I.D[1879071700] = { "Cazador / Cazadora de bandidos", "Brigand-slayer", 106, 0, 0, 5, 500, "Hombres de Bree", "el vigilante de las rutas / la vigilante de las rutas", "Muchas bandas de bandidos deambulan por las tierras salvajes de las Tierras de Bree, emboscando a viajeros y acosando a los habitantes de Bree y de las poblaciones circundantes. Depende de ti contrarrestar la amenaza...", "Many bands of brigands roam the wilds of Bree-land, waylaying travellers and bullying the inhabitants of Bree and the towns surrounding it. It is up to you to counter the threat the brigands pose to the inhabitants of...", "Men of Bree", "Watcher of Roads" }
I.O[1879071700] = { { "Derrota a los bandidos en las Tierras de Bree x30", "Defeat brigands in Bree-land x30", "", "" } }
I.D[1879071701] = { "Cazador / Cazadora de bandidos (Avanzado)", "Brigand-slayer (Advanced)", 106, 0, 2000, 10, 700, "Hombres de Bree", "", "Muchas bandas de bandidos deambulan por las tierras salvajes de las Tierras de Bree, emboscando a viajeros y acosando a los habitantes de Bree y de las poblaciones circundantes. Depende de ti contrarrestar la amenaza...", "Many bands of brigands roam the wilds of Bree-land, waylaying travellers and bullying the inhabitants of Bree and the towns surrounding it. It is up to you to counter the threat the brigands pose to the inhabitants of...", "Men of Bree", "" }
