I.D[1879071702] = { "Leñador / Leñadora de las Tierras de Bree", "Bree-land Woodsman", 106, 10, 0, 5, 500, "Hombres de Bree", "Cortador de raíces / Cortadora de raíces", "Abundan las leyendas sobre el Bosque Viejo. Es un lugar de temor y de espíritu malévolo. Una oscura voluntad llena a los árboles de odio hacia todo aquello que camina sobre dos piernas. Depende de ti aplacar el espíritu...", "Legends of the Old Forest abound. It is a place of fear and malevolent spirit. Some dark will fills the trees with a hatred of all that goes on two legs. It is up to you to quell the Forest's malevolent spirit.", "Men of Bree", "Root-hewer" }
I.O[1879071702] = { { "Derrota a los árboles despiertos en el Bosque Viejo x20", "Defeat awakened trees in the Old Forest x20", "", "" } }
I.D[1879071703] = { "Leñador / Leñadora de las Tierras de Bree (Avanzado)", "Bree-land Woodsman (Advanced)", 106, 10, 2000, 10, 700, "Hombres de Bree", "", "Abundan las leyendas sobre el Bosque Viejo. Es un lugar de temor y de espíritu malévolo. Una oscura voluntad llena a los árboles de odio hacia todo aquello que camina sobre dos piernas. Depende de ti aplacar el espíritu...", "Legends of the Old Forest abound. It is a place of fear and malevolent spirit. Some dark will fills the trees with a hatred of all that goes on two legs. It is up to you to quell the Forest's malevolent spirit.", "Men of Bree", "" }
