I.D[1879071706] = { "Azote de Orcos", "Orc-slayer", 106, 10, 0, 5, 500, "Hombres de Bree", "Defensor de las Tierras de Bree / Defensora de las Tierras de Bree", "Una compañía de orcos ha entrado en las Tierras de Bree desde las Quebradas del Norte, arrasando el campo y destruyendo granjas. Hay que detener el avance de los orcos desde el norte.", "A company of Orcs has passed into Bree-land from the North Downs, ravaging the countryside and razing farms. The advance of the Orcs out of the North must be brought to a halt.", "Men of Bree", "Defender of Bree-land" }
I.O[1879071706] = { { "Derrota a los orcos en las Tierras de Bree x30", "Defeat Orcs in Bree-land x30", "", "" } }
I.D[1879071707] = { "Azote de orcos (avanzado)", "Orc-slayer (Advanced)", 106, 10, 2000, 10, 700, "Hombres de Bree", "", "Una compañía de orcos ha entrado en las Tierras de Bree desde las Quebradas del Norte, arrasando el campo y destruyendo granjas. Hay que detener el avance de los orcos desde el norte.", "A company of Orcs has passed into Bree-land from the North Downs, ravaging the countryside and razing farms. The advance of the Orcs out of the North must be brought to a halt.", "Men of Bree", "" }
