I.D[1879071710] = { "Azote de arañas", "Spider-slayer", 106, 0, 0, 5, 500, "Hombres de Bree", "Cazador de arañas / Cazadora de arañas", "Arañas extrañas y monstruosas han llegado a las Tierras de Bree desde las oscuras zonas del Bosque Negro, más allá de las Montañas Nubladas al este. Tu valor será puesto a prueba contra la infestación de arañas que se...", "Strange, monstrous spiders have crept into Bree-land from the dark corners of Mirkwood, beyond the Misty Mountains in the east. Your courage will be tested against the spider infestation spreading through the forests...", "Men of Bree", "Spider-foe" }
I.O[1879071710] = { { "Derrota arañas en las Tierras de Bree x30", "Defeat spiders in Bree-land x30", "", "" } }
I.D[1879071711] = { "Azote de arañas (avanzado)", "Spider-slayer (Advanced)", 106, 0, 2000, 10, 700, "Hombres de Bree", "", "Arañas extrañas y monstruosas han llegado a las Tierras de Bree desde las oscuras zonas del Bosque Negro, más allá de las Montañas Nubladas al este. Tu valor será puesto a prueba contra la infestación de arañas que se...", "Strange, monstrous spiders have crept into Bree-land from the dark corners of Mirkwood, beyond the Misty Mountains in the east. Your courage will be tested against the spider infestation spreading through the forests...", "Men of Bree", "" }
