I.O[1879071839] = { { "Termina the quest 'El Pájaro y el Bebé' (Has ayudado a Carlo Bosqueoscuro)", "Complete the quest 'The Bird and Baby' (You have aided Carlo Blagrove)", "", "" }, { "Termina the quest 'El Dragón Verde' (Has ayudado a Barmy Nudoraíz y a Gerd Pieblanco)", "Complete the quest 'The Green Dragon' (You have aided Barmy Rootknot and Gerd Whitfoot)", "", "" }, { "Termina the quest 'Posada del Tronco Flotante' (Has ayudado a Ponto Hopsbloom)", "Complete the quest 'The Floating Log' (You have aided Ponto Hopsbloom)", "", "" }, { "Termina the quest 'La Perca Dorada' (Has ayudado a Gunderic Cavada)", "Complete the quest 'The Golden Perch' (You have aided Gunderic Grubb)", "", "" }, { "Termina the quest 'El Arado y las Estrellas' (Has ayudado a Halson Fondocuba)", "Complete the quest 'The Plough and Stars' (You have aided Halson Tubwort)", "", "" } }
I.D[1879084435] = { "Bastiones de esperanza", "Bastions of Hope", 103, 30, 4000, 5, 500, "Concilio del Norte", "", "Incluso en los desiertos arrasados de Angmar, quedan algunos pequeños bastiones de resistencia y valor para luchar contra la oscuridad. Estos puestos avanzados y campamentos se encuentran ocultos y bien defendidos en...", "Even in the blasted wastes of Angmar, there remain a few small bastions of resistance and valour to strive against the darkness. These outposts and camps lie hidden and well-defended in the hills of this dark land,...", "Council of the North", "" }
I.O[1879084435] = { { "Lehmä-koti", "Lehmä-koti", "Lehmä-koti es un pequeño pueblo de los Hijos de la Tierra situado en las profundidades del Ram Dúath. Las fuerzas de Angmar lo han ignorado por el momento, ya que sus ejércitos viajan por el camino...", "Lehmä-koti is a small Earth-kin village tucked within the depths of Ram Dúath. The forces of Angmar have ignored it for the time being as their armies travel the eastern road through these broken..." }, { "Aughaire", "Aughaire", "Los montañeses de Aughaire están jugando un juego peligroso con los poderes de Angmar. Como una de las tribus más grandes e independientes de los montañeses en la región, tienen una influencia...", "The Hillmen of Aughaire are playing a dangerous game with the powers of Angmar. As one of the larger and more independent tribes of Hillmen in the region, they have considerable sway with their..." }, { "Tyrn Lhuig", "Tyrn Lhuig", "Este pequeño campamento está habitado por un grupo de cazadores de Aughaire, y como tal alberga algunas simpatías por los Pueblos Libres de Eriador. Afortunadamente para ellos, este campamento es...", "This small camp is inhabited by a band of hunters out of Aughaire, and as such harbour some sympathies for the Free Peoples of the Eriador. Luckily for them, this camp is far too small to have come..." }, { "Gabilshathûr", "Gabilshathûr", "El puesto de minería de los enanos en Gabilshathûr fue fundado imprudentemente poco antes del reciente renacimiento de los poderes de Angmar. Ahora estas pobres almas están atrapadas, aferrándose a...", "The dwarf mining-outpost of Gabilshathûr was unwisely founded shortly before the recent revival of the powers of Angmar. Now these poor souls are trapped, holding out against hope that they can..." }, { "Gath Forthnír", "Gath Forthnír", "Un pequeño grupo de valientes, que incluye un contingente de montaraces, ha creado un puesto avanzado bien escondido aquí en las puertas de Carn Dûm. Desde aquí, envían espías para vigilar los...", "A small band of brave souls, including a small contingent of Rangers, has created a well-hidden outpost here on the very doorsteps of Carn Dûm. From here, they send spies to watch the movements of..." } }
I.D[1879085025] = { "El círculo de la desesperación", "The Circle of Despair", 103, 30, 2000, 5, 500, "Concilio del Norte", "", "Se rumorea que la antigua fortaleza del Rey Brujo de Angmar está rodeada por ocho torres temibles dentro de las cuales residían sus lugartenientes durante la larga guerra con Arnor, tejiendo su temible magia allí contra...", "The ancient fortress of the Witch-king of Angmar is rumoured to be surrounded by eight dread towers within which his lieutenants resided during the long war with Arnor, weaving their dread magic there against the forces...", "Council of the North", "" }
I.O[1879085025] = { { "Minas Caul", "Minas Caul", "Minas Caul es la torre noroeste del palacio del Rey Brujo. Se rumorea que los otros ocho Nazgûl ocasionalmente residen dentro de estas torres, manejando oscuras brujerías a las órdenes del Rey Brujo.", "Minas Caul is north-west tower of the Witch-king's palace. It is rumoured that the other eight Nazgûl occasionally reside within these towers, wielding dark sorceries at the behest of the Witch-king." }, { "Minas Agar", "Minas Agar", "Minas Agar es la torre occidental del palacio del Rey Brujo. Se rumorea que los otros ocho Nazgûl ocasionalmente residen dentro de estas torres, manejando oscuras brujerías a las órdenes del Rey...", "Minas Agar is the western tower of the Witch-king's palace. It is rumoured that the other eight Nazgûl occasionally reside within these towers, wielding dark sorceries at the behest of the Witch-king." }, { "Minas Maur", "Minas Maur", "Minas Maur es la torre suroeste del palacio del Rey Brujo. Se rumorea que los otros ocho Nazgûl ocasionalmente residen dentro de estas torres, manejando oscuras brujerías a las órdenes del Rey Brujo.", "Minas Maur is the south-west tower of the Witch-king's palace. It is rumoured that the other eight Nazgûl occasionally reside within these towers, wielding dark sorceries at the behest of the..." }, { "Minas Angos", "Minas Angos", "Minas Angos es la torre sur del palacio del Rey Brujo. Se rumorea que los otros ocho Nazgûl ocasionalmente residen dentro de estas torres, manejando oscuras brujerías a las órdenes del Rey Brujo.", "Minas Angos is the southern tower of the Witch-king's palace. It is rumoured that the other eight Nazgûl occasionally reside within these towers, wielding dark sorceries at the behest of the..." }, { "Minas Nîr", "Minas Nîr", "Minas Nîr es la torre noreste del palacio del Rey Brujo. Se rumorea que los otros ocho Nazgûl ocasionalmente residen dentro de estas torres, manejando oscuras brujerías a las órdenes del Rey Brujo.", "Minas Nîr is the north-east tower of the Witch-king's palace. It is rumoured that the other eight Nazgûl occasionally reside within these towers, wielding dark sorceries at the behest of the..." }, { "Minas Deloth", "Minas Deloth", "Minas Deloth es la torre sureste del palacio del Rey Brujo. Se rumorea que los otros ocho Nazgûl ocasionalmente residen dentro de estas torres, manejando oscuras brujerías a las órdenes del Rey Brujo.", "Minas Deloth is the south-east tower of the Witch-king's palace. It is rumoured that the other eight Nazgûl occasionally reside within these towers, wielding dark sorceries at the behest of the..." }, { "Minas Gularan", "Minas Gularan", "Minas Gularan es la torre oriental del palacio del Rey Brujo. Se rumorea que los otros ocho Nazgûl ocasionalmente residen dentro de estas torres, manejando oscuras brujerías a las órdenes del Rey...", "Minas Gularan is the eastern tower of the Witch-king's palace. It is rumoured that the other eight Nazgûl occasionally reside within these towers, wielding dark sorceries at the behest of the..." }, { "Minas Dhem", "Minas Dhem", "Minas Dhem es la torre norte del palacio del Rey Brujo. Se rumorea que los otros ocho Nazgûl ocasionalmente residen dentro de estas torres, manejando oscuras brujerías a las órdenes del Rey Brujo.", "Minas Dhem is the northern tower of the Witch-king's palace. It is rumoured that the other eight Nazgûl occasionally reside within these towers, wielding dark sorceries at the behest of the..." } }
I.D[1879085026] = { "El camino de la guerra", "The Road to War", 103, 30, 4000, 5, 500, "Concilio del Norte", "", "Hay un gran camino que atraviesa las Tierras baldías de Angmar hasta las mismas puertas de Carn Dûm. Es a lo largo de este camino que las oscuras huestes marchan para someter a los Pueblos Libres de Eriador al yugo del...", "There is a great road that leads through the wastes of Angmar to the very gates of Carn Dûm. It is along this road that the dark armies march forth to bring the Free Peoples of Eriador under the yoke of the Enemy.", "Council of the North", "" }
I.O[1879085026] = { { "Skathmúr", "Skathmúr", "El campamento armado de Skathmúr es responsable de patrullar los cañones de Ram Dúath, asegurándose de que estén despejados y el camino bien mantenido para que los ejércitos de Angmar puedan moverse...", "The armed camp of Skathmúr is responsible for patrolling the canyons of Ram Dúath, ensuring that it is clear and the road well-maintained so that Angmar's armies may move undisturbed through its..." }, { "Bail Róva", "Bail Róva", "La fortaleza de Bail Róva domina la salida del Ram Dúath hacia Angmar. Para los ejércitos de Angmar, esta es la última gran fortaleza que atravesarán antes de embarcarse en sus campañas hacia el sur.", "The fortress of Bail Róva commands the exit from Ram Dúath as it spills into Angmar. For the armies of Angmar, this is the last major fortress they will pass through before embarking on their..." }, { "Bail Boglakh", "Bail Boglakh", "Bail Boglakh es un importante campamento de preparación para los ejércitos de Angmar, ya que se reúnen desde las tierras circundantes y avanzan hacia el sur. Sin embargo, incluso los habitantes de...", "Bail Boglakh is a major staging camp for the armies of Angmar as they gather from the surrounding lands and move into the south. Even the inhabitants of this vast encampment avoid the valley to the..." }, { "Mor Maudhúl", "Mor Maudhúl", "Esta torre de vigilancia domina el gran lago de azufre de Duvuinen al sur. Desde aquí, los exploradores y comandantes pueden vigilar las hogueras de los ejércitos reunidos y observar sus movimientos...", "This watch-tower overlooks the great sulfur lake of Duvuinen to the south. From here, scouts and commanders can survey the watch-fires of the gathering armies and observe their movements as they draw..." }, { "Bail Dílas", "Bail Dílas", "Este pequeño campamento actúa como un punto de control por el que deben pasar los viajeros y mensajeros que se dirigen a Carn Dûm antes de acercarse a las grandes puertas de la ciudad.", "This small camp acts as a checkpoint through which travellers and messengers to Carn Dûm must pass before approaching the vast gates of the city." }, { "Puerta de las Sombras", "Gate of Shadows", "La Puerta de las Sombras es la gran puerta exterior de la ciudad fortaleza de Carn Dûm. Abundan las historias sobre los horrores que se encuentran dentro, pero aquí, lejos de la guerra, la pequeña...", "The Gate of Shadows is the vast outer gate of the fortress city of Carn Dûm. Stories abound of the horrors within, but here far from the war the small town settled around the gate might seem almost..." } }
I.D[1879086861] = { "Defensor / Defensora de tumbas", "Tomb-defender", 106, 20, 0, 5, 500, "Los Guardianes de Annúminas", "Guardián de tumbas", "Los saqueadores de tumbas llevan rebuscando desde hace mucho en los ruinosos senderos de Annúminas y las tumbas de los reyes caídos de antaño. Los montaraces del Norte se alían con quienes se alce en armas para mantener...", "Tomb-robbers have long sifted through the ruined paths of Annúminas and the tombs of the fallen Kings of old. The Rangers of the North ally with any who would take up arms to keep these thieves and scoundrels at bay.", "The Wardens of Annúminas", "Tomb-warden" }
I.O[1879086861] = { { "Derrota a los saqueadores de tumbas en Vendim x90", "Defeat tomb-robbers in Evendim x90", "", "" } }
I.D[1879086862] = { "Defensor / Defensora de tumbas (avanzado)", "Tomb-defender (Advanced)", 106, 20, 2000, 10, 700, "Los Guardianes de Annúminas", "", "Aquellos que se atreven a profanar las tumbas de los antiguos Dúnedain se vuelven más atrevidos gracias al caos y al miedo de una guerra que se cierne sobre las tierras del Norte. Alzarse en armas contra estos villanos...", "Those who would defile the tombs of the ancient Dúnedain grow ever bolder as chaos and the fear of war grip the lands of the North. To take up arms against such unprincipled villains is as noble a cause as any.", "The Wardens of Annúminas", "" }
I.O[1879086862] = { { "Termina the deed 'Defensor / Defensora de tumbas'", "Complete the deed 'Tomb-defender'", "", "" }, { "Derrota a los saqueadores de tumbas en Evendim x180", "Defeat tomb-robbers in Evendim x180", "", "" } }
I.D[1879086863] = { "Azote de Limrafn", "Limrafn-slayer", 106, 20, 0, 5, 500, "Los Guardianes de Annúminas", "Guardián de los Misterios", "Los Limrafn son una forma menor y débil de un espíritu malvado. Ni los Elfos pueden afirmar qué es lo que los atrae a Evendim en tal cantidad.", "The Limrafn are a lesser, weaker form of fell spirit. What draws them to Evendim in such numbers, not even the Elves can say.", "The Wardens of Annúminas", "Keeper of Mysteries" }
I.O[1879086863] = { { "Derrota a los Limrafn en Evendim x50", "Defeat Limrafn in Evendim x50", "", "" } }
I.D[1879086864] = { "Azote de Limrafn (avanzado)", "Limrafn-slayer (Advanced)", 106, 20, 2000, 10, 700, "Los Guardianes de Annúminas", "", "Has visto muchas de estas extrañas luces en Evendim últimamente... parecen estar multiplicándose con la presencia de Hombres y otras fuerzas. ¿Es posible que estas extrañas entidades estén siendo despertadas o atraídas...", "You have seen many of these strange lights in Evendim lately -- they seem almost to be multiplying with the presence of Men and other forces. Is it possible that these strange entities are being awakened or attracted by...", "The Wardens of Annúminas", "" }
I.O[1879086864] = { { "Termina the deed 'Azote de Limrafn'", "Complete the deed 'Limrafn-slayer'", "", "" }, { "Derrota a los Limrafn en Evendim x100", "Defeat Limrafn in Evendim x100", "", "" } }
I.D[1879086865] = { "Azote de Gauredain", "Gauradan-slayer", 106, 30, 0, 5, 500, "Los Guardianes de Annúminas", "Azote de los Gauredain", "Las leyendas han hablado desde hace mucho de hombres lobo que acechan en la noche, pero ahora que has conocido a los Gauredain sospechas que conoces más la verdad detrás de estas historias. Si son Hombres, apenas lo son...", "Folk tales have long spoken of werewolves stalking the night -- but now that you have met the Gauredain, you suspect you know more of the truth of these tales. If they are Men, then they are only barely so. They are...", "The Wardens of Annúminas", "Slayer of the Gauredain" }
I.O[1879086865] = { { "Derrota a los Gauredain en Evendim x90", "Defeat Gauredain in Evendim x90", "", "" } }
I.D[1879086866] = { "Azote de Gauredain (avanzado)", "Gauradan-slayer (Advanced)", 106, 30, 2000, 10, 700, "Los Guardianes de Annúminas", "", "Si los Guaredain eran conocidos para los antiguos reyes de Arnor, pocas historias han sobrevivido hasta hoy que hablen de ellos. Más parece que estos Hombres salvajes llegaran a Evendim desde Forochel, en el lejano...", "If the Gauredain were known to the ancient Kings of Arnor, few tales survive to this day that speak of them. More likely it seems that these savage Men wandered down into Evendim from the far north from Forochel.", "The Wardens of Annúminas", "" }
I.O[1879086866] = { { "Termina the deed 'Azote de Gauredain'", "Complete the deed 'Gauradan-slayer'", "", "" }, { "Derrota a los Gauredain en Evendim x180", "Defeat Gauredain in Evendim x180", "", "" } }
I.D[1879086867] = { "Azote de gigantes", "Giant-slayer", 106, 30, 0, 5, 500, "Los Guardianes de Annúminas", "Enemigo de los Gigantes", "Una tribu de gigantes de piedra parece haberse instalado en las colinas del oeste de Evendim. Aunque no son tan grandes en estatura como sus legendarios primos de las Montañas Nubladas, son poderosos oponentes cuando...", "A tribe of Stone-giants appears to have taken up residence in the western hills above Evendim. While not so great in stature as their legendary cousins in the Misty Mountains, they are nevertheless powerful opponents...", "The Wardens of Annúminas", "Enemy of the Giants" }
I.O[1879086867] = { { "Derrota a los gigantes en Evendim x40", "Defeat giants in Evendim x40", "", "" } }
I.D[1879086868] = { "Azote de gigantes (avanzado)", "Giant-slayer (Advanced)", 106, 20, 2000, 10, 700, "Los Guardianes de Annúminas", "", "Nadie parece saber con quienes están aliados los gigantes. De hecho, parece que no sirven nadie salvo a sí mismos dada su caprichosa naturaleza. Sin embargo, si estas tierras caen en manos del Enemigo, los gigantes sin...", "No-one seems to know where the allegiance of the giants lies -- indeed, it seems likely that they serve none but themselves given their capricious nature. Nevertheless, should these lands fall to the Enemy, the giants...", "The Wardens of Annúminas", "" }
I.O[1879086868] = { { "Termina the deed 'Azote de gigantes'", "Complete the deed 'Giant-slayer'", "", "" }, { "Derrota a los gigantes en Evendim x80", "Defeat giants in Evendim x80", "", "" } }
I.D[1879086869] = { "Azote de trasgos", "Goblin-slayer", 106, 20, 0, 5, 500, "Los Guardianes de Annúminas", "Enemigo de los trasgos", "La amenaza de los trasgos parece estar por todas partes estos días, incluso en las fronteras de la misma Comarca. Los rumores dicen que en Evendim hay una nueva raza de estas inmundas criaturas: los extraños boggarts......", "The scourge of the goblins appears to be everywhere these days, even on the borders of the Shire itself. Rumour has it that in Evendim a new breed of the foul creatures can be found in the odd-looking Boggarts --...", "The Wardens of Annúminas", "Goblin-foe" }
I.O[1879086869] = { { "Derrota a los trasgos en Evendim x90", "Defeat goblins in Evendim x90", "", "" } }
I.D[1879086870] = { "Azote de trasgos (avanzado)", "Goblin-slayer (Advanced)", 106, 20, 2000, 10, 700, "Los Guardianes de Annúminas", "", "Parece que los trasgos delsur de Evendim todavía no han llegado en gran número. Quizás solo están aquí para hostigar a la gente de la Comarca y distraer a los Montaraces de objetivos más importantes. Sin embargo, los...", "It seems that the goblins in southern Evendim have not yet come in great numbers, perhaps they are only here to harry the folk of the Shire and distract the Rangers from more important goals elsewhere? Nonetheless, the...", "The Wardens of Annúminas", "" }
I.O[1879086870] = { { "Termina the deed 'Azote de trasgos'", "Complete the deed 'Goblin-slayer'", "", "" }, { "Derrota a los trasgos en Evendim x180", "Defeat goblins in Evendim x180", "", "" } }
I.D[1879086871] = { "Azote de Kergrim", "Kergrim-slayer", 106, 30, 0, 5, 500, "Los Guardianes de Annúminas", "Pesadilla de los Kergrim", "Los Kergrim son otro misterio de las tierras de Evendim. Los montaraces parecen creer que son primos distantes de las bestias de las nieves que habitan en las Montañas Nubladas, pero nadie sabe decir por qué están aquí,...", "The Kergrim are yet another mystery of the lands of Evendim. The Rangers seem to believe that they are a distant cousin of the snow-beasts that range throughout the Misty Mountains, but none can say why they would be...", "The Wardens of Annúminas", "Bane of the Kergrim" }
I.O[1879086871] = { { "Derrota a los Kergrim en Evendim x50", "Defeat Kergrim in Evendim x50", "", "" } }
I.D[1879086872] = { "Azote de Kergrim (avanzado)", "Kergrim-slayer (Advanced)", 106, 30, 2000, 10, 700, "Los Guardianes de Annúminas", "", "Muchos de los inmundos Kergrim parecen haber infestado el valle en el que se encuentran las tumbas de los antiguos reyes Dúnedain. No hay duda de que los Montaraces del Norte están enfurecidos por la posible profanación...", "Many of the foul Kergrim appear to have infested the valley in which the tombs of the ancient Dúnedain kings can be found. No doubt the Rangers of the North are enraged by the potential desecration of their ancestors'...", "The Wardens of Annúminas", "" }
I.O[1879086872] = { { "Termina the deed 'Azote de Kergrim'", "Complete the deed 'Kergrim-slayer'", "", "" }, { "Derrota a los Kergrim en Evendim x100", "Defeat Kergrim in Evendim x100", "", "" } }
I.D[1879086873] = { "Azote de salamandras", "Salamander-slayer", 106, 20, 0, 5, 500, "Los Guardianes de Annúminas", "Apagador de Llamas", "Las salamandras de Evendim siempre han sido difíciles de encontrar. Esta extraña ramificación de la famlia de los dragones tiene una gran afinidad con el fuego, que desata sin control contra cualquier enemigo que ose...", "The Salamanders of Evendim have always been a rare sight. This odd offshoot of the family of dragons has a strong affinity for fire, which it wields with abandon against any enemy that disturbs it.", "The Wardens of Annúminas", "Quencher of Flames" }
I.O[1879086873] = { { "Derrota a las salamandras en Evendim x90", "Defeat Salamanders in Evendim x90", "", "" } }
I.D[1879086874] = { "Azote de salamandras (avanzado)", "Salamander-slayer (Advanced)", 106, 20, 2000, 10, 700, "Los Guardianes de Annúminas", "", "Extrañamente, las salamandras se encuentran frecuentemente cerca de masas de agua como ríos o lagos, aunque también se las puede encontrar en ciénagas pantanosas o desiertos de arena. Los eruditos creen que esto pueda...", "Oddly, Salamanders are frequently found near bodies of water such as rivers or lakes -- though they may also be found in wet marshes or sandy deserts. Scholars believe this may be because of the creature's tendency to...", "The Wardens of Annúminas", "" }
I.O[1879086874] = { { "Termina the deed 'Azote de salamandras'", "Complete the deed 'Salamander-slayer'", "", "" }, { "Derrota a las salamandras en Evendim x180", "Defeat Salamanders in Evendim x180", "", "" } }
I.D[1879089144] = { "Tumbas de Evendim", "Tombs of Evendim", 103, 30, 2000, 5, 500, "Los Guardianes de Annúminas", "", "Los reyes de Annúminas fueron enterrados en tumbas a lo largo del camino a la puerta de la ciudad. Nueve fueron reyes que gobernaron sobre Arnor desde su trono en esta ciudad, pero no todos fueron enterrados en el...", "The kings of Annúminas were intered within tombs along the road to the gate of the city. Nine were the kings that ruled over Arnor from this ancient seat of power, but not all of them were buried in the Way of Kings...", "The Wardens of Annúminas", "" }
I.O[1879089144] = { { "Haudh Eärendur", "Haudh Eärendur", "La tumba de Eärendur, hijo de Elendur. Eärendur fue el décimo y último rey de los reyes de Arnor. Tras su muerte, el reino de Arnor se dividió entre sus hijos en los reinos de Arthedain, Cardolan y...", "The tomb of Eärendur, son of Elendur. Eärendur was the tenth and last of the Kings of Arnor - after his death the kindgom of Arnor was divided by his contending sons into the kingdoms of Arthedain,..." }, { "Haudh Elendur", "Haudh Elendur", "La tumba de Elendir, hijo de Valandur. Como el noveno reino de Arnor, Elendur tuvo uno de los más largos reinados de todos, gobernando a la gente de Arnor durante ciento veinticinco años.", "The tomb of Elendur, son of Valandur. As the ninth king of Arnor Elendur had one of the longest and most enduring reigns of all, ruling over the people of Arnor for one hundred and twenty five years." }, { "Haudh Valandur", "Haudh Valandur", "La tumba de Valandur, hijo de Tarondor. La historia no menciona mucho al octavo rey de Arnor, excepto por su muerte violenta en misteriosas circunstancias alrededor del quincuagésimo año de su...", "The tomb of Valandur, son of Tarondor. History mentions relatively little about the eighth king of Arnor, except that he is said to have died in violent and mysterious circumstances sometime around..." }, { "Haudh Elendil", "Haudh Elendil", "La tumba de Elendil, hijo de Amandil. Elendil fue el primer rey y fundador del reino de Arnor, adonde había huido cuando llegó a la Tierra Media escapando de la gran ruina de Númenor. Elendil luchó...", "The tomb of Elendil, son of Amandil. Elendil was the first and founding King of Arnor, whither he had fled into Middle-earth from the great ruin of Númenor. Elendil fought alongside Gil-galad as the..." }, { "Haudh Tarondor", "Haudh Tarondor", "La tumba de Tarondor, hijo de Tarcil. El reinado del séptimo rey de Arnor fue marcado por una época de paz relativa, ya que la contienda que consumiría y con el tiempo destruiría los Reinos del Norte...", "The tomb of Tarondor, son of Tarcil. The reign of the seventh king of Arnor was marked by a time of comparative peace, for the strife that would consume and in time destroy the Kingdoms of the North..." }, { "Haudh Eldacar", "Haudh Eldacar", "La tumba de Eldacar, hijo de Valandil. Eldacar gobernó como cuarto rey de Arnor, y fue el nieto de Isildur. Se cree que Eldacar reinó durante una época de paz que se extendía desde la derrota de...", "The tomb of Eldacar, son of Valandil. Eldacar ruled as the fourth king of Arnor, and was the direct grandson of Isildur himself. It is believed that Eldacar ruled during a time of peace that extended..." }, { "Haudh Tarcil", "Haudh Tarcil", "La tumba de Tarcil, hijo de Arantar. Tarcil fue el sexto rey de Arnor y su reinado duró aproximadamente ochenta años antes de que la corona pasara a su hijo, Tarondor.", "The tomb of Tarcil, son of Arantar. Tarcil was the sixth king of Arnor and his reign lasted for about eighty years before the crown passed to his son, Tarondor." }, { "Haudh Arantar", "Haudh Arantar", "La tumba de Arantar, hijo de Eldacar. Aunque se dice que el reinado del quinto rey de Arnor duró casi un siglo, la mayoría de los registros de esta época se perdieron en la caída de los Reinos del...", "The tomb of Arantar, son of Eldacar. Though the reign of the fifth King of Arnor was said to last for nearly a century, most of the records of this time were lost in the eventual fall of the Northern..." } }
I.D[1879089145] = { "Ruinas de Evendim", "Ruins of Evendim", 103, 30, 2000, 5, 500, "Los Guardianes de Annúminas", "", "Explora las ruinas de la antigua Arnor.", "Explore the ruins of ancient Arnor.", "The Wardens of Annúminas", "" }
I.O[1879089145] = { { "Tham Nambarth", "Tham Nambarth", "Varias de las grandes familias de Annúminas construyeron mansiones palaciegas en las colinas de los Campos de Evendim, mostrando su riqueza y prosperidad a lo largo y ancho de la región,...", "Several of the great families of Annúminas constructed palatial estates upon the rolling hills of the Evendim Fields, displaying their wealth and prosperity far and wide and providing them summer..." }, { "Tham Varan", "Tham Varan", "El dominio de Tham Varan perteneció una vez a una de las más antiguas y prestigiosas familias de Annúminas. Eran conocidos por largas y a veces extrañas contiendas por conseguir influencia en las...", "The estate of Tham Varan once belonged to one of the oldest and most prestigious families of Annúminas. They were known for a long and, at times, strange contest for influence in the royal courts of..." }, { "Ost Heryn", "Ost Heryn", "Originalmente construida como una fortaleza para controlar el acceso a los Campos de Evendim desde el este, Ost Heryn se permitió languidecer durante los largos periodos de paz que caracterizaban a...", "Originally built as a fortress to oversee the approach to the Fields of Evendim from the east, Ost Heryn was allowed to languish during the long periods of peace that characterized those times. It..." }, { "Tham Andalath", "Tham Andalath", "Construida durante el apogeo de Annúminas y su influencia en el Norte, los dominios de Tham Andalath se convirtieron en los más extensos de los Campos de Evendim. Pronto fue conocido como un símbolo...", "Constructed during the height of Annúminas' influence and wealth in the North, the estate of Tham Andalath became the largest in the Evendim Fields. It quickly became known as a symbol of upstart..." }, { "Tham Ornen", "Tham Ornen", "La más pequeña de las grandes casas de Arnor construyó su palacio aquí, en Tham Ornen. Aunque no podían reclamar la riqueza o el poder de otras casas, se dice que esta famlia tenía estrechos lazos...", "The smallest of the great houses of Arnor built their estate here at Tham Ornen. While they could not claim the wealth or power of the other houses, it is said that this family had close ties with..." }, { "Barad Rath", "Barad Rath", "Construido antes de la fundación original de Ost Forod, Barad Rath una vez delimitaba la frontera más al norte de la región del lago Evendim. Una vez que Ost Forod alcanzó la preeminencia en el...", "Constructed before the original founding of Ost Forod, Barad Rath once stood as the furthest northern frontier in the region of Lake Evendim. Once Ost Forod rose to pre-eminence in the north Barad..." }, { "Rantost", "Rantost", "Dadas las evidencias de las hermosas y extensas estructuras que antaño se erigieron en la isla de Rantost, es extraño que no se las mencionen en las historias de Arnor. Es posible que alguna familia...", "Given the evidence of the beautiful and extensive structures once built on the island of Rantost, it is strangely devoid of mention in the histories of Arnor. It is possible that some powerful family..." }, { "Tollobel", "Tollobel", "Aisladas por el lago de la mayoría de otros dominios y ruinas de Evendim, pocos eruditos conocen a ciencia cierta la naturaleza de las ruinas que hoy se hallan aquí. Las principales teorías sugieren...", "Isolated by the lake from most of the other estates and ruins of Evendim, few scholars are certain of the nature of the ruins that lie there today. The foremost theories suggest that it may have once..." } }
I.D[1879089146] = { "Tierras salvajes de Evendim", "Wilds of Evendim", 103, 30, 2000, 5, 500, "Los Guardianes de Annúminas", "", "Una vez la capital del Norte, Evendim siempre ha sido una región salvaje y llena de misterios... que respectivamente se han vuelto más peligrosas y extraños aun tras los largos años que han pasado desde que Annúminas...", "Once the capital of the North, Evendim has nonetheless always had its wild places and mysteries -- and those have grown stranger and more dangerous still in the long years since Annúminas was abandoned. Far across the...", "The Wardens of Annúminas", "" }
I.O[1879089146] = { { "Nan Orngon", "Nan Orngon", "Nan Orngon es una gran promontorio de piedra descubierto por los colonos originales de Evendim hace mucho. Aunque su posición, que domina los senderos hacia los Campos de Fornost, podría haberle...", "Nan Orngon is a great stone outcropping discovered by the original settlers of Evendim long ago. While its position overlooking the paths into the Fields of Fornost might have afforded it some..." }, { "Tûm Fuin", "Tûm Fuin", "El valle de Tûm Fuin y sus alrededores son conocidos por ser un lugar predilecto para cazadores y tramperos de Ost Forod. Se encuentra muy alejado de las rutas transitadas y cuenta con abundante...", "The valley of Tûm Fuin and its surroundings are known to be a favourite haunt of local trappers and hunters out of Ost Forod. It lies well off the beaten path and has an abundance of local wildlife -..." }, { "Los Saltos del Crepúsculo", "The Even-rills", "Los Saltos del Crepúsculo son una serie de estanques y caídas de agua conectados, alimentados por el deshielo de las montañas al norte del lago Evendim. Son tan fríos como el hielo incluso en los...", "The Even-rills are a series of connected pools and falls fed by ice melting high in the mountains north of Lake Evendim. They are as frigid as ice even on the warmest days of summer, and bands of..." }, { "Las Agujas de la Linde", "The Eavespires", "Pocos cazadores o tramperos llegan tan hacia el oeste de Ost Forod. Los relatos hablan de árboles que caminan y osos que construyen casas en estas remotas tierras salvajes. Aunque hay poco de verdad...", "Few hunters or trappers come this far west of Ost Forod - tales speak of trees that walk and bears that build houses in these remote wilds. While there is little truth to most of these fanciful..." }, { "La Laguna de la Linde", "The Eave-mere", "La Laguna de la Linde representa el tramo inferior del mayor afluente del lago Evendim. Alimentada por rápidos que llegan desde la montaña y descienden en grandes caídas hacia el lago, la laguna es...", "The Eave-mere represents the lower stretch of the largest tributary to lake Evendim. Fed by rapids from higher up the mountain and crashing down in great falls towards the lake below, the mere itself..." }, { "Arroyo Veloz", "Swiftbrook", "Este arroyo frío y aislado se interna profundamente en la roca de las montañas en lo alto del lado oeste del lago Evendim, antes de descender en tumultuosos rápidos a la Laguna de la Linde y de ahí...", "This cold and isolated stream cuts deeply through the rock of the mountains high above the western side of Lake Evendim before descending through tumultuous rapids to the Eave-mere below and thence..." }, { "La Arboleda Retorcida", "The Twisted Grove", "La Arboleda Retorcida es un lugar oscuro e inquietante, que se encuentra en las tierras salvajes más hacia el oeste del lago Evendim. Incluso durante el reinado de los reyes de Arnor, era considerado...", "The Twisted Grove is a dark and forboding place, set in the deepest wilds west of Lake Evendim. Even during the reign of the Kings of Arnor, it was considered an unlucky place and was avoided by..." }, { "Valcorriente", "Rushingdale", "Aunque no era visitada frecuentemente incluso en los tiempos de Arnor, el estanque conocido como Valcorriente era reverenciado por la gente local quien dejaba ofrendas flotantes en la orilla de sus...", "Though visited infrequently even in the time of Arnor, the pool now known as the Rushingdale was held in reverence by the local people who would leave offerings floating upon the edge of the waters...." } }
I.D[1879099039] = { "Las Alturas Aterradoras", "The Forbidding Heights", 103, 30, 2000, 5, 500, "Elfos de Rivendel", "", "Aunque la mayoría de la gente sensata se queda en casa cuidando campos y talleres, algunos aventureros resistentes se sienten atraídos por los lugares más inhóspitos y difíciles de la Tierra Media. Pocos lugares...", "While most folks sensibly stay home and tend to fields and shops, some hardy adventurers are drawn to the most inhospitable and difficult places in Middle-earth. Few such places pose so great a challenge as the stretch...", "Elves of Rivendell", "" }
I.O[1879099039] = { { "Cirith Daur", "Cirith Daur", "Cirith Daur fue en tiempos uno de los pasos principales que usaban los viajeros para entrar al Paso Alto. Incluso en los mejores días, está azotado por vientos y tormentas y es traicionero de cruzar....", "Cirith Daur was once one of the major passes that travellers used to enter the High Pass. Even at the best of times, it is torn by winds and storms and is treacherous to pass through. It often..." }, { "La Grieta Negra", "The Black Crack", "Esta pequeña cueva en las rocas del Paso Alto ofrece un aparente refugio para los viajeros en tiempos de tormenta, pero hace mucho se descubrió que es una entrada oculta a las madrigueras de la...", "This small cave in the rocks of the High Pass offers apparent shelter for travellers in times of storm, but it was long ago discovered to be a concealed entrance into the burrows of Goblin-town..." }, { "Dómstoll", "Dómstoll", "Dómstoll —llamado con mayor frecuencia el Trono del Gigante en oestron— es un enorme asiento de piedras masivas que se alza sobre las ruinas abandonadas de Starkhath y ofrece una vista dominante de...", "Dómstoll -- more often called the Giant's Throne in Westron -- is a great seat of massive stones that sits above the abandoned ruins of Starkhath and offers a domineering view of the surrounding..." }, { "Fisura de Erforgh", "Erforgh Cleft", "La Fisura de Erforgh es un enorme caos de rocas y arroyos congelados, dejado atrás por una gran masa de hielo en eras pasadas. Ahora ofrece algo de refugio contra los vientos montañosos más brutales...", "The Erforgh Cleft is a massive jumble of rocks and frozen streams left behind by some great mass of ice in ages past. Now it offers some semblance of shelter from the most brutal mountain winds to a..." }, { "Serpentinos", "Writhenbores", "Este complejo de cavernas llamado los Serpentinos parece estar formado por una gran masa de peñascos, demasiado grandes incluso para que los gigantes pudieran levantarlos. Cómo llegaron a estar así...", "This complex of caves called the Writhenbores seems to be formed by a great mass of boulders, larger than even the giants could hope to lift. How they came to be this way is a mystery -- perhaps by..." }, { "Starkhath", "Starkhath", "Un grupo de viajeros que pasó por aquí hace muchos años describió un lugar donde los gigantes arrojaban peñascos a través del paso por diversión. Los gigantes parecen haber desaparecido ahora...", "A group of travellers who passed this way many years ago described a place where giants capriciously tossed boulders across the pass for sport and amusement. The giants appear to be gone now -- some..." }, { "Hrimbarg", "Hrimbarg", "Fundado antes que la ciudad de Helegrod, Hrimbarg fue llamado en su día “La Corona de las Montañas Nubladas” por los enanos que vivían allí, y era considerado la morada más elevada de su pueblo en...", "Founded before the city of Helegrod, Hrimbarg was once called 'The Crown of the Misty Mountains' by the dwarves who lived there, and they marked it as the highest dwelling of their people in all the..." }, { "Akûltot", "Akûltot", "Construido recientemente desde la ascensión del nuevo Gran Trasgo de la Ciudad de los Trasgos, el campamento de Akûltot se sitúa entre repisas y agujas de roca que dominan la aproximación a las...", "Newly built since the ascension of the new Great Goblin of Goblin-town, the camp of Akûltot is set among rock ledges and spires that overlook the approach to the main gates of Goblin-town...." } }
I.D[1879099041] = { "Las Tierras Salvajes de Tâl Bruinen", "The Wilds of Tâl Bruinen", 103, 30, 2000, 10, 500, "Elfos de Rivendel", "", "El sur del Bosque de los Trolls está dominado por las Tierras Salvajes de Tâl Bruinen. Son pocos los que viven aquí ahora, incluso entre los Elfos, y las colinas boscosas se han vuelto densas y cubiertas de maleza,...", "The southern Trollshaws are dominated by the Wilds of Tâl Bruinen. Few even amongst the Elves live here now, and the forested hills have become heavily overgrown and inhabited mostly by wild beasts that pose a constant...", "Elves of Rivendell", "" }
I.O[1879099041] = { { "Cirith Ulunn", "Cirith Ulunn", "Aunque pueden encontrarse sierpes dispersos en otras zonas del Bosque de los Trolls, la estirpe que vive aquí se ha vuelto especialmente numerosa y mortal. En verdad, los instintos de caza agresivos...", "Though worms can be found scattered in other areas of the Trollshaws, the breed here has grown particularly deadly and numerous. Indeed, the aggressive hunting instincts of these vicious beasts do a..." }, { "Echad Candelleth", "Echad Candelleth", "Se cree entre los eruditos que la ruina de Echad Candelleth fue en tiempos un centro de arte y aprendizaje en el antiguo reino de Rhudaur, antes de caer bajo la influencia corrupta de Angmar y ser...", "The ruin of Echad Candelleth is believed by scholars to have once been a centre of art and learning in the ancient kingdom of Rhudaur, before it fell beneath the corrupt sway of Angmar and was..." }, { "Eryn Singor", "Eryn Singor", "Aunque es un espectáculo digno de contemplar, los viajeros que se dejan seducir por la belleza natural de Eryn Singor rara vez emergen de sus traicioneros barrancos. Una hueste de trolls silvanos ha...", "Though it is a wonder to behold, travellers who allow themselves to be lulled by the natural beauty of Eryn Singor rarely emerge from its treacherous ravines. A host of deadly Wood-trolls have taken..." }, { "Echad Gauradan", "Echad Gauradan", "Aunque los hombres civilizados abandonaron estas colinas hace mucho tiempo, una tribu de hombres salvajes se ha asentado aquí recientemente, y parecen sentirse en casa entre las bestias peligrosas y...", "While civilized men long ago quit these hills, a tribe of wild men have recently taken up residence here, seemingly at home amongst the dangerous beasts and natural hazards of the region. Alas, they..." }, { "Torech Ullug", "Torech Ullug", "Se dice que existe un área de anidación para los numerosos sierpes que infestan Tâl Bruinen, y parece que has tropezado con ella aquí, en Torech Ullug. ¡Ten cuidado! Las madres de los gusanos...", "It is said that there is a nesting area for the numerous worms who infest Tal Bruinen, and it would seem that you have stumbled upon it here at Torech Ullug. Take care! The mothers of nesting worms..." }, { "Delossad", "Delossad", "¿Qué son estas extrañas ruinas? Parecen de antiguas raíces cardolanas, pero los Elfos de Rivendel se muestran reacios a hablar de ellas. Algún extraño misterio las rodea, y puede que las únicas...", "What are these strange ruins? They seem to be of ancient Cardolan origins, but the Elves of Rivendell seem hesitant to speak of them at all. Some strange mystery surrounds them, and it may be that..." } }
