I.D[1879103870] = { "Las siete espadas", "The Seven Swords", 104, 40, 0, 10, 500, "Concilio del Norte", "Sabio de Rhudaur", "Siete espadas han sido robadas de Kruslë Lannan y deben ser devueltas a su lugar de descanso.", "Seven swords have been stolen from Krúslë Lannan and must be returned to their proper resting place.", "Council of the North", "Sage of Rhudaur" }
I.O[1879103870] = { { "Termina the quest 'La espada de Abb' (Recupera la espada de Abb de Owen)", "Complete the quest 'The Sword of Abb' (Recover the Sword of Abb from Owen)", "", "" }, { "Termina the quest 'La espada de Kolmak' (Recupera la espada de Kolmak de Ruraikh)", "Complete the quest 'The Sword of Kolmak' (Recover the Sword of Kolmak from Ruraikh)", "", "" }, { "Termina the quest 'La espada de Anraig' (Recupera la espada de Anraig de Tobaid)", "Complete the quest 'The Sword of Ánraig' (Recover the sword of Ánraig from Tobaid)", "", "" }, { "Termina the quest 'La espada de Guinokh' (Recupera la espada de Guinokh de Brekhin)", "Complete the quest 'The Sword of Guinokh' (Recover the sword of Guinokh from Brekhin)", "", "" }, { "Termina the quest 'La espada de Innis' (Recupera la espada de Innis de Dugald)", "Complete the quest 'The Sword of Innis' (Recover the sword of Innis from Dugald)", "", "" }, { "Termina the quest 'La espada de Kevoka' (Recupera la espada de Kevoka de Frangan)", "Complete the quest 'The Sword of Kevoka' (Recover the sword of Kevoka from Frangan)", "", "" }, { "Termina the quest 'La espada de Mánas' (Recupera la espada de Mánas de Huisdán)", "Complete the quest 'The Sword of Mánas' (Recover the sword of Mánas from Huisdán)", "", "" } }
I.D[1879109786] = { "La batalla de Forochel", "The Battle for Forochel", 103, 30, 2000, 5, 500, "Lossoth de Forochel", "", "Descubre cada uno de los campos de batalla clave para controlar la Bahía de Hielo de Forochel.", "Discover each of the key battlegrounds for control of the Ice Bay of Forochel.", "Lossoth of Forochel", "" }
I.O[1879109786] = { { "Hylje-leiri", "Hylje-leiri", "Forochel está salpicado de muchos pequeños campamentos de caza, incluyendo Hylje-leiri, el Campamento de la Foca.", "Forochel is dotted with many small hunting-camps, including Hylje-leiri, the Camp of the Seal." }, { "Karhu-leiri", "Karhu-leiri", "Karhu-leiri, el Campamento del Oso, es uno de los muchos campamentos de caza de los Lossoth repartidos por Forochel.", "Karhu-leiri, the Camp of the Bear, is one of many Lossoth hunting-camps spread across Forochel." }, { "Pynti-leiri", "Pynti-leiri", "Pynti-leiri, el Campamento de la Caza, es uno de los campamentos más populares de los Lossoth.", "Pynti-leiri, the Camp of the Hunt, is one of the more popular hunting-camps of the Lossoth." }, { "Norsu-leiri", "Norsu-leiri", "Norsu-leiri, el Campamento de los Mamuts, fue establecido por los Lossoth como un lugar desde el cual cazar a los mamuts nativos.", "Norsu-leiri, the Camp of the Mammoth, was established by the Lossoth as a place from which to hunt the native mammoths." } }
I.D[1879109787] = { "Piedras Antiguas de Forochel", "Ancient Stones of Forochel", 103, 30, 2000, 5, 500, "Lossoth de Forochel", "", "Aunque los Lossoth de Forochel no son grandes constructores, los enanos tuvieron hace mucho tiempo muchas minas y campamentos en el Norte.", "While the Lossoth of Forochel are not great builders, the dwarves long ago had many mines and encampments in the North.", "Lossoth of Forochel", "" }
I.O[1879109787] = { { "Kibilzahar", "Kibilzahar", "En aquella época en que los enanos extraían minerales de los peñascos y acantilados de Forochel, construyeron muchas fortalezas. Kibilzahar es uno de esos lugares, aunque ha sido abandonado hace...", "In an age when dwarves mined the crags and bluffs of Forochel, they built many fortresses. Kibilzahar is one such place, though it has been long abandoned. Rumour has it that fell spirits now dwell..." }, { "El Umbral de Hierro", "The Ironspan", "El Umbral de Hierro fue construido por los enanos hace mucho tiempo, mientras buscaban metales preciosos y gemas en las montañas de Forochel y Angmar. Cuando los enanos abandonaron sus esfuerzos, el...", "The Ironspan was built by the dwarves long ago, as they sought precious metals and gems in the mountains of Forochel and Angmar. When the dwarves abandoned their endeavours, the Witch-realm of Angmar..." }, { "Zigilgund", "Zigilgund", "Zigilgund es un antiguo sitio enano al que los Barbiluengos regresaron hace poco.", "Zigilgund is an ancient dwarf-site to which the Longbeards have only recently returned." }, { "The Lonesome Stones", "The Lonesome Stones", "Las Piedras Solitarias son un recordatorio cansado y arruinado de días antiguos cuando los enanos extraían minerales de los peñascos de Forochel.", "The Lonesome Stones are a weary and ruined reminder of ancient days when dwarves mined the crags of Forochel." }, { "Minas de Arrancahielo", "Icereave Mines", "Las Minas de Arrancahielo permanecieron largo tiempo sin usar, pero ahora los Duramano buscan utilizarlas para su propio beneficio.", "The Icereave Mines long stood unused, but now the Dourhands seek to use them for their own benefit." } }
I.D[1879109791] = { "Azote de Angmarim", "Angmarim-slayer", 106, 30, 0, 5, 500, "Lossoth de Forochel", "Pesadilla de Angmar", "Parece que los dedos oscuros de Angmar se han extendido incluso al desolado Forochel, sembrando las semillas del conflicto aquí como en todos los lugares que tocan. Aquí al menos, parece que sus preparativos no están...", "So it seems that the shadowy fingers of Angmar have stretched even into desolate Forochel, sewing the seeds of conflict here as in all places they touch. Here at least, it seems that their preparations are less ready...", "Lossoth of Forochel", "Angmar's Bane" }
I.O[1879109791] = { { "Derrota Angmarim en Forochel x100", "Defeat Angmarim in Forochel x100", "", "" } }
I.D[1879109792] = { "Azote de Angmarim (avanzado)", "Angmarim-slayer (Advanced)", 106, 30, 2000, 10, 700, "Lossoth de Forochel", "", "Parece que en el mejor de los casos los Angmarim están buscando algo, o quizá simplemente mezclando en los conflictos entre los Lossoth y los Gauredain. No parece que sea su propósito una invasión a toda fuerza en...", "It seems that the Angmarim may at best be searching for something, or perhaps simply meddling in the conflicts between the Lossoth and the Gauredain. A full-strength invasion does not seem to be their purpose in...", "Lossoth of Forochel", "" }
I.O[1879109792] = { { "Termina the deed 'Azote de Angmarim'", "Complete the deed 'Angmarim-slayer'", "", "" }, { "Derrota Angmarim en Forochel x200", "Defeat Angmarim in Forochel x200", "", "" } }
I.D[1879109793] = { "Azote de Duramano", "Dourhand-slayer", 106, 30, 0, 5, 500, "Lossoth de Forochel", "Vigilante de las Minas", "Las antiguas ruinas enanas salpican el paisaje de Forochel. Siendo los más resistentes de los Pueblos Libres, los enanos afirman que fueron los primeros en asentarse aquí hace mucho tiempo, con la esperanza de encontrar...", "Old dwarf-ruins litter the landscape of Forochel. Being the hardiest of the Free Peoples, the dwarves claim that they were the first to settle here long ago, in hopes of finding riches beneath the frozen earth -- but...", "Lossoth of Forochel", "Warden of the Mines" }
I.O[1879109793] = { { "Derrota Duramano en Forochel x100", "Defeat Dourhands in Forochel x100", "", "" } }
I.D[1879109794] = { "Azote de Duramano (Avanzado)", "Dourhand-slayer (Advanced)", 106, 30, 2000, 10, 700, "Lossoth de Forochel", "", "Los intentos de los Duramano de reclamar un descenso legítimo de los Señores Enanos de antaño parecen inútiles en este punto, pues su alianza oscura con Angmar se convierte en conocimiento más común entre los enanos de...", "The attempts by the Dourhands to claim a legitimate descent from the Dwarf-lords of old seems futile at this point, as their dark alliance with Angmar becomes more common knowledge among the dwarves of Middle-earth --...", "Lossoth of Forochel", "" }
I.O[1879109794] = { { "Termina the deed 'Azote de Duramano'", "Complete the deed 'Dourhand-slayer'", "", "" }, { "Derrota Duramano en Forochel x200", "Defeat Dourhands in Forochel x200", "", "" } }
I.D[1879109795] = { "Azote de Gauredain", "Gauradan-slayer", 106, 30, 0, 5, 500, "Lossoth de Forochel", "Repulsor de Salvajes", "Finalmente llegaste a la tierra natal de los Gauredain -- y viendola, se hace claro cómo llegaron a ser tales brutos poderosos, moldeados por los elementos vicios y las penurias del Forochel, es difícil imaginarselos de...", "At last you have come upon the homeland of the Gauredain -- and in seeing it, it becomes clear how they came to be such powerful brutes, shaped by the vicious elements and hardships of Forochel, it is hard to imagine...", "Lossoth of Forochel", "Repulser of Savages" }
I.O[1879109795] = { { "Derrota Gauredain en Forochel x100", "Defeat Gauredain in Forochel x100", "", "" } }
I.D[1879109796] = { "Azote de Gauredain (avanzado)", "Gauradan-slayer (Advanced)", 106, 30, 2000, 10, 700, "Lossoth de Forochel", "", "Parece ciertamente extraño que dos pueblos como los Gauredain y los Lossoth luchen por reclamar una tierra tan perdida y difícil como Forochel, y sin embargo se esfuerzan sin cesar por ella. Parece que el hogar es el...", "It seems odd indeed that two people such as the Gauredain and the Lossoth should do battle to claim such a forbidding and difficult land as Forochel, and yet they strive endlessly over it. It seems that home is the...", "Lossoth of Forochel", "" }
I.O[1879109796] = { { "Termina the deed 'Azote de Gauredain'", "Complete the deed 'Gauradan-slayer'", "", "" }, { "Derrota Gauredain en Forochel x200", "Defeat Gauredain in Forochel x200", "", "" } }
I.D[1879109797] = { "Azote de Sombríos", "Grim-slayer", 106, 30, 0, 5, 500, "Lossoth de Forochel", "el Desgarrador de Hielo", "Los Gauredain creen que los Macabras son las almas errantes de los de su pueblo que fueron expulsados por su cobardía, condenados a vagar eternamente por los campos de nieve congelada después de morir congelados en el...", "The Gauredain believe that the grims are the wandering souls of those among their people who were cast out for their cowardice, damned to eternally wander the frozen snow-fields after they froze to death in the ice....", "Lossoth of Forochel", "the Ice-render" }
I.O[1879109797] = { { "Derrota Sombríos en Forochel x40", "Defeat grims in Forochel x40", "", "" } }
I.D[1879109798] = { "Azote de Sombríos (Avanzado)", "Grim-slayer (Advanced)", 106, 30, 2000, 10, 700, "Lossoth de Forochel", "", "Si hay el más mínimo rastro de un espíritu que alguna vez vivió dentro del Sombrío, parece que no es suficiente para mostrar ninguna señal de compañía o piedad. Al más mínimo signo de calor o vida atacan, aparentemente...", "If there is the slightest trace of a once-living spirit within the grim, it would seem that it is not enough to show any sign of compassion or mercy. At the slightest sign of warmth or life they strike, seemingly intent...", "Lossoth of Forochel", "" }
I.O[1879109798] = { { "Termina the deed 'Azote de Sombríos'", "Complete the deed 'Grim-slayer'", "", "" }, { "Derrota Sombríos en Forochel x80", "Defeat grims in Forochel x80", "", "" } }
I.D[1879109799] = { "Azote de Colmillo de Sable", "Sabre-tooth Slayer", 106, 30, 0, 5, 500, "Lossoth de Forochel", "Rompe-colmillos", "Estos gatos salvajes son depredadores de naturaleza particularmente viciosa e indiscriminada. Los Lossoth se aseguran de respetar su territorio durante la caza, para no convertirse en comida de estas criaturas mortales....", "These savage cats are predators of a particularly vicious and undiscerning nature. The Lossoth make sure to respect their territory during the hunt, lest they become a meal for these deadly creatures. Likewise what...", "Lossoth of Forochel", "Fang-breaker" }
I.O[1879109799] = { { "Derrota Colmillos de Sable en Forochel x100", "Defeat sabre-tooths in Forochel x100", "", "" } }
I.D[1879109800] = { "Azote de Colmillo de Sable (Avanzado)", "Sabre-tooth Slayer (Advanced)", 106, 30, 2000, 10, 700, "Lossoth de Forochel", "", "Los gatos Colmillo de Sable son un peligro frecuente y mortal de los bosques de Forochel. Solo los cazadores más valientes entre los Lossoth se atreven a cazar en las proximidades de una guarda de Colmillo de Sable, e...", "The sabre-tooth cats are a deadly and frequent hazard of the forests of Forochel. Only the bravest hunters amongst the Lossoth will dare to hunt in the vicinity of a Sabertooth den, and even they occasionally fail to...", "Lossoth of Forochel", "" }
I.O[1879109800] = { { "Termina the deed 'Azote de Colmillo de Sable'", "Complete the deed 'Sabre-tooth Slayer'", "", "" }, { "Derrota Colmillo de Sable en Forochel x200", "Defeat sabre-tooth in Forochel x200", "", "" } }
I.D[1879109801] = { "Azote de sierpes", "Worm-slayer", 106, 30, 0, 5, 500, "Lossoth de Forochel", "Ira del Invierno", "Los sierpes de Forochel se han adaptado al ambiente eternamente frío, creciendo con un abrigo de escamas extrañamente peludas para protegerse del frío, mientras que sus garras y dientes llevan un frío extraño propio, a...", "The Worms of Forochel have adapted to the eternally cold environment, growing a coat of strangely-furred scales to ward off the cold, while their claws and teeth carry a strange cold of their own, often causing those...", "Lossoth of Forochel", "Wrath of Winter" }
I.O[1879109801] = { { "Derrota sierpes en Forochel x100", "Defeat worms in Forochel x100", "", "" } }
I.D[1879109802] = { "Azote de sierpes (avanzado)", "Worm-slayer (Advanced)", 106, 30, 2000, 10, 700, "Lossoth de Forochel", "", "Es incierto si estos sierpes son nativas del Forochel o si han bajado de las tierras desoladas del norte durante el invierno cuando la Bahía de Hielo está congelada lo suficiente para cruzar. Por supuesto, ya no importa...", "It is uncertain whether these worms are native to Forochel or whether they have come down from the northern waste-land during the winter when the Ice Bay is frozen solid enough to travel across. Of course, it no longer...", "Lossoth of Forochel", "" }
I.O[1879109802] = { { "Termina the deed 'Azote de sierpes'", "Complete the deed 'Worm-slayer'", "", "" }, { "Derrota sierpes en Forochel x200", "Defeat worms in Forochel x200", "", "" } }
