I.D[1879161641] = { "Escalador / Escaladora de Torres del Bosque Negro", "Mirkwood Tower Climber", 103, 56, 0, 5, 500, "Malledhrim", "Maestro Ascendente", "Hay dos torres principales que han sobrevivido en las ruinas de Ost Galadh: Minas Celebolf y Minas Glórelloth. Desde estas alturas, se puede ver gran parte de la extensión del Bosque Negro.", "There are two major, surviving towers in the ruins of Ost Galadh: Minas Celebolf and Minas Glórelloth. From these pinnacles, much of the expanse of Mirkwood may be seen.", "Malledhrim", "Master Ascender" }
I.O[1879161641] = { { "Minas Celebolf", "Minas Celebolf", "Minas Celebolf, la torre del árbol de plata, es una de las dos torres de vigilancia en Ost Galadh.", "Minas Celebolf, the tower of the silver tree, is one of the two watch towers at Ost Galadh." }, { "Minas Glórelloth", "Minas Glórelloth", "Minas Glórelloth, la torre de la flor dorada, es una de las dos torres de vigilancia en Ost Galadh.", "Minas Glórelloth, the tower of the golden flower, is one of the two watch towers at Ost Galadh." } }
I.D[1879175134] = { "Azote de hechiceros", "Sorcerer-slayer", 106, 55, 0, 5, 500, "Malledhrim", "Malledhrim honorario", "Los sirvientes del Enemigo son una presencia formidable en el Bosque Negro mientras los Malledhrim avanzan.", "The servants of the Enemy are a formidable presence in Mirkwood as the Malledhrim press forward.", "Malledhrim", "Honorary Malledhrim" }
