I.D[1879175136] = { "Azote de bestias", "Beast-slayer", 106, 55, 0, 5, 500, "Malledhrim", "Cazador de Bestias Oscuras", "Los numerosos depredadores del Bosque Negro son tan oscuros como la noche misma, corrompidos por los largos años de maldad.", "The many predators of Mirkwood are as black as the night itself, corrupted by the long years of evil.", "Malledhrim", "Hunter of Dark Beasts" }
