I.D[1879175386] = { "Las tierras salvajes del Bosque Negro", "The Wilds of Mirkwood", 103, 56, 2000, 5, 500, "Malledhrim", "", "Hay muchos lugares salvajes y abandonados que se pueden encontrar mientras el viajero cauteloso atraviesa el Bosque Negro.", "There are many wild and forsaken places to be stumbled upon as the wary wanderer passes through Mirkwood.", "Malledhrim", "" }
I.O[1879175386] = { { "Colina del Aullador de la Manada", "Pack-howler's Hill", "Esta colina aislada en los Troncosombríos es un punto de reunión para las manadas de lobos del Bosque Negro; aullidos lamentables se pueden escuchar a menudo en el viento desde esta dirección.", "This isolated hill in the Dourstocks is a rallying point for the wolf-packs of Mirkwood; mournful howls can often be heard upon the wind from this direction." }, { "Gorogrod", "Gorogrod", "Gorogrod es un oscuro y malvado escondite de las arañas de las Hondonadas Enmarañadas, lleno de trampas peligrosas y telarañas pegajosas. Incluso el viajero más experimentado debe tener cuidado antes...", "Gorogrod is a deep and evil den of the spiders of the Scuttledells, filled with perilous snares and sticky webs. Even the most seasoned traveller should be wary before treading here, for spiders are..." }, { "Sâd Meryrn", "Sâd Meryrn", "Incluso los árboles pueden ser corrompidos por influencias malignas, y los Ucornos del Bosque Negro pasan sus largos días volviéndose cada vez más oscuros y corruptos. Su hogar, Sâd Meryrn, es un...", "Even trees can be corrupted by evil influences, and the Huorns of Mirkwood live out their long days growing ever blacker and ever more corrupt. Their home of Sâd Meryrn is a sad and lonely place,..." }, { "Estanque de la Muerte Rastrera", "Pool of Creeping Death", "Las aguas corrompidas del Bosque Ahogado están contaminadas por muchos años de corrupción, y el corazón de la enfermedad en el pantano es el Estanque de la Muerte Rastrera, hogar de muchos cadáveres...", "The fell waters of the Drownholt are polluted by many long years of corruption, and the heart of sickness in the swamp is the Pool of Creeping Death, home to many corpses and nasty creatures." }, { "El árbol del sufrimiento", "The Tree of Suffering", "El Árbol del Sufrimiento es un lugar donde los Orcos exhiben los cuerpos de sus víctimas para que todos los vean como una advertencia para aquellos que intenten llevar la luz al oscuro bosque.", "The Tree of Suffering is a place where the Orcs display the bodies of their victims for all to see as a warning to all who would bring light to the dark forest." }, { "The Crawling Water", "The Crawling Water", "Las cosas inmundas hacen que el agua de este estanque se agite, causando temor y disgusto a quienes lo descubren por casualidad.", "Foul things cause the water of this pool to ripple, bringing dread and disgust to those who happen upon it." }, { "Las Piedras del Viento", "The Wind Stones", "Las Piedras del Viento son impresionantes en su formación, elevándose desde el suelo del bosque, moldeadas y golpeadas por los elementos. Pero el mal se ha asentado aquí, y muchos Wargs crueles...", "The Wind Stones are impressive in their formation, jutting high from the forest floor, shaped and beaten by the elements. But evil has settled here, and many cruel Wargs prowl about, spoiling the..." } }
I.D[1879175387] = { "Al descubrimiento de las ruinas del Bosque Negro", "Uncovering the Ruins of Mirkwood", 103, 56, 2000, 5, 500, "Malledhrim", "", "El Bosque Negro alberga muchos lugares que alguna vez fueron grandiosos, pero que han caído en ruinas tras largos años de corrupción y abandono.", "Mirkwood is home to many places that were once great, but have fallen into ruin after long years of corruption and disrepair.", "Malledhrim", "" }
I.O[1879175387] = { { "Dannenglor", "Dannenglor", "Danneglor fue una vez un bastión de los Elfos del Gran Bosque Verde, pero cayó bajo el asalto del Nigromante de Dol Guldur hace mucho tiempo. Ahora, los viles merrevail de Angmar se han refugiado...", "Danneglor was once a stronghold of the Elves of Greenwood the Great, but it fell beneath the onslaught of the Necromancer of Dol Guldur long ago. Now vile merrevail out of Angmar have taken refuge..." }, { "Mithechad", "Mithechad", "Los Malledhrim que buscan atacar el corazón de Dol Guldur se han acampado en estas ruinas inmundas, esperando evitar ser detectados el tiempo suficiente para llevar a cabo sus planes.", "Malledhrim seeking to strike into the heart of Dol Guldur have encamped in these foul ruins, hoping to avoid detection long enough to carry out their plans." }, { "Tirnhirion", "Tirnhirion", "Esta torre una vez vigiló el río Anduin y el paso hacia Lothlórien, la tierra hermana del Bosque Negro en las orillas occidentales.", "This tower once watched over the river Anduin and the passage to Lothlórien, Mirkwood's sister on the western banks." }, { "Sâd Morangol", "Sâd Morangol", "Estas ruinas se han convertido en el hogar de hechiceros númenóreanos negros y espíritus malignos al servicio de Dol Guldur", "These ruins have become home to Black Númenórean sorcerers and fell spirits in service to Dol Guldur." }, { "Las Ruinas Salvajes", "The Wild Ruin", "Las ruinas periféricas de Ost Galadh se han convertido en guaridas de bestias salvajes, corrompidas por el poder maligno de Dol Guldur.", "The outlying ruins of Ost Galadh have become the lairs of wild beasts, corrupted by the foul power of Dol Guldur." } }
I.D[1879175388] = { "Fortalezas Malignas del Bosque Negro", "Evil Strongholds of Mirkwood", 103, 56, 2000, 15, 500, "Malledhrim", "", "Muchos enemigos se han asentado en todo el Bosque Negro, esforzándose siempre por convertirlo en la fortaleza maligna y desesperada que se ha convertido desde entonces.", "Many foes have settled throughout Mirkwood, striving ever to make it the fell and hopeless stronghold of evil that it has since become.", "Malledhrim", "" }
I.O[1879175388] = { { "Garmadh-maudhûl", "Garmadh-maudhûl", "Garmadh-maudhûl es uno de los muchos campamentos orcos en los Pasajes de Ceniza donde las fuerzas de Dol Guldur se reúnen para comenzar su invasión de Lothlórien.", "Garmadh-maudhûl is one of many Orc-camps in the Ashenslades where the forces of Dol Guldur muster to begin their invasion of Lothlórien." }, { "Sâd Doldúr", "Sâd Doldúr", "Este lugar malvado es la fuente de la plaga que afecta a los Pasajes de Ceniza, invocada por los espíritus malignos y los hechiceros que habitan allí.", "This evil place is the source of the blight upon the Ashenslades, summoned by the fell spirits and sorcerers who dwell there." }, { "Ânghum-maudhûl", "Ânghum-maudhûl", "Ânghum-maudhûl es uno de los muchos campamentos orcos que salpican las Tierras baldías de los Pasajes de Ceniza, actuando como Sala de Reunión Militar para las fuerzas de Dol Guldur.", "Ânghum-maudhûl is one of many Orc-camps littering the wastes of the Ashenslades, acting as a mustering hall for the forces of Dol Guldur." }, { "Búrzkala", "Búrzkala", "Búrzkala es un fuerte orco en Gathbúrz, donde los Orcos de Dol Guldur han establecido una base.", "Búrzkala is an Orc-fort in Gathbúrz, where the Orcs of Dol Guldur have established a foothold." }, { "Amon Angened", "Amon Angened", "Esta colina fue una vez un puesto de observación para los Elfos del Gran Bosque Verde antes de la llegada del Nigromante.", "This hill was once a look-out for the Elves of Greenwood the Great before the coming of the Necromancer." }, { "Durbúrz-stazg", "Durbúrz-stazg", "Este campamento orco se estableció para prevenir un ataque a Dol Guldur desde el bosque de Lothlórien.", "This Orc-camp was established to prevent an attack upon Dol Guldur from the forest of Lothlórien." } }
I.D[1879190074] = { "Azote de Dunlendinos", "Dunlending-slayer", 106, 59, 0, 5, 500, "La Compañía Gris", "enemigo de la Mano Blanca", "Elimina a los Dunlendinos en Enedwaith.", "Defeat Dunlendings in Enedwaith.", "The Grey Company", "Foe of the White Hand" }
I.O[1879190074] = { { "Elimina a los Dunlendinos en Enedwaith x100", "Defeat Dunlendings in Enedwaith x100", "", "" } }
I.D[1879190082] = { "Camino de la Compañía Gris", "Path of the Grey Company", 103, 59, 1000, 5, 500, "La Compañía Gris", "embajador de la Compañía Gris", "Los Montaraces del Norte, parientes de Aragorn hijo de Arathorn, han salido en ayuda de su jefe. Mientras se dirigen al sur hacia Rohan, exploran el camino por delante en busca de las mejores rutas.", "Rangers of the North, kinsmen of Aragorn son of Arathorn, have ridden forth to their chieftain's aid. As they pass south to Rohan, scout the way ahead for the best roads.", "The Grey Company", "Ambassador of the Grey Company" }
I.O[1879190082] = { { "Echad Dagoras", "Echad Dagoras", "Echad Dagoras es el campamento de Dagoras de Esteldín y sus compañeros. Aquí es donde la Compañía Gris entró en Enedwaith y se separó, con la esperanza de atravesar la región sin ser detectados por...", "Echad Dagoras is the encampment of Dagoras of Esteldín and his companions. It is here that the Grey Company entered Enedwaith and went their separate ways, hoping to pass through the region unnoticed..." }, { "Echad Saeradan", "Echad Saeradan", "Echad Saeradan es el campamento de Saeradan de las Tierras de Bree y sus compañeros.", "Echad Saeradan is the encampment of Saeradan of Bree-land and his companions." }, { "Echad Idhrenfair", "Echad Idhrenfair", "Echad Idhrenfair es el campamento de Idhrenfair y sus compañeros, que habían ayudado a los Malledhrim en el sur del Bosque Negro.", "Echad Idhrenfair is the encampment of Idhrenfair and his companions, who had aided the Malledhrim in Southern Mirkwood." }, { "Echad Daervunn", "Echad Daervunn", "Echad Daervunn es el campamento de Daervunn de Esteldín y sus compañeros.", "Echad Daervunn is the encampment of Daervunn of Esteldín and his companions." }, { "Harndirion", "Harndirion", "Harndirion es la ruina de una antigua fortaleza construida por los Hombres de Gondor hace mucho tiempo.", "Harndirion is the ruin of an ancient fortress built by the Men of Gondor long ago." } }
I.D[1879190100] = { "Los Cartrevs de Enedwaith", "The Cartrevs of Enedwaith", 104, 59, 1000, 5, 500, "La Compañía Gris", "colono de Enedwaith", "Los miembros del clan Uch-lûth tienen muchas granjas periféricas, aunque han sido atacados por invasores del sur.", "The clansmen of the Uch-lûth have many outlying farmsteads, though they have come under attack by invaders from the South.", "The Grey Company", "Homesteader of Enedwaith" }
I.O[1879190100] = { { "Cartrev Duved", "Cartrev Duved", "Esta cabaña es el hogar del pastor Duved. Junto con su hija Avanen, cuida de sus rebaños en Fordirith.", "This hut is the home of the shepherd Duved. Along with his daughter Avanen, he tends his flocks in Fordirith." }, { "Cartrev Emlun", "Cartrev Emlun", "Esta granja pertenece a un pastor llamado Emlun. Los recientes problemas en las tierras de los Uch-lûth le han obligado a abandonar su hogar por un tiempo.", "This stead belongs to a herdsman named Emlun. Recent troubles in the lands of the Uch-lûth have caused him to abandon his home for a time." }, { "Cartrev Rurith", "Cartrev Rurith", "Esta granja pertenecía a un pastor llamado Rurith hasta que los invasores del sur lo masacraron a él y a su familia y la quemaron por completo.", "This stead belonged to a herdsman named Rurith until raiders from the South butchered him and his family and burnt it to the ground." }, { "Cartrev Matho", "Cartrev Matho", "Esta granja pertenecía a un pastor llamado Matho. Los invasores del sur la quemaron por completo mientras Matho estaba ausente.", "This stead belonged to a herdsman named Matho. Raiders from the South burnt it to the ground while Matho was away." }, { "Cartrev Hamon", "Cartrev Hamon", "Esta granja de Uch-lûth es una de las pocas que sobrevivieron a los ataques de los semiorcos.", "This Uch-lûth farmstead is one of the few that survived the attacks of the half-orcs." } }
