I.D[1879190796] = { "Maestro de las Escaleras / Maestra de las Escaleras", "Master of Stairs", 104, 59, 1000, 10, 500, "Algraig, Hombres de Enedwaith", "Maestro / Maestra de las Escaleras", "El camino que conduce a la Cumbre de Nar es largo y arduo.", "The road leading to Nar's Peak is a long and arduous one.", "Algraig, Men of Enedwaith", "Master / Mistress of Stairs" }
I.O[1879190796] = { { "Al mirar hacia arriba por las escaleras, te preguntas cómo lograste sobrevivir para llegar a la cima.", "Looking up the stairs, you wonder how you ever survived to make it to the top.", "Al mirar hacia arriba por las escaleras, te preguntas cómo lograste sobrevivir para llegar a la cima.", "Looking up the stairs, you wonder how you ever survived to make it to the top." }, { "Al mirar hacia abajo por la escalera, te preguntas cómo lograste reunir el valor para hacer el ascenso", "Looking down the stair, you wonder how you ever mustered the courage to make the ascent", "Al mirar hacia abajo por la escalera, te preguntas cómo lograste reunir el valor para hacer el ascenso", "Looking down the stair, you wonder how you ever mustered the courage to make the ascent" } }
I.D[1879190797] = { "Exiliados de la Montaña Solitaria", "Exiles from the Lonely Mountain", 103, 0, 1000, 5, 500, "Algraig, Hombres de Enedwaith", "exiliado de Erebor", "Cuando Smaug derribó a los enanos de Erebor, Thrór, su familia y muchos de sus súbditos escaparon hacia el sur y, tras atravesar las Tierras Brunas, se dirigieron al norte hacia las Montañas Azules.", "When Smaug threw down the dwarves of Erebor, Thrór and his family and many of their subjects escaped south, eventually crossing through Dunland and north to the Blue Mountains.", "Algraig, Men of Enedwaith", "Exile of Erebor" }
I.O[1879190797] = { { "PROGRESS", "PROGRESS", "", "" }, { "PROGRESS", "PROGRESS", "", "" }, { "PROGRESS", "PROGRESS", "", "" }, { "PROGRESS", "PROGRESS", "", "" }, { "PROGRESS", "PROGRESS", "", "" }, { "PROGRESS", "PROGRESS", "", "" } }
I.D[1879190798] = { "La Larga Ruta de los Hobbits", "The Long Road of the Hobbits", 103, 0, 1000, 5, 500, "Algraig, Hombres de Enedwaith", "seguidor del Largo Camino", "Se dice que los hobbits de la Comarca se originaron al este de las Montañas Nubladas y que, después de cruzar las Nubladas, una familia de Fuertes se estableció en Enedwaith.", "It is said that the hobbits of the Shire originated east of the Misty Mountains and that after crossing the Misties, a family of Stoors settled in Enedwaith.", "Algraig, Men of Enedwaith", "Follower of the Long Road" }
I.O[1879190798] = { { "PROGRESS", "PROGRESS", "", "" }, { "PROGRESS", "PROGRESS", "", "" }, { "PROGRESS", "PROGRESS", "", "" }, { "PROGRESS", "PROGRESS", "", "" } }
I.D[1879190838] = { "Pequeñas maravillas", "Little Wonders", 103, 59, 1000, 10, 500, "Algraig, Hombres de Enedwaith", "pequeña maravilla", "Al patrullar los Valles Sombríos, te sorprendió encontrar objetos claramente pertenecientes a los hobbits, aunque rústicos.", "While patrolling the Gloomglens, you were amazed to find items clearly belonging to hobbit-folk, however rustic.", "Algraig, Men of Enedwaith", "Little Wonder" }
I.O[1879190838] = { { "Esta flecha toscamente tallada pertenecía a un niño pequeño o a un hobbit; la fabricación indica un hobbit.", "This rough-hewn arrow either belonged to a small child or hobbit -- the make indicates a hobbit.", "Esta flecha toscamente tallada pertenecía a un niño pequeño o a un hobbit; la fabricación indica un hobbit.", "This rough-hewn arrow either belonged to a small child or hobbit -- the make indicates a hobbit." }, { "Estas botas, aunque toscas y rústicas en su diseño, son claramente de fabricación Fuerte.", "These boots, while crude and rustic in design, are clearly of Stoor-make.", "Estas botas, aunque toscas y rústicas en su diseño, son claramente de fabricación Fuerte.", "These boots, while crude and rustic in design, are clearly of Stoor-make." }, { "Este pequeño cubo podría haber sido el juguete de un niño, pero si es así, el fabricante se esforzó mucho...", "This little bucket might have been the toy of a child, but if so the maker took great pains to make it...", "Este pequeño cubo podría haber sido el juguete de un niño, pero si es así, el fabricante se esforzó mucho para que fuera resistente.", "This little bucket might have been the toy of a child, but if so the maker took great pains to make it labour-worthy." }, { "Este esqueleto es una clara evidencia de que los hobbits viven o vivieron en los Valles Sombríos.", "This skeleton is clear evidence that hobbits live or once-lived in the Gloomglens.", "Este esqueleto es una clara evidencia de que los hobbits viven o vivieron en los Valles Sombríos.", "This skeleton is clear evidence that hobbits live or once-lived in the Gloomglens." }, { "Este pico de minería es sin duda un implemento de fabricación hobbit.", "This mining pick is certainly an implement of hobbit-make.", "Este pico de minería es sin duda un implemento de fabricación hobbit.", "This mining pick is certainly an implement of hobbit-make." }, { "Los hobbits fueron una vez conocidos como grandes arqueros, pero ahora son más conocidos por la jardinería......", "Hobbits were once known as great archers, but now they are better known for gardening...this bow suggests...", "Los hobbits fueron una vez conocidos como grandes arqueros, pero ahora son más conocidos por la jardinería... este arco sugiere que todavía hay cazadores entre ellos.", "Hobbits were once known as great archers, but now they are better known for gardening...this bow suggests that there are still hunters among them." } }
I.D[1879190866] = { "Rey pescador / Reina pescadora", "Fisher-king", 103, 59, 1000, 5, 500, "Algraig, Hombres de Enedwaith", "Rey Pescador / Reina Pescadora", "Mientras que la mayoría de los Fuertes de Maur Tulhau son maestros agricultores y cazadores expertos, algunos eligen ganarse la vida pescando.", "While most of the Stoors of Maur Tulhau are master farmers and expert hunters, a few choose to make their living fishing.", "Algraig, Men of Enedwaith", "Fisher-king / Fisher-queen" }
I.O[1879190866] = { { "The Fishing Hole", "The Fishing Hole", "Solo unos pocos, incluso entre los Fuertes de Maur Tulhau, conocen la ubicación de este maravilloso agujero de pesca.", "Only a few even among the Stoors of Maur Tulhau know the location of this marvelous fishing hole." } }
