I.D[1879220073] = { "Azote de Uruk-hai", "Uruk-hai Slayer", 106, 62, 0, 5, 500, "Hombres de las Tierras Brunas", "", "Los poderosos Uruk-hai son leales solo a Saruman. Son más inteligentes y crueles que incluso los viles Orcos.", "The mighty Uruk-hai are loyal only to Saruman. They are more clever and cruel than even the vile Orcs.", "Men of Dunland", "" }
I.O[1879220073] = { { "Derrota a los Uruk-hai en las Tierras Brunas x100", "Defeat Uruk-hai in Dunland x100", "", "" } }
I.D[1879220074] = { "Azote de semiorcos", "Half-orc Slayer", 106, 62, 0, 5, 500, "Hombres de las Tierras Brunas", "", "Los semiorcos de las Tierras Brunas vienen todos de Isengard, donde trabajan para llevar a cabo el plan de Saruman de oprimir a sus vecinos.", "The half-orcs in Dunland all hail from Isengard, where they strive to carry out Saruman's plan to oppress his neighbours.", "Men of Dunland", "" }
I.O[1879220074] = { { "Derrota a los semiorcos en las Tierras Brunas x100", "Defeat half-orcs in Dunland x100", "", "" } }
I.D[1879220075] = { "Azote de Orcos", "Orc-slayer", 106, 62, 0, 5, 500, "Hombres de las Tierras Brunas", "", "Los Orcos son siempre malvados, sin importar a quién sirvan. Los Orcos de Isengard no son mejores que los que vienen de Mordor.", "Orcs are always evil, no matter whom they serve. The Orcs of Isengard are no better than those who come from Mordor.", "Men of Dunland", "" }
I.O[1879220075] = { { "Derrota a los Orcos en las Tierras Brunas x100", "Defeat Orcs in Dunland x100", "", "" } }
I.D[1879220076] = { "Azote de Huargos", "Warg-slayer", 106, 62, 0, 5, 500, "Hombres de las Tierras Brunas", "", "Los Huargos cazan y aúllan en mayor número a medida que las sombras del mal extienden sus oscuras garras por toda la Tierra Media.", "Wargs hunt and howl in greater numbers as the shadows of evil stretch their dark fingers across all of Middle-earth.", "Men of Dunland", "" }
I.O[1879220076] = { { "Derrota a los Huargos en las Tierras Brunas x100", "Defeat Wargs in Dunland x100", "", "" } }
I.D[1879220077] = { "Azote de crebains", "Craban-slayer", 106, 62, 0, 5, 500, "Hombres de las Tierras Brunas", "", "Los crebains espías sirven a Saruman tan lealmente como los Orcos y los Hombres, llevando mensajes de un lado a otro, dando a Isengard una ventaja en la próxima guerra.", "Spying crebain serve Saruman as loyally as Orcs and Men, bearing messages to and fro, giving Isengard an advantage in the coming war.", "Men of Dunland", "" }
I.O[1879220077] = { { "Derrota a los crebains en las Tierras Brunas x50", "Defeat crebain in Dunland x50", "", "" } }
I.D[1879220078] = { "Azote de los Muertos", "Slayer of the Dead", 106, 62, 0, 5, 500, "Hombres de las Tierras Brunas", "", "Es una señal de maldad cuando los Muertos se despiertan de su largo sueño para caminar nuevamente por la tierra.", "It is an evil sign when the Dead wake from their long slumber to walk the earth again.", "Men of Dunland", "" }
I.O[1879220078] = { { "Derrota a los Muertos en las Tierras Brunas x100", "Defeat the Dead in Dunland x100", "", "" } }
I.D[1879220079] = { "Azote de trasgos", "Goblin-slayer", 106, 62, 0, 5, 500, "Hombres de las Tierras Brunas", "", "Dondequiera que la guerra y la violencia estallen, los trasgos están allí para reírse mientras saquean el botín del caos.", "Wherever war and violence lash out, goblins are there to cackle while they reap the plunder from the chaos.", "Men of Dunland", "" }
I.O[1879220079] = { { "Derrota a los trasgos en las Tierras Brunas x100", "Defeat goblins in Dunland x100", "", "" } }
I.D[1879220080] = { "Azote de Dunlendinos (Avanzado)", "Dunlending-slayer (Advanced)", 106, 62, 2000, 5, 700, "Hombres de las Tierras Brunas", "", "Los malvados Hombres de las Tierras Brunas existen para dar mala reputación a los habitantes de estas tierras, tanto a los buenos como a los malos.", "The evil Men of Dunland exist to give a bad reputation to the folk of these lands, good and bad alike.", "Men of Dunland", "" }
I.O[1879220080] = { { "Termina the deed 'Azote de Dunlendinos'", "Complete the deed 'Dunlending-slayer'", "", "" }, { "Derrota a los Dunlendinos hostiles en las Tierras Brunas x200", "Defeat hostile Dunlendings in Dunland x200", "", "" } }
I.D[1879220081] = { "Azote de bestias (Avanzado)", "Beast-slayer (Advanced)", 106, 62, 2000, 5, 700, "Hombres de las Tierras Brunas", "", "Las criaturas salvajes de las Tierras Brunas representan una gran amenaza para las personas que intentan sobrevivir en estas tierras difíciles.", "The wild creatures of Dunland pose a great threat to the people who try to survive in these harsh lands.", "Men of Dunland", "" }
I.O[1879220081] = { { "Termina the deed 'Azote de bestias'", "Complete the deed 'Beast-slayer'", "", "" }, { "Derrota a las bestias salvajes en las Tierras Brunas x200", "Defeat wild beasts in Dunland x200", "", "" } }
I.D[1879220082] = { "Azote de Uruk-hai (Avanzado)", "Uruk-hai Slayer (Advanced)", 106, 62, 2000, 5, 700, "Hombres de las Tierras Brunas", "", "Los poderosos Uruk-hai son leales solo a Saruman. Son más inteligentes y crueles que incluso los viles Orcos.", "The mighty Uruk-hai are loyal only to Saruman. They are more clever and cruel than even the vile Orcs.", "Men of Dunland", "" }
I.O[1879220082] = { { "Termina the deed 'Azote de Uruk-hai'", "Complete the deed 'Uruk-hai Slayer'", "", "" }, { "Derrota a los Uruk-hai en las Tierras Brunas x200", "Defeat Uruk-hai in Dunland x200", "", "" } }
I.D[1879220083] = { "Azote de semiorcos (Avanzado)", "Half-orc Slayer (Advanced)", 106, 62, 2000, 5, 700, "Hombres de las Tierras Brunas", "", "Los semiorcos de las Tierras Brunas vienen todos de Isengard, donde trabajan para llevar a cabo el plan de Saruman de oprimir a sus vecinos.", "The half-orcs in Dunland all hail from Isengard, where they strive to carry out Saruman's plan to oppress his neighbours.", "Men of Dunland", "" }
I.O[1879220083] = { { "Termina the deed 'Azote de semiorcos'", "Complete the deed 'Half-orc Slayer'", "", "" }, { "Derrota a los semiorcos en las Tierras Brunas x200", "Defeat half-orcs in Dunland x200", "", "" } }
I.D[1879220084] = { "Azote de orcos (avanzado)", "Orc-slayer (Advanced)", 106, 62, 2000, 5, 700, "Hombres de las Tierras Brunas", "", "Los Orcos son siempre malvados, sin importar a quién sirvan. Los Orcos de Isengard no son mejores que los que vienen de Mordor.", "Orcs are always evil, no matter whom they serve. The Orcs of Isengard are no better than those who come from Mordor.", "Men of Dunland", "" }
I.O[1879220084] = { { "Termina the deed 'Azote de Orcos'", "Complete the deed 'Orc-slayer'", "", "" }, { "Derrota a los Orcos en las Tierras Brunas x200", "Defeat Orcs in Dunland x200", "", "" } }
I.D[1879220085] = { "Azote de Huargos (avanzado)", "Warg-slayer (Advanced)", 106, 62, 2000, 5, 700, "Hombres de las Tierras Brunas", "", "Los huargos cazan y aúllan en mayor número a medida que las sombras del mal extienden sus oscuros dedos por toda la Tierra Media.", "Wargs hunt and howl in greater numbers as the shadows of evil stretch their dark fingers across all of Middle-earth.", "Men of Dunland", "" }
I.O[1879220085] = { { "Termina the deed 'Azote de Huargos'", "Complete the deed 'Warg-slayer'", "", "" }, { "Derrota a los huargos en las Tierras Brunas x200", "Defeat Wargs in Dunland x200", "", "" } }
I.D[1879220086] = { "Azote de crebains (Avanzado)", "Craban-slayer (Advanced)", 106, 62, 2000, 5, 700, "Hombres de las Tierras Brunas", "", "Los crebains espías sirven a Saruman con la misma lealtad que los Orcos y los Hombres, llevando mensajes de un lado a otro y dando a Isengard una ventaja en la guerra que se avecina.", "Spying crebain serve Saruman as loyally as Orcs and Men, bearing messages to and fro, giving Isengard an advantage in the coming war.", "Men of Dunland", "" }
I.O[1879220086] = { { "Termina the deed 'Azote de crebains'", "Complete the deed 'Craban-slayer'", "", "" }, { "Derrota a los crebains en las Tierras Brunas x100", "Defeat crebain in Dunland x100", "", "" } }
I.D[1879220087] = { "Azote de los muertos (Avanzado)", "Slayer of the Dead (Advanced)", 106, 62, 2000, 5, 700, "Hombres de las Tierras Brunas", "", "Es una señal de maldad cuando los muertos se despiertan de su largo sueño para caminar nuevamente por la tierra.", "It is an evil sign when the Dead wake from their long slumber to walk the earth again.", "Men of Dunland", "" }
I.O[1879220087] = { { "Termina the deed 'Azote de los Muertos'", "Complete the deed 'Slayer of the Dead'", "", "" }, { "Derrota a los muertos en las Tierras Brunas x200", "Defeat the dead in Dunland x200", "", "" } }
I.D[1879220088] = { "Azote de trasgos (avanzado)", "Goblin-slayer (Advanced)", 106, 62, 2000, 5, 700, "Hombres de las Tierras Brunas", "", "Dondequiera que la guerra y la violencia estallen, los trasgos están allí para reírse mientras saquean el botín del caos.", "Wherever war and violence lash out, goblins are there to cackle while they reap the plunder from the chaos.", "Men of Dunland", "" }
I.O[1879220088] = { { "Termina the deed 'Azote de trasgos'", "Complete the deed 'Goblin-slayer'", "", "" }, { "Derrota a los trasgos en las Tierras Brunas x200", "Defeat goblins in Dunland x200", "", "" } }
I.D[1879220211] = { "Explorando Fuerte Dreng", "Exploring Trum Dreng", 103, 62, 2000, 5, 500, "Hombres de las Tierras Brunas", "", "Fuerte Dreng, hogar del Clan del Ciervo, tiene muchos lugares para explorar.", "Trum Dreng, home of the Stag-clan, has many places to explore.", "Men of Dunland", "" }
I.O[1879220211] = { { "Dire Hollow", "Dire Hollow", "La Hondonada Desolada es un refugio de lobos malvados que atormentan a la gente de Lhan Tarren.", "Dire Hollow is a den of evil wolves which plague the people of Lhan Tarren." }, { "The Herd-lands", "The Herd-lands", "Estos amplios campos son utilizados por los Caru-lûth, Clan del Ciervo, como pastizales para sus rebaños de bueyes.", "These wide fields are used by the Caru-lûth, Stag-clan, as grazing lands for their herds of oxen." }, { "Lhan Tarren", "Lhan Tarren", "Lhan Tarren es el hogar de los Caru-lûth, Clan del Ciervo, un pueblo en disminución en las Tierras Brunas.", "Lhan Tarren is home to the Caru-lûth, Stag-clan, a dwindling people in Dunland." }, { "The North Pass", "The North Pass", "El Paso del Norte conduce de Fuerte Dreng a la Arboleda Lóbrega de Enedwaith.", "The North Pass leads from Trum Dreng into the Mournshaws of Enedwaith." }, { "The Watch-tower", "The Watch-tower", "Esta vieja torre sirvió una vez como puesto de vigilancia para la gente de Fuerte Dreng.", "This old tower once served as a watch-post for the folk of Trum Dreng." }, { "The White Hand Outpost", "The White Hand Outpost", "Este campamento alberga a muchos semiorcos al servicio de la Mano Blanca de Isengard.", "This encampment houses many half-orcs in service to the White Hand of Isengard." } }
I.D[1879220266] = { "Explorando Pren Gwydh", "Exploring Pren Gwydh", 103, 62, 2000, 5, 500, "Hombres de las Tierras Brunas", "", "Pren Gwydh, lugar donde se encuentra Galtrev, tiene muchos lugares para explorar.", "Pren Gwydh, home of the city of Galtrev, has many places to explore.", "Men of Dunland", "" }
I.O[1879220266] = { { "The Fanged Lair", "The Fanged Lair", "La Guarida Dentada es la guarida de una manada de lobos malvados que merodean por Pren Gwydh.", "The Fanged Lair is the den of a pack of evil wolves which prowl Pren Gwydh." }, { "Bloodtusk's Den", "Bloodtusk's Den", "Esta es la guarida de Viejo Colmillo Sangriento, un jabalí que se dice que migró desde Archet en las Tierras de Bree.", "This is the den of Old Bloodtusk, a boar who is said to have migrated all the way from Archet in Bree-land." }, { "The Galtrev Lumber-camp", "The Galtrev Lumber-camp", "Este campamento de leñadores es trabajado por la gente de Galtrev, lo más cercano a un centro social bullicioso en las Tierras Brunas.", "This lumber-camp is worked by the people of Galtrev, the closest thing to a bustling social centre in Dunland." }, { "Dragon-clan Settlement", "Dragon-clan Settlement", "El Draig-lûth, el Clan del Dragón, estableció este campamento para hostigar a los habitantes de Galtrev.", "The Draig-lûth, Dragon-clan, established this encampment to harry the peoples of Galtrev." }, { "Las Cavernas Aullantes", "The Howling Caverns", "Una manada de huargos ha establecido esta guarida desde donde hostigar a los enemigos de la Mano Blanca.", "A pack of Wargs has established this den from whence to harry the enemies of the White Hand." }, { "Cabaña de grajo", "Rook's Hut", "Grajo, un antiguo guardián de crebains de Saruman, es un nativo de las Tierras de Bree que aspira a convertirse en un gran mago... un objetivo inalcanzable que aún no logra comprender.", "Rook, a former craban-keeper for Saruman, is a Bree-land native who aspires to become a great wizard...an unattainable goal he yet fails to grasp." } }
I.D[1879220269] = { "Explorando Peñalago", "Exploring Carreglyn", 103, 62, 2000, 5, 500, "Hombres de las Tierras Brunas", "", "Peñalago tiene muchos lugares para explorar.", "Carreglyn has many places to explore.", "Men of Dunland", "" }
I.O[1879220269] = { { "Bajo Barnavon", "Lower Barnavon", "Bajo Barnavon es el distrito del pueblo de Barnavon donde ahora habita el remanente de los Turch-lûth, el clan del Jabalí.", "Lower Barnavon is the district of the village of Barnavon where the remnant of the Turch-lûth, the Boar-clan, now dwell." }, { "Alto Barnavon", "Upper Barnavon", "Alto Barnavon es el distrito del pueblo de Barnavon habitado por los Uch-lûth, el clan del Buey gobernante.", "Upper Barnavon is the district of the village of Barnavon inhabited by the ruling Uch-lûth, Ox-clan." }, { "Naur-maudhûl", "Naur-maudhûl", "Naur-maudhûl es un campamento de trasgos y huargos establecido para permitir a los exploradores Nákhmau de Saruman acceder a Peñalago.", "Naur-maudhûl is an encampment of goblins and Wargs established to allow Saruman's Nákhmau scouts access to Carreglyn." }, { "Barnavon Mine", "Barnavon Mine", "Esta mina, actualmente trabajada en nombre de Saruman el Blanco, ha sido invadida por viciosos bugan.", "This mine, currently being worked in the name of Saruman the White, has been overrun by vicious bugan." }, { "Hen Turrau", "Hen Turrau", "Esta torre de vigilancia fue construida sobre las ruinas de una antigua torre gondoriana.", "This watch-tower was built atop the ruins of an ancient Gondorian tower." }, { "Lhun Avanc", "Lhun Avanc", "Se rumorea que este estanque es el hogar del Gran Avanc, una criatura de la leyenda dunlendina.", "This pond is rumoured to be the home of the Great Avanc, a creature of Dunlending legend." }, { "Santuario de Munfaeril", "Munfaeril's Shrine", "Este santuario fue erigido por los Uch-lûth hace mucho tiempo como un lugar para comunicarse con Munfaeril, un espíritu de tiempos antiguos venerado como el Uch-gwirod, el espíritu del Buey, por el...", "This shrine was erected by the Uch-lûth long ago as a place to commune with Munfaeril, a spirit of ancient days worshipped as the Uch-gwirod, the Ox-spirit, by the people of Barnavon." } }
I.D[1879220270] = { "Explorando el Bosque de las Tumbas", "Exploring the Gravenwood", 103, 62, 2000, 5, 500, "Jinetes de Teodred", "", "El Bosque de las Tumbas tiene muchos lugares para explorar.", "The Gravenwood has many places to explore.", "Théodred's Riders", "" }
I.O[1879220270] = { { "The Tree of Tribute", "The Tree of Tribute", "Este gran árbol marcado con runas es el lugar donde un héroe dunlendino de antaño se sacrificó para detener el avance de los enemigos de su pueblo.", "This great, rune-marked tree is the place where a Dunlending hero of old sacrificed himself to hold off the advance of his people's enemies." }, { "El Árbol del Reclutamiento", "The Mustering Tree", "Este árbol marcado con runas es un lugar donde los dunlendinos una vez reunieron sus fuerzas para luchar contra Gondor y Rohan.", "This rune-marked tree is a place where the Dunlendings once mustered their forces to battle against Gondor and Rohan." }, { "Campamento de exploradores Rohirrim", "Rohirrim Scout-camp", "Este campamento fue establecido por Théodred, Príncipe de Rohan, y su grupo de exploradores para vigilar los movimientos de las fuerzas dunlendinas.", "This camp was established by Théodred, Prince of Rohan, and his party of scouts to watch the movements of the Dunlending forces." }, { "La Cuenca de las Sombras", "The Slade of Shadows", "Este cuenco de tres árboles marcados con runas alberga el Dutegelh, una reliquia de gran poder arrebatada de Dol Guldur cuando el Concilio Blanco expulsó al Nigromante.", "This slade of three rune-marked trees houses the Dutegelh, a relic of great power wrested from Dol Guldur when the White Council drove forth the Necromancer." }, { "Uvel-cadlus", "Uvel-cadlus", "El Draig-lûth, Clan del Dragón, estableció este campamento temporal en su viaje hacia el sur desde Enedwaith hasta la Hendidura de Wulf.", "The Draig-lûth, Dragon-clan, established this temporary encampment on their journey south out of Enedwaith to Wulf's Cleft." }, { "Rhuvel-cadlus", "Rhuvel-cadlus", "El Uch-lûth, Clan del Buey, estableció este campamento temporal en su viaje desde Barnavon hasta la Hendidura de Wulf.", "The Uch-lûth, Ox-clan, established this temporary encampment on their journey from Barnavon to Wulf's Cleft." }, { "Ak-ghru", "Ak-ghru", "Los orcos de la Mano Blanca establecieron este campamento para talar el Bosque de las Tumbas y suministrar madera para los esfuerzos bélicos de su amo.", "Orcs of the White Hand established this camp to clear-cut the Gravenwood to supply wood for their master's war-efforts." } }
I.D[1879220271] = { "Explorando el Páramo Desolado", "Exploring Starkmoor", 103, 62, 2000, 5, 500, "Hombres de las Tierras Brunas", "", "El Páramo Desolado tiene muchos lugares para explorar.", "Starkmoor has many places to explore.", "Men of Dunland", "" }
I.O[1879220271] = { { "Avardin", "Avardin", "Avardin es un puesto comercial y un pueblo del Uch-lûth, Clan del Buey, en el Páramo Desolado.", "Avardin is a trading post and village of the Uch-lûth, Ox-clan, in the Starkmoor." }, { "Flam-cadlus", "Flam-cadlus", "Flam-cadlus es un campamento del Draig-lûth, Clan del Dragón, en el Páramo Desolado.", "Flam-cadlus is an encampment of the Draig-lûth, Dragon-clan, in the Starkmoor." }, { "Cartrev Andras", "Cartrev Andras", "Esta es la casa del comerciante Andras, a quien has ayudado en un momento de necesidad.", "This is the home of the merchant Andras, to whom you have lent aid in a time of need." }, { "El Reposo del Sabueso", "The Hound's Rest", "El Reposo del Sabueso recibe su nombre porque los huargos del Enemigo gustan de tomar el sol sobre la roca.", "The Hound's Rest is so named because the Wargs of the Enemy like to sun upon the rock." }, { "The Culling Pit", "The Culling Pit", "La Fosa de la Matanza es una arena donde los guerreros dunlendinos se entrenan, o son eliminados, y los comerciantes apuestan en las batallas.", "The Culling Pit is an arena where Dunlending warriors are trained -- or trimmed -- and merchants wager on the battles." }, { "Mirador de la Hendidura de Wulf", "Wulf's Cleft Overlook", "El Promontorio ofrece una vista panorámica del gran valle de la Hendidura de Wulf, donde los guerreros de todas las Tierras Brunas se reúnen para invadir Rohan.", "The Overlook gives a vantage of the great valley of Wulf's Cleft, where warriors from across Dunland muster to invade Rohan." } }
I.D[1879220272] = { "Explorando los Altos del Brezal", "Exploring the Heathfells", 103, 62, 2000, 5, 500, "Jinetes de Teodred", "", "Los Altos del Brezal tienen muchos lugares para explorar.", "The Heathfells have many places to explore.", "Théodred's Riders", "" }
I.O[1879220272] = { { "Campamento de Grimbold", "Grimbold's Camp", "Este es el campamento de Grimbold del Bosque Oscuro, uno de los Señores de Caballos de Rohan.", "This is the encampment of Grimbold of the Grimslade, one of the Horse-lords of Rohan." }, { "Dol Baran", "Dol Baran", "Esta gran colina es de interés estratégico tanto para los Rohirrim como para la Mano Blanca.", "This great hill is of strategic interest to both the Rohirrim and the White Hand." }, { "Atalaya del Río", "River-watch", "Este campamento disputado es donde las fuerzas de Théodred se han fortificado para bloquear el acceso tanto por el camino del sur como por el río Isen.", "This contested encampment is where Théodred's forces have fortified to block approach both by the southern road, and up the River Isen." }, { "El Foso de Hierro", "The Pit of Iron", "El Foso de Hierro es una gran mina bajo Isengard donde los Orcos y sus prisioneros extraen mineral para usarlo en la fabricación de armas para la Mano Blanca.", "The Pit of Iron is a great mine beneath Isengard where the Orcs and their prisoners extract ore for use in making weapons for the White Hand." }, { "Slave Stockades", "Slave Stockades", "Estas celdas son donde se alojan los prisioneros de Isengard.", "These cells are where the prisoners of Isengard are housed." }, { "The Smelters", "The Smelters", "Aquí es donde se funde el mineral de hierro extraído del Foso de Hierro para su uso.", "This is where the iron-ore drawn from the Pit of Iron is smelted for use." }, { "El Complejo Subterráneo", "The Underworkings", "Esta es una de las minas que forman el Foso de Hierro.", "This is one of the mines that makes up the Pit of Iron." } }
I.D[1879220273] = { "Explorando Nan Curunír", "Exploring Nan Curunír", 103, 62, 2000, 5, 500, "Jinetes de Teodred", "", "Nan Curunír tiene muchos lugares para explorar.", "Nan Curunír has many places to explore.", "Théodred's Riders", "" }
I.O[1879220273] = { { "The Gates of Isengard", "The Gates of Isengard", "Estas puertas bloquean el paso a través del Anillo de Isengard hacia Orthanc más allá.", "These gates bar the passage through the Ring of Isengard to Orthanc beyond." }, { "The Pillar of the White Hand", "The Pillar of the White Hand", "Este horrible pilar indica el camino hacia Orthanc, la fortaleza de Saruman el Blanco.", "This gruesome pillar points the way to Orthanc, the stronghold of Saruman the White." }, { "Fang-rider's Warren", "Fang-rider's Warren", "Este campamento de trasgos también alberga a muchos jinetes de huargos.", "This goblin-encampment is also home to many Warg-riders." }, { "Blackmarch Fort", "Blackmarch Fort", "Esta fortaleza alberga a muchos Uruk-hai al servicio de la Mano Blanca.", "This stronghold houses many Uruk-hai in service to the White Hand." }, { "Bosque de Ramaviva", "Quickbeam's Grove", "Esta arboleda es el hogar del Ent Bregalad, también llamado Ramaviva.", "This grove is the home of the Ent Bregalad, also called Quickbeam." }, { "Campamento de Dagoras", "Dagoras' Camp", "El Montaraz Dagoras estableció este campamento para vigilar Nan Curunír y el Valle de Isengard.", "The Ranger Dagoras established this camp to keep an eye on Nan Curunír and the Vale of Isengard." } }
I.D[1879220276] = { "Explorando el Valle de los Huesos", "Exploring the Bonevales", 103, 62, 2000, 5, 500, "Hombres de las Tierras Brunas", "", "El Valle de los Huesos tiene muchos lugares para explorar.", "The Bonevales has many places to explore.", "Men of Dunland", "" }
I.O[1879220276] = { { "La Cantera de Huesos", "The Bone Quarry", "La Cantera de Huesos es una antigua cantera de piedra en las Valles de Huesos donde los Dievlig han erigido muchos túmulos.", "The Bone Quarry is an old stone-quarry in the Bonevales where the Dievlig have erected many cairns." }, { "Plas-maru", "Plas-maru", "Este enorme túmulo es la tumba central de todos los líderes de los Dievlig.", "This massive cairn is the central tomb of all the Dievlig's leaders." }, { "Echad Naeglanc", "Echad Naeglanc", "Aquí es donde el Montaraz Naeglanc y sus aliados dunlendinos han establecido su campamento.", "This is where the Ranger Naeglanc and his Dunlending allies have set up camp." }, { "Lhan Bach", "Lhan Bach", "Este pueblo dievlig sufre bajo el opresivo gobierno de su Brenin, Trehéarn.", "This Dievlig village suffers under the oppressive rule of their Brenin, Trehéarn." }, { "Lhan Gogledh", "Lhan Gogledh", "Lhan Gogledh es el pueblo central de los Dievlig en el Valle de los Huesos.", "Lhan Gogledh is the central village of the Dievlig in the Bonevales." } }
I.D[1879220277] = { "Explorando el Valle del Isen", "Exploring the Isendale", 103, 62, 2000, 5, 500, "Jinetes de Teodred", "", "El Valle del Isen ha estado durante mucho tiempo en el borde de los enfrentamientos fronterizos entre los Rohirrim y los Dunlendinos, y tiene muchos lugares para explorar.", "Isendale has long been on the edge of border skirmishes between the Rohirrim and Dunlendings, and has many places to explore.", "Théodred's Riders", "" }
I.O[1879220277] = { { "Puente del Cuarto", "Forthbrond", "Los Rohirrim han establecido Puente del Cuarto como un campamento avanzado en el Paso de Rohan contra los Dunlendinos que amenazan con invadir.", "The Rohirrim have established Forthbrond as a forward encampment in the Gap of Rohan against the Dunlendings who are threatening to invade." }, { "Cuvnerth", "Cuvnerth", "Este pueblo es uno de los muchos donde los Dunlendinos se están preparando para la invasión de Rohan.", "This village is one of many where the Dunlendings are ramping up for the invasion of Rohan." }, { "Âthdâr", "Âthdâr", "Muchos de los huargos de Saruman han habitado este gran madriguera, esperando las órdenes de su maestro.", "Many of Saruman's Wargs have inhabited this large warren, awaiting their master's commands." }, { "Brôntrig", "Brôntrig", "Brôntrig domina el Paso de Rohan y proporciona a los Dunlendinos un punto de estrangulamiento contra cualquier incursión de los Rohirrim. Es uno de varios pueblos donde los Dunlendinos se están...", "Brôntrig overlooks the Gap of Rohan and provides the Dunlendings a choke point against any incursion from the Rohirrim. It is one of several villages where the Dunlendings are ramping up for the..." } }
I.D[1879220278] = { "Explorando el Pantano Bruno", "Exploring the Dunbog", 103, 62, 2000, 5, 500, "Hombres de las Tierras Brunas", "", "El Pantano Bruno tiene muchos lugares para explorar. Mientras atraviesas los pantanos, ten cuidado de detenerte y oler el azufre.", "Dunbog has many places to explore. As you tread through the swamps, be careful to stop and smell the sulfur.", "Men of Dunland", "" }
I.O[1879220278] = { { "Lhan Colvarn", "Lhan Colvarn", "Has encontrado Lhan Colvarn, hogar de las Abominaciones.", "You have found Lhan Colvarn, home of the Abominations." }, { "Lhan Rhos", "Lhan Rhos", "Has encontrado Lhan Rhos, hogar de los Avanc-lûth", "You have found Lhan Rhos, home of the Avanc-lûth" }, { "Las Piedras Marchitas", "The Withered Stones", "Has encontrado las Piedras Marchitas, hogar de Bloodmaw y su prole.", "You have found the Withered Stones, home of Bloodmaw and her brood." }, { "Durgors", "Durgors", "Has encontrado Durgors, hogar temporal del Clan del Jabalí", "You have found Durgors, temporary home of the Boar Clan" }, { "El Claro Inmaculado", "The Pristine Glade", "Has encontrado el Claro Inmaculado, lugar secreto de los Avanc-lûth", "You have found The Pristine Glade, secret place of the Avanc-lûth" } }
I.D[1879221718] = { "Los Guardianes de la Puerta de Isengard", "The Gatekeepers of Isengard", 106, 73, 0, 5, 1200, "Jinetes de Teodred", "Derribapuertas", "Saruman ha colocado a dos de sus más poderosos sirvientes para vigilar las puertas de Isengard y destruir a cualquiera que se acerque sin ser anunciado.", "Saruman has placed two of his most powerful servants to watch the gates of Isengard and destroy any who approach unannounced.", "Théodred's Riders", "Gatecrasher" }
