I.D[1879222054] = { "Las Aventuras de Floid y Dewitt", "The Adventures of Floid and Dewitt", 103, 0, 0, 0, 0, "", "el Explorador / la Exploradora", "Eres un gran explorador de la Tierra Media. ¡Seguramente no tendrás problemas para localizar a otros grandes aventureros en sus expediciones!", "You are a great explorer of Middle-earth. Surely you'll have no trouble locating other great adventurers on their expeditions!", "", "the Wanderer" }
