I.O[1879227965] = { { "At the Ox-clan merchant-camp in Nan Curunír, you found many pipes leading into Isengard....", "At the Ox-clan merchant-camp in Nan Curunír, you found many pipes leading into Isengard....", "At the Ox-clan merchant-camp in Nan Curunír, you found many pipes leading into Isengard....", "At the Ox-clan merchant-camp in Nan Curunír, you found many pipes leading into Isengard...." } }
I.D[1879230964] = { "Explorador / Exploradora de Parth Celebrant", "Parth Celebrant Explorer", 103, 68, 2000, 5, 500, "Los Jinetes de Stangard", "Explorador de Parth Celebrant", "Parth Celebrant es un antiguo cruce de caminos y campo de batalla que tiene una gran importancia para los Rohirrim como el lugar de nacimiento de su reino.", "Parth Celebrant is an old cross-roads and battlefield that holds a long significance to the Rohirrim as the birthplace of their kingdom.", "The Riders of Stangard", "Explorer of Parth Celebrant" }
I.O[1879230964] = { { "Idmar's Camp", "Idmar's Camp", "Este es el campamento del guardián rohirrim Idmar.", "This is the camp of the Rohirrim warden Idmar." }, { "Field of Celebrant", "Field of Celebrant", "Este gran campo es donde tuvo lugar la Batalla del Campo del Celebrant, cuando los Hombres de Gondor y los Hombres del Norte expulsaron a la Horda de Orientales, y Rohan se convirtió en una nación.", "This great field is where the Battle of the Field of Celebrant took place, when the Men of Gondor and Men of the North drove forth the Easterling Horde, and Rohan became a nation." }, { "Hordfierd", "Hordfierd", "Hordfierd es una fortaleza erigida por los bandidos que se infiltraron en Parth Celebrant para robar las reliquias allí... solo para ser influenciados por los siervos de Mordor.", "Hordfierd is a fortress erected by the brigands who stole into Parth Celebrant to thieve the relics there... only to be swayed by the servants of Mordor." }, { "Ost Celebrant", "Ost Celebrant", "Ost Celebrant fue una vez una gran fortaleza de Gondor antes de caer ante la traición de los Perjuros. Ahora alberga las sombras de los traidores y sus malvados aliados.", "Ost Celebrant was once a great fortress of Gondor before it fell to the treachery of Oathbreakers. Now it houses the shades of the betrayers and their evil allies." }, { "La Fosa Asesina", "The Murderous Pit", "Este lugar se ha convertido en la guarida de una manada de lobos hambrientos, que se han vuelto caníbales por la falta de comida.", "This place has become the den of a pack of ravenous wolves, which have turned to cannibalism for the lack of food." } }
