I.D[1879230979] = { "Explorador / Exploradora de Thinglad", "Thinglad Explorer", 103, 68, 2000, 5, 500, "Los Jinetes de Stangard", "Explorador de Thinglad", "Los Elfos de Lórien tienen un puesto avanzado en los bosques poco conocidos de Thinglad, un lugar gris en invierno que se extiende a lo largo del borde del Gran Río.", "The Elves of Lórien have an outpost in the little-known woods of Thinglad, a grey place in winter that runs along the edge of the Great River.", "The Riders of Stangard", "Explorer of Thinglad" }
I.O[1879230979] = { { "Foul-maw's Den", "Foul-maw's Den", "Fauces Hediondas es un oso viejo y feo, enorme y de temperamento horrible.", "Foul-maw is an old and ugly bear, huge and horrible of temper." }, { "Haldirith", "Haldirith", "Haldirith, un jardín en ruinas de los Elfos, es donde las centinelas de Thinglad han hecho su hogar.", "Haldirith, a ruined garden of the Elves, is where the sentinels of Thinglad have made their home." }, { "Las Viejas Madrigueras", "The Old Burrows", "La guarida, abandonada durante mucho tiempo por sus antiguos habitantes, ha sido recientemente reclamado por voraces Huargos.", "The den, long abandoned by its former inhabitants, has been lately reclaimed by vicious Wargs." }, { "Ûngund", "Ûngund", "Los orcos han comenzado a asentarse en Thinglad por primera vez en muchos años. Esto es seguramente un signo de días malos por venir.", "Orcs have begun to settle in Thinglad for the first time in many a year. This is surely a sign of evil days to come." }, { "Hîs-urdan", "Hîs-urdan", "Los orcos parecen estar en todas partes estos días, incluso en los bosques antes pacíficos de Thinglad, tan cerca del borde de Lórien.", "Orcs seem to be everywhere these days, even in the once-peaceful woods of Thinglad, so near to Lórien's edge." } }
I.D[1879230981] = { "Los Espíritus del Limclaro", "The Spirits of the Limlight", 104, 68, 0, 10, 1200, "Héroes de la Garganta del Limclaro", "Cronista del Crepúsculo", "Ordhrien ha sugerido que intentes hablar con los espíritus de la Garganta del Limclaro. Los Elfos de Lothlórien una vez se comunicaron con estos espíritus y afirman que solo pueden ser vistos a la luz de las estrellas.", "Ordhrien has suggested that you attempt to speak with the spirits of the Limlight Gorge. The Elves of Lothlórien once communed with these spirits and claim that they can only be seen by the light of the stars.", "Heroes of Limlight Gorge", "Chronicler of Twilight" }
I.O[1879230981] = { { "Termina the quest 'Fallen Stones and Forgotten Tales'", "Complete the quest 'Fallen Stones and Forgotten Tales'", "", "" }, { "Habla con el Espíritu de la Reverencia", "Speak with the Spirit of Reverence", "", "" }, { "Habla con el Espíritu del Recuerdo", "Speak with the Spirit of Remembrance", "", "" }, { "Habla con el Espíritu de la Amistad", "Speak with the Spirit of Amity", "", "" }, { "Habla con el Espíritu de la Melodía", "Speak with the Spirit of Melody", "", "" }, { "Habla con el Espíritu de la Iluminación", "Speak with the Spirit of Enlightenment", "", "" }, { "Habla con el Espíritu del Destino", "Speak with the Spirit of Destiny", "", "" } }
I.D[1879230984] = { "Ruinas antiguas del Limclaro", "Ancient Ruins of the Limlight", 103, 68, 0, 10, 1200, "Héroes de la Garganta del Limclaro", "", "Busca rastros del antiguo legado de la Garganta del Limclaro, cuando aún formaba parte del Bosque de Oro hace muchas eras.", "Look for traces of the ancient legacy of the Limlight Gorge, when it was still a part of the Golden Wood ages ago.", "Heroes of Limlight Gorge", "" }
I.O[1879230984] = { { "Ruinas Antiguas", "Ancient Ruins", "Algunas piedras antiguas permanecen aquí entre las rocas. Es difícil decirlo, pero podrían ser de fabricación élfica.", "A few Ancient stones remain here among the rocks. It is hard to say, but they may be of Elf-make." }, { "Ruinas Misteriosas", "Mysterious Ruins", "Los pocos restos de mampostería y trabajo en piedra que encontraste sugieren que los Elfos vivieron aquí en algún momento... pero debe haber pasado al menos una era del mundo desde entonces.", "The few remaining chunks of masonry and stonework you found suggest that the Elves once lived here...but it must have been an age of the world at least since that time." }, { "Ruinas Caídas", "Tumbled Ruins", "Cubiertas de antiguos líquenes, encuentras los últimos restos desmoronados de una ruina élfica. ¿Qué propósito podrían haber tenido los Elfos hace tanto tiempo que los llevó hasta aquí?", "Covered with ancient lichens, you find the final crumbling remnants of an Elf-ruin. What purpose could the Elves have had so long ago that brought them here?" }, { "Ruinas Santificadas", "Hallowed Ruins", "Estas ruinas parecen aún más antiguas que las demás, si es que eso es posible. Ni siquiera puedes empezar a adivinar cuál podría haber sido su propósito.", "These ruins look even older than the rest, if that is possible. You cannot even begin to guess at what their purpose might have been." }, { "Ruinas Grabadas", "Engraved Ruins", "Estas viejas ruinas élficas parecen tener algunas marcas extrañas grabadas en ellas. Tienes bastante dificultad para descifrar las extrañas runas, hasta que finalmente te das cuenta de que son...", "These old Elf-ruins appear to have some strange markings carved upon them. You have some considerable difficulty deciphering the odd runes, until finally you realize that they are rather recent..." }, { "Ruinas Desmoronadas", "Crumbling Ruins", "Estas ruinas son tan antiguas que no hay señales de lo que las llevó a este estado, ya sea la guerra, la calamidad o el paso de un vasto período de tiempo que las redujo a casi nada.", "These ruins are so ancient that there is no sign of what brought them to this state, whether it was war, calamity, or the passing of some vast span of time that crumbled them to all but nothing." } }
I.D[1879230985] = { "Explorador / Exploradora del Juncal", "Rushgore Explorer", 103, 68, 2000, 5, 500, "Los Jinetes de Stangard", "Explorador del Juncal", "Los pantanos del Juncal han estado deshabitados durante mucho tiempo... o eso creían los guardias fronterizos de Rohan. Además de las bestias salvajes, villanos de una variedad bípedas han llegado recientemente...", "The marshes of the Rushgore have long been uninhabited... or so the border-guard of Rohan believed. Besides wild beasts, villains of a two-legged variety have recently come....", "The Riders of Stangard", "Explorer of the Rushgore" }
I.O[1879230985] = { { "Aculf's Camp", "Aculf's Camp", "El pequeño campamento está ocupado por Aculf y sus compañeros... una pequeña patrulla para vigilar lo que se suponía que era un territorio deshabitado...", "The small camp-site is held by Aculf and his companions... a small patrol to watch over what was supposed to be uninhabited territory...." }, { "Atburg", "Atburg", "Este campamento se estableció como un punto de paso para los bandidos de las Tierras Pardas que buscan saquear Parth Celebrant en busca de reliquias antiguas.", "This encampment was established as a waypoint for the brigands of the Brown Lands who seek to plunder Parth Celebrant for ancient relics." }, { "Wyrmdenn", "Wyrmdenn", "Este lugar es el terreno de cría de los avancs del Juncal... un lugar peligroso para los incautos.", "This place is the breeding ground for the avanc of the Rushgore... a dangerous place for the unwary." }, { "The Creeping Mud", "The Creeping Mud", "El Lodazal Rastrero es, de hecho, un nido de viles grodbogs que habitan el Juncal.", "The Creeping Mud is, in fact, a nest of vile gredbyg which dwell in the Rushgore." }, { "Tik Botokh", "Tik Botokh", "Tik Botokh es un campamento de exploradores de una tribu de los Hombres Orientales llamada los Khundolar, descendientes de la Horda que luchó contra Gondor y los antepasados de los Rohirrim en el...", "Tik Botokh is an encampment of scouts for an Easterling tribe called the Khundolar, descendants of the Horde who battled Gondor and the ancestors of the Rohirrim at the Field of Celebrant." }, { "The Clutch-ground", "The Clutch-ground", "Tortugas de gran tamaño habitan el Juncal, y este es su lugar de anidación.", "Turtles of great size inhabit the Rushgore, and this is their nesting place." } }
I.D[1879230987] = { "Azote de sombras (Avanzado)", "Shade-slayer (Advanced)", 106, 68, 2000, 10, 700, "Los Jinetes de Stangard", "", "Derrota a muchas sombras en el Gran Río.", "Defeat many Shades in the Great River.", "The Riders of Stangard", "" }
I.O[1879230987] = { { "Termina the deed 'Azote de sombras'", "Complete the deed 'Shade-slayer'", "", "" }, { "Derrota a las sombras en el Gran Río x200", "Defeat Shades in the Great River x200", "", "" } }
I.D[1879230991] = { "Explorador / Exploradora de las Colinas de los Lamentos", "Wailing Hills Explorer", 103, 68, 2000, 5, 500, "Los Jinetes de Stangard", "Explorador de las Colinas de los Lamentos", "Las Colinas de los Lamentos, al noroeste de Stangard, reciben su nombre debido a una gran batalla y la masacre de orcos que ocurrió allí hace muchos años, alrededor de la época de la fundación de Rohan.", "The Wailing Hills, north-west of Stangard, are so named due to a great battle and the slaughtering of Orcs that occured there many years ago, around the time of Rohan's founding.", "The Riders of Stangard", "Explorer of the Wailing Hills" }
I.O[1879230991] = { { "The Cuthstan", "The Cuthstan", "La Piedra de la Amistad, donde Cirion, el Senescal de Gondor, y Eorl, el primer Rey de Rohan, se encontraron en el campo de batalla como aliados victoriosos. El monumento conmemora su juramento de...", "The Stone of Friendship, where Cirion, the Steward of Gondor, and Eorl, the first King of Rohan, met on the battlefield as victorious allies. The monument commemorates their oath of friendship and..." }, { "Frithstan's Camp", "Frithstan's Camp", "Un pequeño grupo de Rohirrim, liderado por Frithstan, guarda el sur de las Colinas de los Lamentos. Su tarea principal es proteger el monumento Cuthstan.", "A small group of Rohirrim, led by Frithstan, guard the south of the Wailing Hills. Their primary task is to keep safe the Cuthstan monument." }, { "Nink-hai Camp", "Nink-hai Camp", "Este es un campamento orco recientemente construido. Los nink-hai han tenido el valor de abandonar sus hogares en las montañas para vivir en cabañas y tiendas a lo largo del borde norte del río...", "This is a recently constructed Orc-encampment. The Nink-hai have boldly abandoned their mountain homes to live in huts and tents along the northern edge of the Limlight River." }, { "Mor-hai Settlement", "Mor-hai Settlement", "Los orcos mor-hai han crecido en número y tenacidad. Han comenzado a construir campamentos de guerra más allá de la seguridad de sus oscuros hogares en las montañas, para provocar más directamente a...", "The Mor-hai Orcs have grown in number and tenacity. They have begun constructing war-camps beyond the safety of their dark mountain dwellings, in order to more directly provoke the Men of Stangard..." }, { "Claro Aislado", "Secluded Clearing", "Landroval y Meneldor, dos de las Grandes Águilas al servicio de Gwaihir el Señor del Viento, seleccionaron este claro aislado como un lugar seguro para reagruparse, después de dividirse para buscar...", "Landroval and Meneldor, two of the Great Eagles in service to Gwaihir the Windlord, selected this secluded clearing as a safe location to regroup, after splitting up to search the area." }, { "Cueva del Mordisco Venenoso", "Venom-Bite Cave", "Esta gran cueva en la ladera de la montaña es el principal lugar de cría de las arañas Mordisco Venenoso, una especie conocida por sus colmillos venenosos.", "This large cave in the mountainside is the central breeding grounds for the Venom-bite spiders, a breed renowned for their venomous fangs." }, { "Aster Hill", "Aster Hill", "Nombrada por las brillantes flores en forma de estrella que cubren cada cresta, esta colina se ha convertido en un lugar de pastoreo favorito para las cabras salvajes nativas de la región.", "Named for the bright star-shaped flowers that blanket each ridge, this hilltop has become a favourite grazing spot for the wild goats native to the region." } }
