I.D[1879231004] = { "Explorador / Exploradora del Prado de Eorl", "Eorlsmead Explorer", 103, 68, 2000, 5, 500, "Los Jinetes de Stangard", "Explorador del Prado de Eorl", "El Prado de Eorl se encuentra en la distante frontera norte de Rohan, un puesto de vigilancia contra los males del norte.", "Eorlsmead is on the distant northern border of Rohan, a watch-post against the evils of the north.", "The Riders of Stangard", "Explorer of Eorlsmead" }
I.O[1879231004] = { { "The Abandoned Farm", "The Abandoned Farm", "Esta granja fue una vez cuidada con amor por los agricultores de Stangard, pero ha sido abandonada durante mucho tiempo.", "This farm was once lovingly tended by farmers of Stangard, but it has been long left abandoned." }, { "The Foetid Caves", "The Foetid Caves", "Estas cuevas son el refugio de una manada de perros salvajes, que acechan a los hombres de Stangard.", "These caves are den to a pack of wild dogs, which haunt the Men of Stangard." }, { "Stangard", "Stangard", "Has descubierto el gran asentamiento rohirrim de Stangard, la vigía del norte de Rohan. Lo encuentras un poco más deteriorado de lo que esperabas para una ciudad tan grande.", "You have discovered the great Rohirrim settlement of Stangard, the north watch of Rohan. You find it is a bit shabbier than you expected from so great a town." }, { "Torre del Prado de Eorl", "Eorlsmead Tower", "Una gran torre de propósito cuestionable, que se yergue en su vigilancia sobre el Prado de Eorl.", "A great tower of questionable purpose, standing tall in its watch over Eorlsmead." }, { "The Teeming Nest", "The Teeming Nest", "Te has topado con un desafortunado conjunto de túneles excavados por gusanos viles en el Prado de Eorl.", "You have happened upon an unfortunate set of tunnels carved out by vile worms in Eorlsmead." } }
