I.D[1879231013] = { "Explorador / Exploradora de las Tierras Pardas", "Brown Lands Explorer", 103, 68, 2000, 5, 500, "Los Jinetes de Stangard", "Explorador de las Tierras Pardas", "Las Tierras Pardas fueron una vez una tierra verde, llena de vegetación, hasta que la guerra y la corrupción las convirtieron en un páramo desolado.", "The Brown Lands were once a green land, lush with vegetation, until war and corruption turned them into a desolate waste-land.", "The Riders of Stangard", "Explorer of the Brown Lands" }
I.O[1879231013] = { { "Etheburg", "Etheburg", "Etheburg es un puesto de avanzada de la guardia fronteriza de los Rohirrim. Es el último bastión de defensa para los Rohirrim antes de entrar en la propia Marca de los Jinetes.", "Etheburg is a way-post of the Rohirrim border-guard. It is the last bastion of defence for the Rohirrim before entering the Riddermark itself." }, { "Helstor", "Helstor", "Durante mucho tiempo, los bandidos y rufianes han utilizado las Tierras Pardas como escondite. Helstor es su último refugio en ese lugar desolado.", "Long have brigands and ruffians used the Brown Lands as a hideaway. Helstor is their last refuge in that desolate place." }, { "Lashkarg", "Lashkarg", "Los Khundolar, orientales descendientes de la Horda que luchó contra los Señores de Gondor y los antepasados de los Rohirrim en el Campo del Celebrant, han regresado, preparados para la guerra...", "The Khundolar, Easterlings descended from the Horde that fought the Lords of Gondor and the ancestors of the Rohirrim at the Field of Celebrant, have returned, prepared for war...." }, { "Desolation of the Gardens", "Desolation of the Gardens", "Estos antiguos y arruinados jardines florecieron una vez bajo las cuidadosas manos de las Ents mujeres antes de que la guerra los devastara", "These ancient and ruined gardens once blossomed at the caring hands of the Entwives before war ravaged them." }, { "El Agujero de Piedra", "The Stone-hole", "Esta red de cuevas alberga a una tribu de trolls salvajes, que han elegido habitar las Tierras Pardas", "This network of caves houses a tribe of wild trolls, who have chosen to inhabit the Brown Lands" } }
I.D[1879231935] = { "Descubrimiento: Raíces de Fangorn", "Discovery: Roots of Fangorn", 103, 75, 0, 10, 700, "Héroes de la Garganta del Limclaro", "", "Has descubierto la entrada a las Raíces de Fangorn.", "You have discovered the entrance to the Roots of Fangorn.", "Heroes of Limlight Gorge", "" }
I.O[1879231935] = { { "Has descubierto la entrada a las Raíces de Fangorn", "You have discovered the entrance to the Roots of Fangorn", "Has descubierto la entrada a las Raíces de Fangorn", "You have discovered the entrance to the Roots of Fangorn" } }
I.D[1879233865] = { "Explorador / Exploradora de Stangard", "Stangard Explorer", 103, 68, 0, 5, 500, "Los Jinetes de Stangard", "el Intruso", "Descubre todos los interiores de Stangard.", "Discover all of Stangard's interiors.", "The Riders of Stangard", "the Trespasser" }
I.O[1879233865] = { { "El Salón del Hidromiel de Stangard es donde Stanric y los otros Rohirrim llevan a cabo la mayoría de sus...", "The Mead Hall of Stangard is where Stanric and the other Rohirrim conduct the majority of their business.", "El Salón del Hidromiel de Stangard es donde Stanric y los otros Rohirrim llevan a cabo la mayoría de sus asuntos.", "The Mead Hall of Stangard is where Stanric and the other Rohirrim conduct the majority of their business." }, { "El calabozo está custodiado de cerca por Cynred, y nadie puede entrar sin el permiso estricto de los líderes...", "The lockhouse is guarded closely by Cynred, and none may enter without strict permission from the leadership...", "El calabozo está custodiado de cerca por Cynred, y nadie puede entrar sin el permiso estricto de los líderes de Stangard. Aquí se guardan todas las cosas que deben estar bajo llave, desde los...", "The lockhouse is guarded closely by Cynred, and none may enter without strict permission from the leadership of Stangard. Here are all things that must be locked up, from food-stores to prisoners." }, { "La Sala de Escaramuzas es donde se llevan a cabo todos los asuntos relacionados con las escaramuzas.", "The Skirmish Hall is where all skirmish-related business is done.", "La Sala de Escaramuzas es donde se llevan a cabo todos los asuntos relacionados con las escaramuzas.", "The Skirmish Hall is where all skirmish-related business is done." }, { "La Sala de Subastas es raramente utilizada por los Hombres de Stangard, pero aquí se pueden ver las Subastas...", "The Auction Hall is rarely used by the Men of Stangard, but the Auctions of Middle-earth can be viewed here.", "La Sala de Subastas es raramente utilizada por los Hombres de Stangard, pero aquí se pueden ver las Subastas de la Tierra Media.", "The Auction Hall is rarely used by the Men of Stangard, but the Auctions of Middle-earth can be viewed here." }, { "La Bóveda de Stangard ofrece el lugar más seguro para guardar tus objetos más preciados.", "The Stangard Vault offers only the most secure place to store your cherished items.", "La Bóveda de Stangard ofrece el lugar más seguro para guardar tus objetos más preciados.", "The Stangard Vault offers only the most secure place to store your cherished items." }, { "Cuando las cargas del día se vuelven abrumadoras, la Taberna de Stangard sirve como un lugar para relajarse y...", "When the burdens of the day become overwhelming, the Stangard Tavern serves as a place to relax and quench...", "Cuando las cargas del día se vuelven abrumadoras, la Taberna de Stangard sirve como un lugar para relajarse y saciar la sed.", "When the burdens of the day become overwhelming, the Stangard Tavern serves as a place to relax and quench thirsts." }, { "Esta casa cerca del Salón del Hidromiel es el hogar de Stanric, el señor de Stangard.", "This house near the Mead Hall is home to Stanric, the lord of Stangard.", "Esta casa cerca del Salón del Hidromiel es el hogar de Stanric, el señor de Stangard.", "This house near the Mead Hall is home to Stanric, the lord of Stangard." }, { "Athulf se encarga solo de los amables perros que habitan el canil de Stangard.", "Athulf alone cares for the gentle dogs that inhabit the kennel of Stangard.", "Athulf se encarga solo de los amables perros que habitan el canil de Stangard.", "Athulf alone cares for the gentle dogs that inhabit the kennel of Stangard." }, { "El mal tiempo puede obligar a los caballos de Stangard a permanecer en el interior. Este establo ayuda a...", "Undesired weather can force the horses of Stangard indoors. This stable helps provide warmth during the...", "El mal tiempo puede obligar a los caballos de Stangard a permanecer en el interior. Este establo ayuda a proporcionar calor durante los meses de invierno.", "Undesired weather can force the horses of Stangard indoors. This stable helps provide warmth during the winter months." }, { "Esta es la casa del trabajador Wada, un residente sobrecargado de trabajo y mal alimentado de Stangard.", "This is the home of the workman Wada, an overworked and underfed resident of Stangard.", "Esta es la casa del trabajador Wada, un residente sobrecargado de trabajo y mal alimentado de Stangard.", "This is the home of the workman Wada, an overworked and underfed resident of Stangard." }, { "La tienda de objetos legendarios emplea a los únicos dos soldados en Stangard que han dominado la forja y la...", "The Legendary Item Store employs the only two soldiers in Stangard that have mastered the Forging and Imbuing...", "La tienda de objetos legendarios emplea a los únicos dos soldados en Stangard que han dominado la forja y la imbuición de objetos legendarios.", "The Legendary Item Store employs the only two soldiers in Stangard that have mastered the Forging and Imbuing of Legendary Items." }, { "El proveedor vive aquí, pero los suministros en esta casa le pertenecen a él, no a ti.", "The Supplier lives here, but the supplies in this house belong to him, not to you.", "El proveedor vive aquí, pero los suministros en esta casa le pertenecen a él, no a ti.", "The Supplier lives here, but the supplies in this house belong to him, not to you." }, { "El aprovisionador vive aquí, pero las provisiones en esta casa le pertenecen a él, no a ti.", "The Provisioner lives here, but the provisions in this house belong to him, not to you.", "El aprovisionador vive aquí, pero las provisiones en esta casa le pertenecen a él, no a ti.", "The Provisioner lives here, but the provisions in this house belong to him, not to you." }, { "Byrnstan es un guardia leal del Salón del Hidromiel y realiza su trabajo con poca compensación.", "Byrnstan is a loyal guard of the Mead Hall, and does his work with little compensation.", "Byrnstan es un guardia leal del Salón del Hidromiel y realiza su trabajo con poca compensación.", "Byrnstan is a loyal guard of the Mead Hall, and does his work with little compensation." }, { "La casa de Dunstan ahora está desocupada, ya que este valiente cazador fue asesinado por Orcos en Thinglad....", "Dunstan's home is now unoccupied, for this brave hunter was slain by Orcs in Thinglad. He will never sleep in...", "La casa de Dunstan ahora está desocupada, ya que este valiente cazador fue asesinado por Orcos en Thinglad. Nunca volverá a dormir en su cama, pues su tumba está bajo los aleros de los grandes...", "Dunstan's home is now unoccupied, for this brave hunter was slain by Orcs in Thinglad. He will never sleep in his bed again, for his grave is under the eaves of the great trees of Thinglad." }, { "Uthrad es un guardia leal a Sithric. Es mejor no enfrentarse a él.", "Uthrad is a guard loyal to Sithric. It is best not to cross him.", "Uthrad es un guardia leal a Sithric. Es mejor no enfrentarse a él.", "Uthrad is a guard loyal to Sithric. It is best not to cross him." }, { "Tatwine es un agricultor amable que cuida de los caballos de Stangard, día tras día. No desea nada más que un...", "Tatwine is a gentle farmer who tends the horses of Stangard, day in and day out. He wants nothing more than...", "Tatwine es un agricultor amable que cuida de los caballos de Stangard, día tras día. No desea nada más que un poco de tierra para cultivar, pero no se le permite realizar ninguna labor agrícola.", "Tatwine is a gentle farmer who tends the horses of Stangard, day in and day out. He wants nothing more than some land to tend, but he is not permitted to do any farming." }, { "Abandonada desde hace mucho tiempo, esta casa infunde miedo en los corazones de todos los habitantes de...", "Long Abandoned, this home strikes fear into the hearts of any man living in Stangard. All those that enter...", "Abandonada desde hace mucho tiempo, esta casa infunde miedo en los corazones de todos los habitantes de Stangard. Todos los que entran nunca se vuelven a escuchar o ver.", "Long Abandoned, this home strikes fear into the hearts of any man living in Stangard. All those that enter are never heard or seen from again." }, { "Adalbert es un guardia leal a Stanric. Es mejor no enfrentarse a él.", "Adalbert is a guard loyal to Stanric. It is best not to cross him.", "Adalbert es un guardia leal a Stanric. Es mejor no enfrentarse a él.", "Adalbert is a guard loyal to Stanric. It is best not to cross him." }, { "Sabert es tu amigo. Él guarda la puerta principal de Stangard y te saluda cada vez que entras y sales.", "Sabert is your friend. He guards the front gate of Stangard, and greets you whenever you come and go.", "Sabert es tu amigo. Él guarda la puerta principal de Stangard y te saluda cada vez que entras y sales.", "Sabert is your friend. He guards the front gate of Stangard, and greets you whenever you come and go." } }
I.D[1879244108] = { "Explorador / Exploradora de la Muralla del Este", "East Wall Explorer", 103, 70, 2000, 5, 0, "", "Vigilante", "Los acantilados y las laderas cubiertas de árboles de esta región montañosa sirven como límite oriental del reino de Rohan, y como el alcance más septentrional del reino de Gondor en la actualidad.", "The cliffs and tree-clad slopes of this hilly region serve as the eastern boundary of the kingdom of Rohan, and the northernmost reach of the kingdom of Gondor today.", "", "Watcher" }
I.O[1879244108] = { { "Campamento de Mansig", "Mansig's Encampment", "Este campamento de los Rohirrim proviene principalmente del Páramo, pero hay representantes de todo el reino de Rohan. Llegaron a la Muralla del Este bajo el mando de Mansig. Su propósito era...", "This camp of Rohirrim hail primarily from the Wold, but there are representatives from throughout the kingdom of Rohan. They came to the East Wall under the command of Mansig. Their purpose was to..." }, { "Claro del Orco Muerto", "Dead Orc Glade", "Más de una docena de Orcos yacen muertos en un claro no muy lejos de Amon Hen. ¿Qué ocurrió aquí?", "More than a dozen Orcs lie dead in a glade not far from Amon Hen. What happened here?" }, { "Parth Galen", "Parth Galen", "La pradera de Parth Galen sería un buen lugar para acampar para cualquier viajero obligado a desembarcar del río, pero está completamente a la vista de la orilla lejana y podría ser peligroso.", "The grassy lawn of Parth Galen would serve as a good location for the camp-site of any travellers forced to disembark the river, but it is in full view of the far shore and could be dangerous." }, { "The Tindrock", "The Tindrock", "El Tindrock es un gran espolón de roca que divide las aguas del Anduin mientras se precipitan hacia las Cataratas de Rauros. Llamado Tol Brandir por los Elfos, se dice que es imposible de escalar.", "The Tindrock is a great spur of rock that divides the waters of the Anduin as they rush towards the Falls of Rauros. Called Tol Brandir by the Elves, it is said to be unclimbable." }, { "Falls of Rauros", "Falls of Rauros", "Las grandes Cataratas de Rauros descienden desde los acantilados con un rugido atronador. Seguir el río por el borde significa la muerte.", "The great Falls of Rauros descend from the cliffs with a booming roar. To follow the river over the edge means death." }, { "Amon Hen", "Amon Hen", "Amon Hen es una de las dos colinas que se elevan a ambos lados del Anduin en las Cataratas de Rauros. Los antiguos reyes se sentaban en el Trono de la Vista en su cima y veían muchas cosas útiles...", "Amon Hen is one of the two hills that rise on either side of the Anduin at the Falls of Rauros. The kings of old once sat upon the Seat of Seeing at its summit and saw many things of use to them." }, { "Sutcrofts Barricade", "Sutcrofts Barricade", "Los orcos de la Muralla del Este han erigido una barricada para evitar que los viajeros entren en la Muralla del Este desde los Sutcrofts.", "The Orcs in the East Wall have erected a barricade to keep travellers from coming into the East Wall from the Sutcrofts." }, { "The North-guard", "The North-guard", "El Puesto del Norte es una cámara dominada por los orcos de Moria en los túneles bajo la Muralla del Este.", "The North-guard is a chamber dominated by the Orcs of Moria in the tunnels beneath the East Wall." }, { "La Fosa Silbante", "The Hissing Pit", "Esta cámara está llena de gredbyg. Es posible que otros túneles bajo la Muralla del Este también estén infestados con estas criaturas.", "This chamber is full of gredbyg. It is possible other tunnels beneath the East Wall are infested with the creatures as well." }, { "The South-guard", "The South-guard", "Esta es la cámara más al sur de los túneles bajo la Muralla del Este, y está llena de orcos de Moria.", "This is the southernmost chamber of the tunnels beneath the East Wall, and it is full of Orcs from Moria." } }
I.D[1879249010] = { "Azote de orcos del Estemnet", "Orc-slayer of the Eastemnet", 106, 72, 0, 5, 0, "", "", "Deberías vencer a los orcos en el Estemnet.", "You should slay Orcs in the Eastemnet.", "", "" }
I.O[1879249010] = { { "Derrota a los orcos en el Estemnet x100", "Defeat Orcs in the Eastemnet x100", "", "" } }
I.D[1879249136] = { "Ciudades de Rohan Oriental", "Cities of Eastern Rohan", 103, 72, 2000, 5, 0, "", "Colono", "Rohan es hogar de muchas grandes ciudades y asentamientos.", "Rohan is home to many great cities and settlements.", "", "Settler" }
I.O[1879249136] = { { "Largafortín", "Langhold", "Has descubierto Largafortín, la ciudad más al norte del Páramo. Vigila contra los bandidos invasores y los Orientales.", "You have discovered Langhold, the northernmost city of the Wold. It stands guard against invading brigands and Easterlings." }, { "Harwick", "Harwick", "Harwick es una gran ciudad del Páramo, donde reside el Harding, el severo Aldor.", "Harwick is a large city of the Wold, home to Harding, the stern Aldor." }, { "Recodo de la Crecida", "Floodwend", "Has encontrado el Recodo de la Crecida, una bella ciudad cerca de los rápidos de Sarn Gebir. Está gobernada por Radwig, un Thane muy joven.", "You have found Floodwend, a fair city near the rapids of Sarn Gebir, governed by a very young Thane, Radwig." }, { "Cliving", "Cliving", "Cliving es una gran ciudad en los Norcrofts, hogar del Reeve, Athelward.", "Cliving is a great city in the Norcrofts, home to the Reeve, Athelward." }, { "Elthengels", "Elthengels", "La ciudad de Elthengels en los Norcrofts está gobernada por la Thane Mildrith, una mujer valiente y orgullosa.", "The Norcrofts city of Elthengels is presided over by Thane Mildrith, a fearless and proud woman." }, { "Redilaldea", "Faldham", "Has descubierto la ciudad de Redilaldea.", "You have discovered the town of Faldham." }, { "Eaworth", "Eaworth", "Has descubierto la ciudad de Eaworth, gobernada por el leal Reeve Ingbert.", "You have discovered the town of Eaworth, ruled over by the loyal Reeve Ingbert." }, { "Valle del Espino", "Thornhope", "Has descubierto Valle del Espino vacía de todos sus habitantes, llena de cenizas, humo y muerte causada por los enemigos de Rohan.", "You have found Thornhope empty of all inhabitants, filled with ash, smoke, and death wrought by the enemies of Rohan." }, { "Río Nevado", "Snowbourn", "Río Nevado es la ciudad más grande de los Sutcrofts, donde Fastred es Thane. Los orcos rodean y amenazan esta gran ciudad y a todos los que viven allí.", "Snowbourn is the largest city in the Sutcrofts, where Fastred is Thane. Orcs surround and threaten this great city and all who live there." }, { "Campo de Lanzas", "Garsfeld", "Campo de Lanzas es una ciudad principal en los Sutcrofts, gobernada por el Thane Gísil.", "Garsfeld is a principal city in the Sutcrofts, governed by Thane Gísil." } }
I.D[1879249651] = { "Azote de bestias del Estemnet", "Beast-slayer of the Eastemnet", 106, 72, 0, 5, 0, "", "", "Los cazadores en el Estemnet de Rohan no carecen de presas, ya que las praderas están llenas de todo tipo de criaturas.", "Huntsmen in the Eastemnet of Rohan find no lack of beasts for prey, for the grasslands are rife with all sorts of creatures.", "", "" }
