I.D[1879249693] = { "Azote de semiorcos del Estemnet (Avanzado)", "Half-orc Slayer of the Eastemnet (Advanced)", 106, 72, 2000, 5, 0, "", "Azote de semiorcos de Rohan Oriental", "Los semiorcos son más crueles que los Hombres más crueles debido a su herencia orca, hostigando a la buena gente de Rohan.", "Half-orcs are crueler than even the cruelest Men because of their Orkish heritage, harrying the good people of Rohan.", "", "Half-orc Slayer of Eastern Rohan" }
I.O[1879249693] = { { "Termina the deed 'Azote de Semiorcos del Estemnet'", "Complete the deed 'Half-orc Slayer of the Eastemnet'", "", "" }, { "Derrota a los semiorcos en el Estemnet x200", "Defeat half-orcs in the Eastemnet x200", "", "" } }
I.D[1879249694] = { "Azote de Semiorcos del Estemnet", "Half-orc Slayer of the Eastemnet", 106, 72, 0, 5, 0, "", "", "Los semiorcos son más crueles que los Hombres más crueles debido a su herencia orca, hostigando a la buena gente de Rohan.", "Half-orcs are crueler than even the cruelest Men because of their Orkish heritage, harrying the good people of Rohan.", "", "" }
I.O[1879249694] = { { "Derrota a los semiorcos en el Estemnet x100", "Defeat half-orcs in the Eastemnet x100", "", "" } }
I.D[1879249695] = { "Azote de bandidos del Estemnet", "Brigand-slayer of the Eastemnet", 106, 72, 0, 5, 0, "", "", "Los bandidos están entre los peores enemigos de la Tierra Media, ya que son hombres ordinarios, pero crueles y codiciosos en sus formas ilegales y destructivas.", "Brigands are among the worst enemies in Middle-earth, for they are ordinary Men, but cruel and greedy in their lawless, destructive ways.", "", "" }
I.O[1879249695] = { { "Derrota a los bandidos en el Estemnet x100", "Defeat brigands in the Eastemnet x100", "", "" } }
I.D[1879249696] = { "Azote de bandidos del Estemnet (Avanzado)", "Brigand-slayer of the Eastemnet (Advanced)", 106, 72, 2000, 5, 0, "", "Matador de bandidos de Rohan Oriental", "Los bandidos están entre los peores enemigos de la Tierra Media, ya que son hombres ordinarios, pero crueles y codiciosos en sus formas ilegales y destructivas.", "Brigands are among the worst enemies in Middle-earth, for they are ordinary Men, but cruel and greedy in their lawless, destructive ways.", "", "Brigand-slayer of Eastern Rohan" }
I.O[1879249696] = { { "Termina the deed 'Azote de bandidos del Estemnet'", "Complete the deed 'Brigand-slayer of the Eastemnet'", "", "" }, { "Derrota a los bandidos en el Estemnet x200", "Defeat brigands in the Eastemnet x200", "", "" } }
I.D[1879249707] = { "Azote de Huargos del Estemnet", "Warg-slayer of the Eastemnet", 106, 72, 0, 5, 0, "", "", "Los huargos en el Estemnet de Rohan parecen ser más fuertes y brutales que los de otras tierras, con las llanuras abiertas aumentando su velocidad y poder.", "Wargs in the Eastemnet of Rohan seem to be stronger and more brutal than those in other lands, with the open plains fueling their speed and power.", "", "" }
I.O[1879249707] = { { "Derrota a los huargos en el Estemnet x100", "Defeat Wargs in the Eastemnet x100", "", "" } }
I.D[1879249708] = { "Azote de Huargos del Estemnet (Avanzado)", "Warg-slayer of the Eastemnet (Advanced)", 106, 72, 2000, 5, 0, "", "Azote de Huargos de Rohan Oriental", "Los huargos en el Estemnet de Rohan parecen ser más fuertes y brutales que los de otras tierras, con las llanuras abiertas aumentando su velocidad y poder.", "Wargs in the Eastemnet of Rohan seem to be stronger and more brutal than those in other lands, with the open plains fueling their speed and power.", "", "Warg-slayer of Eastern Rohan" }
I.O[1879249708] = { { "Termina the deed 'Azote de Huargos del Estemnet'", "Complete the deed 'Warg-slayer of the Eastemnet'", "", "" }, { "Derrota a los huargos en el Estemnet x200", "Defeat Wargs in the Eastemnet x200", "", "" } }
I.D[1879249730] = { "Azote de arañas del Estemnet", "Spider-slayer of the Eastemnet", 106, 72, 0, 5, 0, "", "", "Las arañas no son más que la prole del mal absoluto, cubriendo todo lo que conquistan con telarañas pegajosas y sofocantes.", "Spiders are naught but the spawn of utter evil, covering all they conquer in sticky, smothering webs.", "", "" }
I.O[1879249730] = { { "Derrota a las arañas en el Estemnet x100", "Defeat spiders in the Eastemnet x100", "", "" } }
I.D[1879249731] = { "Azote de arañas del Estemnet (Avanzado)", "Spider-slayer of the Eastemnet (Advanced)", 106, 72, 2000, 5, 0, "", "Matador de arañas de Rohan Oriental", "Las arañas no son más que la prole del mal absoluto, cubriendo todo lo que conquistan con telarañas pegajosas y sofocantes.", "Spiders are naught but the spawn of utter evil, covering all they conquer in sticky, smothering webs.", "", "Spider-slayer of Eastern Rohan" }
I.O[1879249731] = { { "Termina the deed 'Azote de arañas del Estemnet'", "Complete the deed 'Spider-slayer of the Eastemnet'", "", "" }, { "Derrota a las arañas en el Estemnet x200", "Defeat spiders in the Eastemnet x200", "", "" } }
I.D[1879249732] = { "Azote de dragones del Estemnet", "Dragon-kind Slayer of the Eastemnet", 106, 72, 0, 5, 0, "", "", "Los dragonzuelos y las salamandras son criaturas mortales, sus duras escamas desvían las armas ordinarias y sus bocas están llenas de dientes afilados.", "Drakes and salamanders are deadly creatures, their hard scales deflecting ordinary blades, and their mouths full of sharp teeth.", "", "" }
I.O[1879249732] = { { "Derrota a los dragones en el Estemnet x100", "Defeat Dragon-kind in the Eastemnet x100", "", "" } }
I.D[1879249733] = { "Azote de dragones del Estemnet (Avanzado)", "Dragon-kind Slayer of the Eastemnet (Advanced)", 106, 72, 2000, 5, 0, "", "Matador de reptiles de Rohan Oriental", "Los dragonzuelos y las salamandras son criaturas mortales, sus duras escamas desvían las armas ordinarias y sus bocas están llenas de dientes afilados.", "Drakes and salamanders are deadly creatures, their hard scales deflecting ordinary blades, and their mouths full of sharp teeth.", "", "Reptile-slayer of Eastern Rohan" }
I.O[1879249733] = { { "Termina the deed 'Azote de dragones del Estemnet'", "Complete the deed 'Dragon-kind Slayer of the Eastemnet'", "", "" }, { "Derrota a los dragones en el Estemnet x200", "Defeat Dragon-kind in the Eastemnet x200", "", "" } }
I.D[1879250019] = { "Azote del mal ancestral del Estemnet", "Ancient Evil-slayer of the Eastemnet", 106, 72, 0, 5, 0, "", "", "Los Osos de púas, los draugars y los sabuesos de Swert merodean por las llanuras del Estemnet como temibles criaturas que han salido de un cuento infantil.", "Láthbears, draugar, and swert-hounds prowl the fair plains of the Eastemnet like fearsome creatures that crawled out of a children's tale.", "", "" }
I.O[1879250019] = { { "Derrota a los Osos de púas, los draugars y los sabuesos de Swert x100", "Defeat Láthbears, draugar, and swert-hounds x100", "", "" } }
I.D[1879250023] = { "Azote del mal ancestral del Estemnet (Avanzado)", "Ancient Evil-slayer of the Eastemnet (Advanced)", 106, 72, 2000, 5, 0, "", "matador del mal antiguo en Rohan Oriental", "Los Osos de púas, los draugars y los sabuesos de Swert merodean por las llanuras del Estemnet como temibles criaturas que han salido de un cuento infantil.", "Láthbears, draugar, and swert-hounds prowl the fair plains of the Eastemnet like fearsome creatures that crawled out of a children's tale.", "", "Slayer of Ancient Evil in Eastern Rohan" }
I.O[1879250023] = { { "Termina the deed 'Azote del mal ancestral del Estemnet'", "Complete the deed 'Ancient Evil-slayer of the Eastemnet'", "", "" }, { "Derrota a los Osos de púas, los draugars y los sabuesos de Swert x200", "Defeat láthbears, draugar, and swert-hounds x200", "", "" } }
I.D[1879250651] = { "Exploración de los Aleros de Fangorn", "Eaves of Fangorn Exploration", 103, 72, 2000, 5, 0, "", "explorador de Fangorn", "Explora Fangorn.", "Explore Fangorn.", "", "Explorer of Fangorn" }
I.O[1879250651] = { { "El Bastión de Seda", "The Silkenhold", "El Bastión de Seda está invadido por arañas malvadas que apagan la luz con sus telarañas, para gran disgusto de los árboles que viven allí.", "The Silkenhold is overrun with evil spiders who snuff out the light with their webs, much to the displeasure of the trees who live there." }, { "The Black Heart", "The Black Heart", "En lo más profundo de los Lindes de Fangorn se encuentra un tramo oscuro de bosque cubierto por sombras antiguas y fuertes.", "Deep in the deepest reaches of Fangorn's eaves is a dark stretch of forest covered by shadows old and strong." }, { "Hale-gap", "Hale-gap", "Un conjunto de altas piedras cubiertas de musgo se extiende a lo largo del borde del río Entwash en Fangorn, las rocas verdes y hermosas gracias al agua limpia que beben.", "A mossy set of tall stones runs along the edge of the Entwash River in Fangorn, the rocks green and lovely from the clean water they drink." }, { "Sweetmead", "Sweetmead", "El prado de Dulce Hidromiel lleva bien su nombre, ya que en medio de los grandes árboles se encuentra un prado que huele a miel suave y a dulce luz del sol.", "The meadow of Sweetmead is appropriately named, for in the midst of the thick trees is a meadow, smelling of gentle honey and sweet sunlight." }, { "Fogwater", "Fogwater", "Un gran y profundo estanque se encuentra en medio de Fangorn, traicioneramente oculto bajo su espeso velo de niebla. No puedes evitar preguntarte cuántas criaturas desprevenidas se han ahogado en sus...", "A large, deep pond stands still in the midst of Fangorn, treacherously hiding under its thick veil of fog. You cannot help but wonder how many unsuspecting creatures have drowned in the hidden depths." } }
I.D[1879251696] = { "Las tierras salvajes del Estemnet", "The Wilds of the Eastemnet", 103, 72, 2000, 5, 0, "", "Vigilante de lo Salvaje", "Explora las tierras salvajes de Rohan.", "Explore the wilds of Rohan.", "", "Watcher of the Wilds" }
I.O[1879251696] = { { "The Stinging Bog", "The Stinging Bog", "El Pantano Punzante se encuentra justo más allá de los muros de Harwick en el Páramo.", "The Stinging Bog lies just beyond the walls of Harwick in the Wold." }, { "Cracabor", "Cracabor", "Cracabor es la colina más alta del Páramo, con vistas a las llanuras cubiertas de hierba.", "Cracabor is the highest hill in the Wold, looking out over the grassy plains." }, { "The Croft-watch", "The Croft-watch", "Se rumorea que la Guardia de la Granja es el lugar más hermoso y pintoresco de los Sutcrofts.", "The Croft-watch is rumoured to be the fairest and most scenic place in the Sutcrofts." }, { "The Wódfen", "The Wódfen", "El Wódfen es un humedal en el Valle del Entaguas, plagado de salamandras y draugar que inducen la locura.", "The Wódfen is a wetland in the Entwash Vale, plagued by salamanders and madness-inducing draugar." }, { "Wild Horse Herd", "Wild Horse Herd", "Los caballos salvajes corren libres por las tierras de Rohan, y un grupo en particular de estas impresionantes bestias se puede encontrar en el Valle del Entaguas.", "Wild horses run free in the lands of Rohan, and one particular herd of these impressive beasts can be found in the Entwash Vale." } }
I.D[1879251703] = { "Las defensas de Rohan Oriental", "The Defences of Eastern Rohan", 103, 72, 2000, 5, 0, "", "Buscador de Fuertes", "Explora las defensas de Rohan.", "Explore the defences of Rohan.", "", "Fort-finder" }
I.O[1879251703] = { { "Atalaya de los Meandros", "Undeep Watch", "La Atalaya de los Meandros es el lugar donde los Rohirrim de Largafortín vigilan el vado para evitar que los Orientales crucen el río.", "The Undeep Watch is where the Rohirrim of Langhold keep watch upon the ford against the crossing of Easterlings." }, { "Feldburg", "Feldburg", "Feldburg es un puesto defensivo de Harwick, presidido por el Capitán Agelmund.", "Feldburg is a defence outpost of Harwick, presided over by Captain Agelmund." }, { "Vigilia de la Crecida", "Wakenflood", "La Vigilia de la Crecida, un puesto avanzado rohirrim del Páramo, está a punto de caer en manos de los Orientales. Los soldados yacen heridos mientras luchan por mantener las defensas.", "Wakenflood, a Rohirrim outpost of the Wold, has nearly fallen to Easterlings. Soldiers lie wounded as they struggle to uphold the defences." }, { "Twickenburg", "Twickenburg", "Twickenburg es el puesto de vigilancia rohirrim en las encrucijadas del Páramo, asegurando que los caminos estén bajo control de los Pueblos Libres.", "Twickenburg is the Rohirrim watch upon the cross-roads in the Wold, ensuring that the roads are held by the Free Peoples." }, { "Norte-torr", "North-torr", "Norte-torr es la última defensa de los Rohirrim contra los Orientales en su marcha hacia el Recodo de la Crecida.", "North-torr is the Rohirrim's last defence against Easterlings in the enemy's march upon Floodwend." }, { "Caddabrand's Camp", "Caddabrand's Camp", "El cazador Caddabrand ha establecido un campamento dentro de una formación rocosa para cazar en nombre del Reeve Athelward.", "The huntsman Caddabrand has set up camp within a rock formation to hunt on behalf of Reeve Athelward." }, { "Western Cliving Watch-tower", "Western Cliving Watch-tower", "Los hombres de la torre de vigilancia occidental son la vanguardia de las defensas de la ciudad de Cliving. Desde su puesto avanzado, pueden identificar las fuerzas enemigas que se acercan desde las...", "The men of the western watch-tower are the vanguard of defences for the city of Cliving. From their outpost, they are able to identify enemy forces approaching from the plains and are able to halt..." }, { "Rohirrim Training Grounds", "Rohirrim Training Grounds", "Los hombres del Reeve Athelward han convertido una granja aislada en el noreste en un campo de entrenamiento para aspirantes a soldados. La ubicación relativamente oculta ofrece cierta protección...", "Reeve Athelward's men have converted a secluded farmstead in the north-east into a training ground for aspiring soldiers. The relatively hidden location offers some protection from Orc-assault." }, { "Trader's Outpost", "Trader's Outpost", "Los comerciantes y mercaderes de este puesto avanzado venden suministros muy necesarios a los viajeros que recorren el camino y a aquellos que huyen de los ejércitos orcos invasores. Su ubicación es...", "The merchants and traders at this outpost sell much-needed supplies to travellers along the road and to those fleeing from the invading Orc-armies. Their location is a dangerous one, but hired guards..." } }
I.D[1879251711] = { "Enemigos de los Rohirrim", "Enemies of the Rohirrim", 103, 72, 2000, 5, 0, "", "Buscador de Enemigos", "Explora los campamentos de los enemigos de Rohan.", "Explore the encampments of Rohan's enemies.", "", "Finder of Foes" }
I.O[1879251711] = { { "Olghakhósh", "Olghakhósh", "Olghakhósh es un pequeño campamento de los Orientales en el Páramo.", "Olghakhósh is a small Easterling-camp in the Wold." }, { "Jóshkhin Orda", "Jóshkhin Orda", "Jóshkhin Orda es el gran campamento de los Orientales en el Páramo, donde Súth-torr fue capturado por los Nazgûl para allanar el camino a los enemigos de los Rohirrim.", "Jóshkhin Orda is the large Easterling-encampment of the Wold, where Súth-torr was captured by the Nazgûl to pave the way for the enemies of the Rohirrim." }, { "Nîn-stazg", "Nîn-stazg", "Los orcos de Nîn-stazg se reúnen para un ataque a Recodo de la Crecida.", "The Orcs of Nîn-stazg rally for an attack on Floodwend." }, { "Eastmund's Lair", "Eastmund's Lair", "El líder de los bandidos Eastmund ha sido exiliado muchas veces, pero su guarida siempre parece reaparecer en algún lugar del norte del Páramo.", "The brigand-leader Eastmund has been exiled many times, but his lair always seems to reappear somewhere in the northern Wold." }, { "South Undeep", "South Undeep", "Los bajos fondos del Anduin presentan un punto vulnerable para el Páramo, ya que los Orientales intentan cruzar el río en esos lugares.", "The shallows of the Anduin present a vulnerable spot for the Wold, for Easterlings attempt to creep across the river at such places." }, { "Kufuzg", "Kufuzg", "Una compañía de guerreros Uruk-hai, que había marchado hacia el oeste con una fuerza mayor, ha regresado recientemente y ha establecido un campamento al sur de Elthengels. ¿Qué podría haberlos hecho...", "A company of Uruk-hai warriors, who had marched west with a larger force, has recently returned and made camp south of Elthengels. What could have caused them to flee eastwards?" }, { "Nink-hai War Camp", "Nink-hai War Camp", "Un grupo de orcos de la Mano Blanca, los Nink-hai, han establecido un campamento de guerra en los pasos montañosos entre los Norcrofts y la Muralla del Este, planeando asaltar la aldea agrícola de...", "A group of White Hand Orcs, the Nink-hai, have established a war-camp in the mountain-passes between the Norcrofts and the East Wall, planning to assault the farming-village of Faldham." }, { "Ash Durub", "Ash Durub", "Los orcos que han escapado de las lanzas de Walstow en la Muralla del Este han establecido un campamento en Ash Durub en los Sutcrofts, bloqueando a Walstow de recibir cualquier ayuda de Río Nevado.", "The Orcs that have escaped Walstow's spears at the East Wall have set up camp at Ash Durub in the Sutcrofts, blocking Walstow from receiving any aid from Snowbourn." }, { "Ufum-mau", "Ufum-mau", "Al igual que en Ash Durub, los orcos de Ufum-mau impiden que Walstow reciba ayuda de Río Nevado.", "Along with Ash Durub, the Orcs of Ufum-mau prevent Walstow from receiving aid from Snowbourn." }, { "Krash-bálum", "Krash-bálum", "Los semiorcos de la Mano Blanca han estado intentando activamente saquear Campo de Lanzas, encontrando una resistencia mínima por parte de los hombres de Gísil.", "Half-orcs of the White Hand have been actively trying to sack Garsfeld, having met minimal resistance from Gísil's men." }, { "Maustazg", "Maustazg", "Los orcos y uruks de Maustazg representan una grave amenaza para los habitantes del Valle del Entaguas.", "The Orcs and Uruks of Maustazg pose a dire threat to the people of the Entwash Vale." }, { "Thrug-unur", "Thrug-unur", "Te has encontrado con Thrug-unur, un campamento de trasgos de Moria en el Valle del Entaguas. Tener trasgos como vecinos es una situación que no es ideal para los Rohirrim aquí.", "You have come across Thrug-unur, an encampment of Moria goblins in the Entwash Vale. Having goblins as neighbours is a situation that is less than ideal for the Rohirrim here." } }
I.D[1879251713] = { "Donde habitan las criaturas malignas", "Where Evil Creatures Dwell", 103, 72, 2000, 5, 0, "", "Descubridor de Guaridas", "Explora las moradas de las criaturas malignas en Rohan.", "Explore the dwellings of evil creatures in Rohan.", "", "Den Discoverer" }
I.O[1879251713] = { { "The Howling Wood", "The Howling Wood", "El Bosque Aullante es la guarida de los huargos en el Páramo que fue en su día un lugar de trabajo estratégico para Recodo de la Crecida, pero que ahora está invadido por estas asquerosas y mortales...", "The Howling Wood is a Warg-den in the Wold that was once a strategic worksite for Floodwend, but is now overrun with the filthy, deadly beasts." }, { "Promontorio del Colmillo", "Fang Point", "El Promontorio del Colmillo es un campamento de huargos que amenaza a los hombres de Feldburg, que vigilan el camino.", "Fang Point is a Warg-camp that threatens the Men of Feldburg, who stand watch on the road." }, { "Âmbal's Den", "Âmbal's Den", "Âmbal, la renombrada y temida matrona de lobos, hace su hogar en un círculo de acantilados y rocas cerca del arroyo que atraviesa los Norcrofts. Ella y sus crías han causado no poca sufrimiento a los...", "Âmbal, the renowned and feared wolf-matron, makes her home in a circle of cliffs and rocks near the stream that runs across the Norcrofts. She and her offspring have caused no shortage of suffering..." }, { "Valley of the Láthbear", "Valley of the Láthbear", "Un valle que alguna vez fue pacífico, que se extiende desde el oeste de Redilaldea hasta la Muralla del Este, ha sido invadido por peligrosos Láthbears.", "A once-peaceful valley, spanning from west of Faldham into the East Wall, has become overrun with dangerous Láthbears." }, { "Mina del Dragón", "Wyrmdelf", "Has descubierto la Mina del Dragón, una cueva llena de dracos malignos en el Valle del Entaguas. Tales lugares son mortales incluso para los guerreros más resistentes y valientes.", "You have discovered Wyrmdelf, a cave teeming with evil drakes in the Entwash Vale. Such places are deadly even for the hardiest and bravest of warriors." }, { "Fang Tor", "Fang Tor", "El Patriarca de los dragones de la Mina del Dragón vive sobre la alta roca del Promontorio del Colmillo en el Valle del Entaguas.", "The Wyrm-father of Wyrmdelf lives upon the high rock of Fang Tor in the Entwash Vale." } }
I.D[1879251724] = { "Granjas y Fincas del Estemnet", "Farms and Crofts of the Eastemnet", 103, 72, 2000, 5, 0, "", "Buscador de Granjas", "Descubre las granjas del Estemnet.", "Discover the farms of the Eastemnet.", "", "Finder of Farms" }
I.O[1879251724] = { { "Randgar's Farm", "Randgar's Farm", "Esta pequeña granja pertenece al granjero Randgar, quien se ha negado a evacuar a pesar del creciente peligro de la amenaza orca.", "This small farm belongs to the farmer Randgar, who has refused to evacuate despite the growing danger of the Orc-threat." }, { "Finca de Vista Primaveral", "Springview Estate", "Esta finca fue en su día el hogar de una próspera familia de agricultores, pero ha caído en las codiciosas manos de los Orcos invasores.", "This estate was once home to a prosperous farming family, but it has fallen into the greedy hands of the invading Orcs." }, { "The Desolate Crofts", "The Desolate Crofts", "Las granjas de Walstow, casi completamente arrasadas más allá de toda salvación, están en manos de los Orcos, por lo que los pocos cultivos que quedan son demasiado peligrosos para que cualquier...", "The crofts of Walstow, ravaged almost completely beyond saving, are held by Orcs, so what few crops remain are far too dangerous for any crofter to harvest." }, { "Bradcroft", "Bradcroft", "La Finca de Brad es la más grande de los Sutcrofts y se encuentra al sur de Campo de Lanzas. Actualmente está invadida y ha sido destruida por varios semi-orcos y orcos.", "Bradcroft is the largest croft in the Sutcrofts and lies south of Garsfeld. It is currently overrun and has been destroyed by a number of half-orcs and Orcs." }, { "Wyrthing", "Wyrthing", "Wyrthing es un conjunto de tierras agrícolas en gran parte intactas alrededor de Río Nevado. Los Orcos han intentado sitiarlas, pero hasta ahora sus esfuerzos han sido repelidos por las fuerzas de...", "Wyrthing is a largely untouched spread of croftlands surrounding Snowbourn. The Orcs have made attempts to besiege them, but so far their efforts have been repelled by the forces of Snowbourn." } }
I.D[1879251765] = { "Ruinas, Tumbas y Monumentos del Estemnet", "Ruins, Tombs, and Monuments of the Eastemnet", 103, 72, 2000, 5, 0, "", "Buscador de las Ruinas de Rohan", "Descubre los lugares en ruinas del Estemnet.", "Discover the ruined places of the Eastemnet.", "", "Seeker of Rohan's Ruins" }
I.O[1879251765] = { { "Dwolung Hole", "Dwolung Hole", "Los muertos se agitan en los túmulos del Agujero de Dwolung en el Páramo, nunca es una buena señal para los Hombres de Rohan, que son naturalmente supersticiosos.", "The dead stir in the barrows of the Dwolung Hole in the Wold, never a good sign to the Men of Rohan, who are naturally superstitious." }, { "Wódscrafen", "Wódscrafen", "Wódscrafen es el hogar de los Muertos que caminan, aunque deberían estar dormidos en sus tumbas. ¿Qué despierta a los draugar dormidos de su descanso?", "Wódscrafen is home to the Dead who walk, though they should be asleep in their tombs. What wakes the sleeping draugar from their rest?" }, { "El Lodazal Hirviente", "The Seething Mire", "El Lodazal Hirviente se encuentra cerca de Largafortín, una vez una hermosa construcción gondoriana, ahora no es más que ruinas invadidas por salamandras y sus nidos.", "The Seething Mire lies near Langhold, once a fair Gondorian structure, now naught but ruins overrun by salamanders and their nests." }, { "Minas Rant", "Minas Rant", "Una torre de piedra independiente, Minas Rant es una reliquia de los antiguos ejércitos de Gondor que una vez protegieron las tierras ahora llamadas los Norcrofts.", "A freestanding stone tower, Minas Rant is a relic of the ancient armies of Gondor that once protected the lands now called the Norcrofts." }, { "The Red Fields", "The Red Fields", "Los Campos Rojos fueron una vez tierras ideales para cultivar y criar ganado, pero se convirtieron en los principales campos de batalla de la primera de las recientes invasiones de orcos. La zona...", "The Red Fields were once ideal lands for growing crops and raising livestock, but became the primary battlegrounds of the first of the recent Orc-invasions. The area received its nickname due to the..." }, { "Dagred's Grave", "Dagred's Grave", "Has encontrado la tumba del padre de Fastred, el anterior Reeve de los Sutcrofts. Fastred suele visitar el lugar para rendirle homenaje y cazar sin piedad a cualquier orco que se atreva a acercarse...", "You have found the grave of the father of Fastred, the previous Reeve of the Sutcrofts. Fastred often visits to pay his respects and to mercilessly hunt any Orc that dares to stray too close to his..." }, { "Valle del Espino", "Thornhope", "Lamentablemente, Valle del Espino se ha convertido en uno de los lugares muertos y abandonados del Estemnet. Valle del Espino fue una ciudad próspera en su momento, pero ahora no es más que muerte y...", "Alas for Thornhope, newly arrived upon the list of dead and abandoned places in the Eastemnet. Thornhope was a thriving city once, but now it is naught but death and ruin, a hollow reminder of the..." }, { "Ancient Norcrofts Tomb", "Ancient Norcrofts Tomb", "Las tumbas de los Hombres de Gondor a veces se encuentran en rincones apartados de Rohan. Estas criptas suelen atraer a aventureros que buscan tesoros de la Segunda Edad, pero con frecuencia solo...", "Tombs of the Men of Gondor can sometimes be found in secluded corners of Rohan. Such crypts often attract adventurers who seek treasures of the Second Age, but they are frequently filled only with..." }, { "Byrgenstow fue una vez una tumba antigua perteneciente a los antepasados de los Dunlendinos. Ahora está lleno...", "Byrgenstow was once an ancient burial tomb belonging to the ancestors of the Dunlendings. Now it teems with...", "Byrgenstow fue una vez una tumba antigua perteneciente a los antepasados de los Dunlendinos. Ahora está lleno de maldad en forma de draugar.", "Byrgenstow was once an ancient burial tomb belonging to the ancestors of the Dunlendings. Now it teems with evil in the form of the draugar." }, { "Santuario de Eorl", "Eorl's Hallow", "Este monumento a Eorl el Joven se encuentra en el Páramo como recordatorio de los mayores logros en la historia de Rohan. El monumento de Eorl se encuentra aquí, pero su tumba está cerca de Edoras.", "This memorial to Eorl the Young stands in the Wold as a reminder to the greatest deeds in Rohan's history. Eorl's monument stands here, but his tomb is near Edoras." } }
I.D[1879259563] = { "Blooming in the Snow", "Blooming in the Snow", 104, 80, 2000, 5, 500, "Gente de las Tierras Feroces", "Flor en la Nieve", "Even flowers and plants can be hardy enough to brave the fearsome snows. When you come upon these fierce little blooms, you feel hope for the shivering people of Wildermore.", "Even flowers and plants can be hardy enough to brave the fearsome snows. When you come upon these fierce little blooms, you feel hope for the shivering people of Wildermore.", "People of Wildermore", "Blossom in the Snow" }
I.O[1879259563] = { { "Cardo salvaje", "Wild Thistle", "You have discovered fair thistle blooming in snowy Wildermore.", "You have discovered fair thistle blooming in snowy Wildermore." }, { "Dedalera salvaje", "Wild Foxglove", "You have discovered fair foxglove blooming in snowy Wildermore.", "You have discovered fair foxglove blooming in snowy Wildermore." }, { "Lirio salvaje", "Wild Iris", "You have discovered a fair iris blooming in snowy Wildermore.", "You have discovered a fair iris blooming in snowy Wildermore." }, { "Hierba salvaje", "Wild Herb", "You have discovered a fair herb growing in snowy Wildermore.", "You have discovered a fair herb growing in snowy Wildermore." }, { "Champiñones rojos salvajes", "Wild Red Mushrooms", "You have discovered bright red mushrooms growing strong in snowy Wildermore.", "You have discovered bright red mushrooms growing strong in snowy Wildermore." }, { "Lirio de madera salvaje", "Wild Wood Lily", "You have discovered a fair Wood Lily blooming in snowy Wildermore.", "You have discovered a fair Wood Lily blooming in snowy Wildermore." } }
I.D[1879265472] = { "Loved and Lost", "Loved and Lost", 104, 80, 2000, 5, 500, "Gente de las Tierras Feroces", "Buscador de Penas", "Most of the Reeve's family are laid to rest in the graveyard outside of Forlaw. Most of his family has been killed recently as the conflict in Wildermore escalates.", "Most of the Reeve's family are laid to rest in the graveyard outside of Forlaw. Most of his family has been killed recently as the conflict in Wildermore escalates.", "People of Wildermore", "Seeker of Sorrow" }
