I.O[1879265487] = { { "Forlaw Graveyard", "Forlaw Graveyard", "You have discovered Forlaw's graveyard where many of the noble family are buried.", "You have discovered Forlaw's graveyard where many of the noble family are buried." }, { "You have discovered the mead hall tower, which arguably has the best view in Wildermore.", "You have discovered the mead hall tower, which arguably has the best view in Wildermore.", "You have discovered the mead hall tower, which arguably has the best view in Wildermore.", "You have discovered the mead hall tower, which arguably has the best view in Wildermore." }, { "Lornsettle", "Lornsettle", "You have discovered the Forlaw mead hall, Lornsettle, where the forlorn Reeve Gárwig awaits his passing.", "You have discovered the Forlaw mead hall, Lornsettle, where the forlorn Reeve Gárwig awaits his passing." }, { "Gársig's Home", "Gársig's Home", "You have discovered Gársig's home where the widow Burghild and their son live.", "You have discovered Gársig's home where the widow Burghild and their son live." }, { "Edsig's Home", "Edsig's Home", "You have discovered Edsig's home where the widow Hereswith and their two daughters live.", "You have discovered Edsig's home where the widow Hereswith and their two daughters live." }, { "Gárferth's Home", "Gárferth's Home", "You have discovered Gárferth's home where the widow Ebba and the two orphans live.", "You have discovered Gárferth's home where the widow Ebba and the two orphans live." }, { "Thrymm's Home", "Thrymm's Home", "You have discovered Thrymm's Home where Cyneberg now lives.", "You have discovered Thrymm's Home where Cyneberg now lives." }, { "You have discovered the barber in Forlaw where both man and horse can go for a haircut.", "You have discovered the barber in Forlaw where both man and horse can go for a haircut.", "You have discovered the barber in Forlaw where both man and horse can go for a haircut.", "You have discovered the barber in Forlaw where both man and horse can go for a haircut." }, { "You have discovered the barracks in Forlaw where those involved in battle go for training.", "You have discovered the barracks in Forlaw where those involved in battle go for training.", "You have discovered the barracks in Forlaw where those involved in battle go for training.", "You have discovered the barracks in Forlaw where those involved in battle go for training." }, { "You have discovered the cellar in Forlaw, which appears to have not been used for some time.", "You have discovered the cellar in Forlaw, which appears to have not been used for some time.", "You have discovered the cellar in Forlaw, which appears to have not been used for some time.", "You have discovered the cellar in Forlaw, which appears to have not been used for some time." }, { "You have discovered the auction hall which is the backbone of the market in Forlaw.", "You have discovered the auction hall which is the backbone of the market in Forlaw.", "You have discovered the auction hall which is the backbone of the market in Forlaw.", "You have discovered the auction hall which is the backbone of the market in Forlaw." }, { "You have discovered the bank in Forlaw where the more well-off townsfolk store their valuables.", "You have discovered the bank in Forlaw where the more well-off townsfolk store their valuables.", "You have discovered the bank in Forlaw where the more well-off townsfolk store their valuables.", "You have discovered the bank in Forlaw where the more well-off townsfolk store their valuables." }, { "You have discovered the crafting hall in Forlaw where anyone who knows a profession can work or train.", "You have discovered the crafting hall in Forlaw where anyone who knows a profession can work or train.", "You have discovered the crafting hall in Forlaw where anyone who knows a profession can work or train.", "You have discovered the crafting hall in Forlaw where anyone who knows a profession can work or train." }, { "You have discovered the infirmary of Forlaw where one goes if in need of healing or supplies.", "You have discovered the infirmary of Forlaw where one goes if in need of healing or supplies.", "You have discovered the infirmary of Forlaw where one goes if in need of healing or supplies.", "You have discovered the infirmary of Forlaw where one goes if in need of healing or supplies." }, { "You have discovered the legendary hall of Forlaw where note-worthy items are researched and tended.", "You have discovered the legendary hall of Forlaw where note-worthy items are researched and tended.", "You have discovered the legendary hall of Forlaw where note-worthy items are researched and tended.", "You have discovered the legendary hall of Forlaw where note-worthy items are researched and tended." }, { "You have discovered the Great Tavern in Forlaw where one goes for a stiff drink or good conversation.", "You have discovered the Great Tavern in Forlaw where one goes for a stiff drink or good conversation.", "You have discovered the Great Tavern in Forlaw where one goes for a stiff drink or good conversation.", "You have discovered the Great Tavern in Forlaw where one goes for a stiff drink or good conversation." }, { "You have discovered the Forlaw skirmish hall where one goes to train their soldier or to barter with...", "You have discovered the Forlaw skirmish hall where one goes to train their soldier or to barter with...", "You have discovered the Forlaw skirmish hall where one goes to train their soldier or to barter with merchants.", "You have discovered the Forlaw skirmish hall where one goes to train their soldier or to barter with merchants." } }
