I.O[1879269245] = { { "The Northern Ice-spires", "The Northern Ice-spires", "Núrzum paused here to get a good look at Forlaw, and his footprints lead the other way.", "Núrzum paused here to get a good look at Forlaw, and his footprints lead the other way." }, { "The Southern Ice-spires", "The Southern Ice-spires", "It is clear that Núrzum paused in this spot to hunt a messenger from Forlaw and mangle his horse.", "It is clear that Núrzum paused in this spot to hunt a messenger from Forlaw and mangle his horse." }, { "The Western Ice-spires", "The Western Ice-spires", "Orcs have set up a small encampment encircling these ice-spires, letting their guard down in the shadow of Núrzum's presence.", "Orcs have set up a small encampment encircling these ice-spires, letting their guard down in the shadow of Núrzum's presence." }, { "The Ice-spires at Dunfast", "The Ice-spires at Dunfast", "Núrzum stood outside of Dunfast and tossed about trees and boulders as if they were a child's toys.", "Núrzum stood outside of Dunfast and tossed about trees and boulders as if they were a child's toys." }, { "Núrzum's Wrath", "Núrzum's Wrath", "Núrzum carved a path of terror through Balewood, freezing the forest and paving the way for the White Hand invasion of Wildermore.", "Núrzum carved a path of terror through Balewood, freezing the forest and paving the way for the White Hand invasion of Wildermore." } }
