I.O[1879269256] = { { "The Elderwood", "The Elderwood", "You have wandered into a sprawling wood in the Whitshaws, once lush and green, but now full of wintry skeletons of trees.", "You have wandered into a sprawling wood in the Whitshaws, once lush and green, but now full of wintry skeletons of trees." }, { "Steaping", "Steaping", "You have come upon a cave high upon a tall tor in the High Knolls. It offers shelter against the cold winds that blow across the craggy peaks.", "You have come upon a cave high upon a tall tor in the High Knolls. It offers shelter against the cold winds that blow across the craggy peaks." }, { "Hondonada de Entandos", "Enting Hollow", "You have discovered a frozen pond that was once a favoured meeting place for the young Ents of Balewood.", "You have discovered a frozen pond that was once a favoured meeting place for the young Ents of Balewood." }, { "Stonecliff", "Stonecliff", "You have discovered a rocky outcropping overlooking the Limlight Gorge where several Ents have made their home in the wake of Núrzum's destruction.", "You have discovered a rocky outcropping overlooking the Limlight Gorge where several Ents have made their home in the wake of Núrzum's destruction." }, { "Hidromiel de Zarcillo", "Leaflock's Mead", "Home to one of the eldest Ents in Fangorn, Leaflock, this mead is buried in deep snow from Núrzum's passing.", "Home to one of the eldest Ents in Fangorn, Leaflock, this mead is buried in deep snow from Núrzum's passing." } }
I.D[1879269260] = { "Settlements of Wildermore", "Settlements of Wildermore", 103, 75, 2000, 5, 500, "Gente de las Tierras Feroces", "Calor en medio del frío", "Discover the settlements of the people of Wildermore.", "Discover the settlements of the people of Wildermore.", "People of Wildermore", "Warmth Amidst the Cold" }
I.O[1879269260] = { { "Scylfig", "Scylfig", "You have discovered a great settlement of the Writhendowns, home to Thane Cynegar. The people of Scylfig stand poised to repel an impending assault by the White Hand.", "You have discovered a great settlement of the Writhendowns, home to Thane Cynegar. The people of Scylfig stand poised to repel an impending assault by the White Hand." }, { "Dunfast", "Dunfast", "The town of Dunfast, a small village full of ordinary peasants, lies silent and empty in this troubled time.", "The town of Dunfast, a small village full of ordinary peasants, lies silent and empty in this troubled time." }, { "Byre Tor", "Byre Tor", "Byre Tor, a wild stronghold in the tors of the High Knolls, is now inhabited by the enemy, its banners defiled by the White Hand.", "Byre Tor, a wild stronghold in the tors of the High Knolls, is now inhabited by the enemy, its banners defiled by the White Hand." }, { "Thrymm Red-beard's Camp", "Thrymm Red-beard's Camp", "A makeshift camp led by a champion of Wildermore, this settlement was built recently to prepare the Rohirrim of Writhendowns for an impending White Hand attack.", "A makeshift camp led by a champion of Wildermore, this settlement was built recently to prepare the Rohirrim of Writhendowns for an impending White Hand attack." }, { "Campamento de Cerdic", "Cerdic's Camp", "A small camp hidden amongst the outskirts of the Balewood, Cerdic and his men keep watch on the nearby road for sign of more White Hand invaders.", "A small camp hidden amongst the outskirts of the Balewood, Cerdic and his men keep watch on the nearby road for sign of more White Hand invaders." }, { "Iothete's Hideaway", "Iothete's Hideaway", "Iothete, a villager from Dunfast, abandoned his home long ago and left his people, coming to this remote spot in the Elderwood.", "Iothete, a villager from Dunfast, abandoned his home long ago and left his people, coming to this remote spot in the Elderwood." }, { "Grimnesberg", "Grimnesberg", "Este pequeño pueblo de las Altas Cumbres ofrecía una vista imponente de todas las Tierras Feroces, pero sus habitantes fueron masacrados hasta el último por los Uruks de Isengard.", "This small town in the High Knolls once offered a tall view upon all of Wildermore, but the people who lived here were slain to the very last by the Uruks from Isengard." } }
I.D[1879269261] = { "These Hostile Lands", "These Hostile Lands", 103, 75, 2000, 5, 500, "Gente de las Tierras Feroces", "el Escabroso", "Discover where the foes of the Rohirrim dwell in Wildermore.", "Discover where the foes of the Rohirrim dwell in Wildermore.", "People of Wildermore", "the Rugged" }
I.O[1879269261] = { { "Fiskworth", "Fiskworth", "Now inhabited by all manner of unnatural evil, this abandoned fishing village was once the main source of food for the people of Scylfig.", "Now inhabited by all manner of unnatural evil, this abandoned fishing village was once the main source of food for the people of Scylfig." }, { "Fushaum-dorám", "Fushaum-dorám", "This substantial White Hand settlement occupies a strategic location in the Writhendowns, and aims to keep a watchful eye on the city of Forlaw.", "This substantial White Hand settlement occupies a strategic location in the Writhendowns, and aims to keep a watchful eye on the city of Forlaw." }, { "Kadar-golnauk", "Kadar-golnauk", "A White Hand outpost erected recently to scout Scylfig for the coming attack.", "A White Hand outpost erected recently to scout Scylfig for the coming attack." }, { "The Hungry Paths", "The Hungry Paths", "Snow-cats of the High Knolls prowl in great numbers on this snowy hill, starving as their prey die from the cold.", "Snow-cats of the High Knolls prowl in great numbers on this snowy hill, starving as their prey die from the cold." }, { "Drû Vádokan", "Drû Vádokan", "Built atop the remains of an elder Huorn of Fangorn, this camp is now home to the White Hand forces in Balewood.", "Built atop the remains of an elder Huorn of Fangorn, this camp is now home to the White Hand forces in Balewood." } }
