I.D[1879328985] = { "Guests of the White City", "Guests of the White City", 103, 90, 0, 5, 500, "Defensores de Minas Tirith", "", "Read the plaques of landmarks frequented by those visiting the city of Minas Tirith.", "Read the plaques of landmarks frequented by those visiting the city of Minas Tirith.", "Defenders of Minas Tirith", "" }
I.O[1879328985] = { { "Establos de la ciudad", "City Stables", "Also known as Rochmar Oston, these stables carved into the stone pier are where visitors, soldiers, and errand-riders quarter their steeds while inside the city.", "Also known as Rochmar Oston, these stables carved into the stone pier are where visitors, soldiers, and errand-riders quarter their steeds while inside the city." }, { "Salón de los Recados", "Hall of Errands", "Also known as Tham Pethgyl, it is the location through which all messages to and from Minas Tirith pass, and headquarters of the city's errand-riders.", "Also known as Tham Pethgyl, it is the location through which all messages to and from Minas Tirith pass, and headquarters of the city's errand-riders." }, { "Antigua Casa de Huéspedes", "Old Guest-house", "Also known as Sennas Iaur. It is a stately inn where errand-boys loiter and await orders.", "Also known as Sennas Iaur. It is a stately inn where errand-boys loiter and await orders." }, { "Casa de Huéspedes del Sur", "South Guest-house", "Also known as Sennas Charn, a more recently constructed inn than the Old Guest-house.", "Also known as Sennas Charn, a more recently constructed inn than the Old Guest-house." }, { "Casa de Huéspedes del Norte", "North Guest-house", "Also known as Sennas Forn, an inn that quarters traders from far-off lands.", "Also known as Sennas Forn, an inn that quarters traders from far-off lands." }, { "Cuartel de Huéspedes", "Guest Barracks", "Also known as Sennas Hedyr, the dwelling for soldiers visiting from outside Minas Tirith. The soldiers of the fiefs are quartered here, as well as being billeted in guest-houses and evacuated homes...", "Also known as Sennas Hedyr, the dwelling for soldiers visiting from outside Minas Tirith. The soldiers of the fiefs are quartered here, as well as being billeted in guest-houses and evacuated homes..." }, { "Casa de Reposo", "House of Rest", "Also known as Bâr Haust, a guest-house for visiting merchants.", "Also known as Bâr Haust, a guest-house for visiting merchants." }, { "Casa de Huéspedes Alta", "High Guest-house", "Also known as Sennas Vrand, a small inn catering to the wealthy.", "Also known as Sennas Vrand, a small inn catering to the wealthy." }, { "Establos Altos", "High Stables", "Stables carved into the wall of the Seventh Circle for those few who ride to the top of the city. Also known as Rochbar Raud.", "Stables carved into the wall of the Seventh Circle for those few who ride to the top of the city. Also known as Rochbar Raud." }, { "Gran Casa de Huéspedes del Sur", "Southern Great Guest-house", "This building contains a group of guest-rooms for visitors to the Citadel. The lords of the fiefs reside within, including Lord Forlong.", "This building contains a group of guest-rooms for visitors to the Citadel. The lords of the fiefs reside within, including Lord Forlong." } }
I.D[1879329669] = { "Workings of the White City", "Workings of the White City", 103, 90, 0, 5, 500, "Defensores de Minas Tirith", "", "Read the plaques of places that govern the laws, rules, and commerce of Minas Tirith.", "Read the plaques of places that govern the laws, rules, and commerce of Minas Tirith.", "Defenders of Minas Tirith", "" }
I.O[1879329669] = { { "Salón de las Leyes", "Hall of Laws", "Also known as Tham Baudh, the main courthouse of the city. It is where magistrates pass judgement against all but the highest lords in the city.", "Also known as Tham Baudh, the main courthouse of the city. It is where magistrates pass judgement against all but the highest lords in the city." }, { "Cárcel de la Ciudad", "City Gaol", "Also known as Gadorost. Dug into the side of the Mindolluin, it houses many cells where common folk are held after judgement is passed.", "Also known as Gadorost. Dug into the side of the Mindolluin, it houses many cells where common folk are held after judgement is passed." }, { "Casa del Clamor", "House of Clamour", "Also known as Bâr Caun, the city's public auction hall.", "Also known as Bâr Caun, the city's public auction hall." }, { "Cámaras de la Ciudad", "Chambers of the City", "Also known as Sammath Oston, it contains offices of city clerks, heralds, records-keepers, and so forth. It is the heart that keeps Minas Tirith alive.", "Also known as Sammath Oston, it contains offices of city clerks, heralds, records-keepers, and so forth. It is the heart that keeps Minas Tirith alive." }, { "Cúpula del Sol", "Dome of the Sun", "Also known as Rond Anor, the great meeting-hall of Minas Tirith. It is where the city councilors hold court, and high magistrates hold trials for prominent citizens or the highest of crimes.", "Also known as Rond Anor, the great meeting-hall of Minas Tirith. It is where the city councilors hold court, and high magistrates hold trials for prominent citizens or the highest of crimes." } }
I.D[1879329670] = { "Vaults of the White City", "Vaults of the White City", 103, 90, 0, 5, 500, "Defensores de Minas Tirith", "", "Read the plaques of landmarks used by those living in Minas Tirith to store provisions and valuables.", "Read the plaques of landmarks used by those living in Minas Tirith to store provisions and valuables.", "Defenders of Minas Tirith", "" }
I.O[1879329670] = { { "Torre de las Llaves", "Keep of the Keys", "Also known as Tham Fendir, the headquarters of the city's doorwards. It is governed by Húrin, Warden of the Keys.", "Also known as Tham Fendir, the headquarters of the city's doorwards. It is governed by Húrin, Warden of the Keys." }, { "Almacenes Inferiores", "Lower Stores", "Also known as Bachrond Dofn. Tunneled into the Hill of Guard, it contains the butteries and warehouses for the coming siege.", "Also known as Bachrond Dofn. Tunneled into the Hill of Guard, it contains the butteries and warehouses for the coming siege." }, { "Bóvedas de Rynd Mírath", "Vaults of Rynd Mírath", "Las cámaras fuertes públicas de la ciudad, ubicadas dentro de la Colina de la Guardia.", "The city's public vaults, located within the Hill of Guard." }, { "Almacenes intermedios", "Middle Stores", "Also known as Bachrond Enedh. Located within the Hill of Guard, it contains the butteries and warehouses for the coming siege.", "Also known as Bachrond Enedh. Located within the Hill of Guard, it contains the butteries and warehouses for the coming siege." }, { "Almacenes superiores", "Upper Stores", "Also known as Bachrond Raud. Located within the Hill of Guard, it contains the butteries and warehouses for the coming siege.", "Also known as Bachrond Raud. Located within the Hill of Guard, it contains the butteries and warehouses for the coming siege." }, { "La Casa de los Cofres", "The Coffer-house", "Also known as Bâr Mírath. This well-guarded dome contains the treasury of Gondor, holding all the wealth belonging to the Steward. Many locked chambers beneath the building house gold, silver,...", "Also known as Bâr Mírath. This well-guarded dome contains the treasury of Gondor, holding all the wealth belonging to the Steward. Many locked chambers beneath the building house gold, silver,..." } }
I.D[1879329671] = { "Taverns of the White City", "Taverns of the White City", 103, 90, 0, 5, 500, "Defensores de Minas Tirith", "", "Read the plaques of taverns and wine-shops within Minas Tirith.", "Read the plaques of taverns and wine-shops within Minas Tirith.", "Defenders of Minas Tirith", "" }
I.O[1879329671] = { { "La Rueda y el Barril", "The Wheel and Cask", "A simple ale-house also known as Hwinir a Calph.", "A simple ale-house also known as Hwinir a Calph." }, { "El Mediano Risueño", "The Laughing Halfling", "Also known as Perian Lavrol. The wine-shop features a caricature of a hobbit on its sign, though it is based on secondhand descriptions and highly offensive to actual folk.", "Also known as Perian Lavrol. The wine-shop features a caricature of a hobbit on its sign, though it is based on secondhand descriptions and highly offensive to actual folk." }, { "El Escudo Astillado", "The Splintered Shield", "Also known as Thand Thannan, an ale-hall that caters to soldiers.", "Also known as Thand Thannan, an ale-hall that caters to soldiers." }, { "El Mûmak y la Fortaleza", "The Mûmak and Keep", "Also known as Mûmak a Barad, an ale-hall that caters to soldiers.", "Also known as Mûmak a Barad, an ale-hall that caters to soldiers." }, { "La Cabeza del Auriga", "The Wainrider's Head", "Also known as Dol Rachrohir, a wine-shop for soldiers.", "Also known as Dol Rachrohir, a wine-shop for soldiers." }, { "El Martillo y las Tenazas", "The Hammer and Tongs", "Also known as Dring a Mebir, an ale-house that caters to the city's smiths.", "Also known as Dring a Mebir, an ale-house that caters to the city's smiths." }, { "El Refugio", "The Haven", "Also known as Lond Veriannen, a cozy ale-house.", "Also known as Lond Veriannen, a cozy ale-house." }, { "El Cisne Alegre", "The Merry Swan", "Also known as Alph ’Elir, a tavern favoured by the hostellers of Minas Tirith. It boasts of having the finest wine cellar in the city.", "Also known as Alph ’Elir, a tavern favoured by the hostellers of Minas Tirith. It boasts of having the finest wine cellar in the city." }, { "El Ladrillo y Mortero", "The Brick and Mortar", "Also known as Drafn a Gwedgeph, an ale-house catering to the builders of the city.", "Also known as Drafn a Gwedgeph, an ale-house catering to the builders of the city." }, { "La Ola Crestada", "The Cresting Wave", "Also known as Falf Falthol, a wine-shop where minstrels and their wealthy patrons gather.", "Also known as Falf Falthol, a wine-shop where minstrels and their wealthy patrons gather." }, { "El Faro Solitario", "The Lone Beacon", "Also known as Narthan Ereb, a wine-shop of refinement and beauty whose establishment is marked by the large brazier atop its portico and a central garden.", "Also known as Narthan Ereb, a wine-shop of refinement and beauty whose establishment is marked by the large brazier atop its portico and a central garden." }, { "El Vidente Sediento", "The Thirsty Seer", "Also known as Cenir Faug, it is a warm, friendly, and collegial tavern nestled into a nook in the side of the Mindolluin. It has been beloved for centuries by the students and masters alike in the...", "Also known as Cenir Faug, it is a warm, friendly, and collegial tavern nestled into a nook in the side of the Mindolluin. It has been beloved for centuries by the students and masters alike in the..." }, { "El Águila y la Hoz", "The Eagle and Sickle", "Also known as Thoron a Cerch, a tiny wine-shop next to a larger lawn and garden where poets often come to recite their odes. Its name comes from two of the greater constellations.", "Also known as Thoron a Cerch, a tiny wine-shop next to a larger lawn and garden where poets often come to recite their odes. Its name comes from two of the greater constellations." } }
I.D[1879329672] = { "Teachings of the White City", "Teachings of the White City", 103, 90, 0, 5, 500, "Defensores de Minas Tirith", "", "Read the plaques of buildings used for the advancement of knowledge within the city of Minas Tirith.", "Read the plaques of buildings used for the advancement of knowledge within the city of Minas Tirith.", "Defenders of Minas Tirith", "" }
I.O[1879329672] = { { "Casa de los Cielos", "House of the Heavens", "Also known as Bâr Menel, a tower for gazing at the stars. Soothsayers and natural philosophers congregate here, and artisans craft navigational tools for the mariners of the Falas.", "Also known as Bâr Menel, a tower for gazing at the stars. Soothsayers and natural philosophers congregate here, and artisans craft navigational tools for the mariners of the Falas." }, { "Los Archivos Antiguos", "The Old Archives", "Also known as Gobeth Iaur, the original library of Minas Anor which delves into the pier-rock in the middle of the Sages’ Neath. It is dark, dusty, and little-used; its books and scrolls have no...", "Also known as Gobeth Iaur, the original library of Minas Anor which delves into the pier-rock in the middle of the Sages’ Neath. It is dark, dusty, and little-used; its books and scrolls have no..." }, { "Los Archivos de Vorondil", "The Archives of Vorondil", "Also known as Gobeth Vorondil, named for the last Steward not to serve as Ruling Steward. This library was built when Minas Anor was renamed as Minas Tirith. It is a brighter, more orderly place...", "Also known as Gobeth Vorondil, named for the last Steward not to serve as Ruling Steward. This library was built when Minas Anor was renamed as Minas Tirith. It is a brighter, more orderly place..." }, { "La Casa Negra", "The Black House", "Also known as Bâr Vorn, named for the dark stone of which it is built, as well for the ink used within. This is the chief scriptorium of Minas Tirith, where scribes write, copy, and translate texts...", "Also known as Bâr Vorn, named for the dark stone of which it is built, as well for the ink used within. This is the chief scriptorium of Minas Tirith, where scribes write, copy, and translate texts..." }, { "Casas del Saber", "Houses of Lore", "Also known as Bair Istoth, a collection of halls and towers where the wise gather to teach, learn, argue, and think. Younger sons and daughters of the nobility are often sent here to become sages;...", "Also known as Bair Istoth, a collection of halls and towers where the wise gather to teach, learn, argue, and think. Younger sons and daughters of the nobility are often sent here to become sages;..." } }
