I.O[1879354318] = { { "This road drives like a rod of iron from the Black Gates on into Gorgoroth, where it splits to encircle...", "This road drives like a rod of iron from the Black Gates on into Gorgoroth, where it splits to encircle...", "This road drives like a rod of iron from the Black Gates on into Gorgoroth, where it splits to encircle Orodruin.", "This road drives like a rod of iron from the Black Gates on into Gorgoroth, where it splits to encircle Orodruin." }, { "Many fell weapons and great war-works have winded their way down this road, out of the great forges of...", "Many fell weapons and great war-works have winded their way down this road, out of the great forges of...", "Many fell weapons and great war-works have winded their way down this road, out of the great forges of Anglach.", "Many fell weapons and great war-works have winded their way down this road, out of the great forges of Anglach." }, { "Thousands of rough pairs of feet have marched, stood, and camped upon Udûn's broad central basin.", "Thousands of rough pairs of feet have marched, stood, and camped upon Udûn's broad central basin.", "Thousands of rough pairs of feet have marched, stood, and camped upon Udûn's broad central basin.", "Thousands of rough pairs of feet have marched, stood, and camped upon Udûn's broad central basin." }, { "Atop this steep ascent, countless rough, cruel weapons were wrought to arm the Dark Lord's immeasurable...", "Atop this steep ascent, countless rough, cruel weapons were wrought to arm the Dark Lord's immeasurable...", "Atop this steep ascent, countless rough, cruel weapons were wrought to arm the Dark Lord's immeasurable armies.", "Atop this steep ascent, countless rough, cruel weapons were wrought to arm the Dark Lord's immeasurable armies." }, { "Servants bore goods and messages up this way to the fastness of Durthang.", "Servants bore goods and messages up this way to the fastness of Durthang.", "Servants bore goods and messages up this way to the fastness of Durthang.", "Servants bore goods and messages up this way to the fastness of Durthang." }, { "The lord of Durthang could survey his domain from this height -- and more.", "The lord of Durthang could survey his domain from this height -- and more.", "The lord of Durthang could survey his domain from this height -- and more.", "The lord of Durthang could survey his domain from this height -- and more." }, { "Comings and goings along the Iron Road can be viewed with ease from this spot.", "Comings and goings along the Iron Road can be viewed with ease from this spot.", "Comings and goings along the Iron Road can be viewed with ease from this spot.", "Comings and goings along the Iron Road can be viewed with ease from this spot." }, { "Being nearer to Barad-dûr, this path to Durthang was used for purposes of state and ceremony.", "Being nearer to Barad-dûr, this path to Durthang was used for purposes of state and ceremony.", "Being nearer to Barad-dûr, this path to Durthang was used for purposes of state and ceremony.", "Being nearer to Barad-dûr, this path to Durthang was used for purposes of state and ceremony." }, { "The heights above have been used for many purposes over the centuries; most recently to host a contingent of...", "The heights above have been used for many purposes over the centuries; most recently to host a contingent of...", "The heights above have been used for many purposes over the centuries; most recently to host a contingent of Easterling forces.", "The heights above have been used for many purposes over the centuries; most recently to host a contingent of Easterling forces." }, { "From here, a wary eye was kept on Anglach and the high bridge leading to it.", "From here, a wary eye was kept on Anglach and the high bridge leading to it.", "From here, a wary eye was kept on Anglach and the high bridge leading to it.", "From here, a wary eye was kept on Anglach and the high bridge leading to it." }, { "Rogkalúr", "Rogkalúr", "For what strange purpose was this platform used?", "For what strange purpose was this platform used?" }, { "It is no coincidence that directly before Anglach affords the best view of all eastern Udûn.", "It is no coincidence that directly before Anglach affords the best view of all eastern Udûn.", "It is no coincidence that directly before Anglach affords the best view of all eastern Udûn.", "It is no coincidence that directly before Anglach affords the best view of all eastern Udûn." }, { "An overseer may watch over the works below from here and, also, the road.", "An overseer may watch over the works below from here and, also, the road.", "An overseer may watch over the works below from here and, also, the road.", "An overseer may watch over the works below from here and, also, the road." }, { "Garganta de Hierro", "Isenmouthe", "The doors were somehow wrenched asunder in the chaos and struggle that directly followed the fall of Sauron.", "The doors were somehow wrenched asunder in the chaos and struggle that directly followed the fall of Sauron." }, { "Great steam and water works were controlled from this point, which looked down onto the waste reservoirs...", "Great steam and water works were controlled from this point, which looked down onto the waste reservoirs...", "Great steam and water works were controlled from this point, which looked down onto the waste reservoirs below.", "Great steam and water works were controlled from this point, which looked down onto the waste reservoirs below." } }
