I.O[1879395370] = { { "The Straight Stair", "The Straight Stair", "This is the first of the stairs climbed by Frodo Baggins, Samwise Gamgee, and the creature Gollum by which they intended to gain access to the Land of Mordor. The stairs are tall and steep, and while...", "This is the first of the stairs climbed by Frodo Baggins, Samwise Gamgee, and the creature Gollum by which they intended to gain access to the Land of Mordor. The stairs are tall and steep, and while..." }, { "The Winding Stair", "The Winding Stair", "This second stair begins high above the valley floor, and unlike the Straight Stair it weaves back and forth along the cliffside, a great chasm yawning to one side. At the top of the stairs, a dark...", "This second stair begins high above the valley floor, and unlike the Straight Stair it weaves back and forth along the cliffside, a great chasm yawning to one side. At the top of the stairs, a dark..." }, { "Echad Taerdim", "Echad Taerdim", "Mablung has established the small camp of Echad Taerdim at the top of the Straight Stair, and he intends to use it as a base from which to mount small expeditions into nearby Cirith Ungol.", "Mablung has established the small camp of Echad Taerdim at the top of the Straight Stair, and he intends to use it as a base from which to mount small expeditions into nearby Cirith Ungol." }, { "Cadar Skûs", "Cadar Skûs", "The Ungoledain have come a long way overland across Middle-earth, following a call only they can hear, and they have established the resting-place of Cadar Skûs in the mountains. Is their long...", "The Ungoledain have come a long way overland across Middle-earth, following a call only they can hear, and they have established the resting-place of Cadar Skûs in the mountains. Is their long..." }, { "Torech Ungol", "Torech Ungol", "The pass of Cirith Ungol was rarely left unguarded, but few only would dare to make the crossing while the Orcs of the tower could spy on them from above. The worse and far greater danger was spoken...", "The pass of Cirith Ungol was rarely left unguarded, but few only would dare to make the crossing while the Orcs of the tower could spy on them from above. The worse and far greater danger was spoken..." }, { "Remmorchant, la Red de la Oscuridad", "Remmorchant, the Net of Darkness", "None have seen beyond the entrance to Remmorchant, the Net of Darkness, for that is the deepest and most subterranean of Ungwetári's tunnels, the pitted and sunless abyss into which she retreated...", "None have seen beyond the entrance to Remmorchant, the Net of Darkness, for that is the deepest and most subterranean of Ungwetári's tunnels, the pitted and sunless abyss into which she retreated..." }, { "Taurlingol", "Taurlingol", "The forest of Taurlingol has become spider-infested, a place of webs and unnatural voices. If the Ungoledain can understand the chittering of their idols, they are unwilling to share its meaning....", "The forest of Taurlingol has become spider-infested, a place of webs and unnatural voices. If the Ungoledain can understand the chittering of their idols, they are unwilling to share its meaning...." }, { "Kaslokroz", "Kaslokroz", "Uruks following the commands of Rukhor the Pale Herald have established this camp atop the Winding Stair, west of Cirith Ungol. It seems they have run afoul of the Ungoledain and spiders ranging out...", "Uruks following the commands of Rukhor the Pale Herald have established this camp atop the Winding Stair, west of Cirith Ungol. It seems they have run afoul of the Ungoledain and spiders ranging out..." } }
