I.O[1879418378] = { { "Maergrind, la Puerta Noble", "Maergrind, The Noble Gate", "You have explored Maergrind, The Noble Gate. This is the primary entrance to the great dwarf-city of Gundabad.", "You have explored Maergrind, The Noble Gate. This is the primary entrance to the great dwarf-city of Gundabad." }, { "Asbaj-khîrfin", "Asbaj-khîrfin", "You have explored Asbaj-khîrfin. Once a building of commerce found within the mighty court, it is now a small dwarf-outpost.", "You have explored Asbaj-khîrfin. Once a building of commerce found within the mighty court, it is now a small dwarf-outpost." }, { "Imrêkh-guthlu", "Imrêkh-guthlu", "You have explored Imrêkh-guthlu. Once a great home of a noble in Máttugard, now the building is a small dwarf-outpost, keeping watch over the entrance to the Deepscrave.", "You have explored Imrêkh-guthlu. Once a great home of a noble in Máttugard, now the building is a small dwarf-outpost, keeping watch over the entrance to the Deepscrave." }, { "Zidir-nesad, La Escarpada", "Zidir-nesad, The Steepset", "You have explored Zidir-nesad, The Steepset. The great court and throne of the Steepset were once the seat of Gundabad’s lord.", "You have explored Zidir-nesad, The Steepset. The great court and throne of the Steepset were once the seat of Gundabad’s lord." }, { "Shalakibal", "Shalakibal", "You have explored Shalakibal. The waterways of Shalakibal bring fresh waters to Máttugard from underground springs.", "You have explored Shalakibal. The waterways of Shalakibal bring fresh waters to Máttugard from underground springs." }, { "Vérnozal", "Vérnozal", "You have explored the hall of Vérnozal. The hall of Vérnozal was once a place where the nobles of Gundabad would come to converse and make decisions for the city.", "You have explored the hall of Vérnozal. The hall of Vérnozal was once a place where the nobles of Gundabad would come to converse and make decisions for the city." } }
