I.O[1879422593] = { { "Drúkala", "Drúkala", "Long known to the Orcs as Skaizagâf, or the curse-cave, Gloomingtarn was forbidden to all of their kind until the Angmarim overcame the warding-runes with the aid of Máltagar, the Fell Graver....", "Long known to the Orcs as Skaizagâf, or the curse-cave, Gloomingtarn was forbidden to all of their kind until the Angmarim overcame the warding-runes with the aid of Máltagar, the Fell Graver...." }, { "Ormgren", "Ormgren", "Although nearly no evidence remains of its once-rich deposits, Ormgren was among the first lodes delved by Durin the Deathless after he awoke in Mount Gundabad. For many years after Gloomingtarn was...", "Although nearly no evidence remains of its once-rich deposits, Ormgren was among the first lodes delved by Durin the Deathless after he awoke in Mount Gundabad. For many years after Gloomingtarn was..." }, { "Glittengrof", "Glittengrof", "Rumoured to be the cavern where Durin the Deathless discovered the first crystals he would use to light the halls of Mount Gundabad, Glittengrof is now home to an invasive brood of spiders whose webs...", "Rumoured to be the cavern where Durin the Deathless discovered the first crystals he would use to light the halls of Mount Gundabad, Glittengrof is now home to an invasive brood of spiders whose webs..." }, { "Skelstrand", "Skelstrand", "Along the western bank of Durthuzâram lies Skelstrand, a stretch of jagged shoals and tidepools inhabited by the crab-like ukhrâsh.", "Along the western bank of Durthuzâram lies Skelstrand, a stretch of jagged shoals and tidepools inhabited by the crab-like ukhrâsh." }, { "Mîn Lorg", "Mîn Lorg", "Determined to uncover the secrets of Gloomingtarn, the Angmarim have unwittingly discovered Mîn Lorg, an ancient and seemingly-untouched passage which leads downward into the deepest depths of Mount...", "Determined to uncover the secrets of Gloomingtarn, the Angmarim have unwittingly discovered Mîn Lorg, an ancient and seemingly-untouched passage which leads downward into the deepest depths of Mount..." }, { "Lochan Dúv", "Lochan Dúv", "Established not long after the Angmarim breached the warding-runes of Gloomingtarn, Lochan Dúv is the Iron Crown's deepest foothold within the hallowed caverns of Mount Gundabad. Although many...", "Established not long after the Angmarim breached the warding-runes of Gloomingtarn, Lochan Dúv is the Iron Crown's deepest foothold within the hallowed caverns of Mount Gundabad. Although many..." } }
I.D[1879424673] = { "Sites of Deepscrave", "Sites of Deepscrave", 103, 130, 1000, 5, 500, "Recuperadores de la Fortaleza de la Montaña", "Explorador de Hendidura Profunda", "Explore the points of interests within Deepscrave.", "Explore the points of interests within Deepscrave.", "Reclaimers of the Mountain-hold", "Explorer of Deepscrave" }
I.O[1879424673] = { { "Aslíf", "Aslíf", "Amidst the unfriendly dark of Deepscrave, the Gabil'akkâ have eked out a small place of respite. Aslíf clings to the Berg-beam, as if it is in danger of disappearing into the shadows that surround it.", "Amidst the unfriendly dark of Deepscrave, the Gabil'akkâ have eked out a small place of respite. Aslíf clings to the Berg-beam, as if it is in danger of disappearing into the shadows that surround it." }, { "Buzra-salân", "Buzra-salân", "A waterfall that spills into the depths of Deepscrave. The dwarf-homes that cluster around Buzra-salân are mostly intact, as Orcs have claimed these homes for their own.", "A waterfall that spills into the depths of Deepscrave. The dwarf-homes that cluster around Buzra-salân are mostly intact, as Orcs have claimed these homes for their own." }, { "Gabil-memâg", "Gabil-memâg", "Water from the adjacent Gloomingtarn pours onto the ancient water-wheels at Gabil-memâg. During brighter days, the water-wheels powered the lifts of Deepscrave. Now they serve little purpose, cycling...", "Water from the adjacent Gloomingtarn pours onto the ancient water-wheels at Gabil-memâg. During brighter days, the water-wheels powered the lifts of Deepscrave. Now they serve little purpose, cycling..." }, { "'Abad-nuhbu, the Berg-beam", "'Abad-nuhbu, the Berg-beam", "Sometimes referred to as the Pillar of the Mountain, the Berg-beam almost seems to hold the entire cavern ceiling aloft. It was here that most of the common folk of Gundabad built their homes.", "Sometimes referred to as the Pillar of the Mountain, the Berg-beam almost seems to hold the entire cavern ceiling aloft. It was here that most of the common folk of Gundabad built their homes." } }
