I.O[1879430142] = { { "Dashat-zahar", "Dashat-zahar", "Tucked into the curved walls of Clovengap, Dashât-zahar was once a marketplace specializing in the sale and trade of Zigilmarn, the renowned wine made from the gap's own grapes. Once, tall vases,...", "Tucked into the curved walls of Clovengap, Dashât-zahar was once a marketplace specializing in the sale and trade of Zigilmarn, the renowned wine made from the gap's own grapes. Once, tall vases,..." }, { "Garanashmar", "Garanashmar", "The ancestral home of Forstóri's Line perches high above the river Kurdushâlak. Clovengap's gardens, vineyards, and clean, pure waters, brought much wealth to the clan of Forstóri, the first dwarf...", "The ancestral home of Forstóri's Line perches high above the river Kurdushâlak. Clovengap's gardens, vineyards, and clean, pure waters, brought much wealth to the clan of Forstóri, the first dwarf..." }, { "Frósthel", "Frósthel", "Long before the passing of a dragon coated the northern end of Clovengap with ice and rime frost, Frósthel's field were lush and green. Shepherds herded livestock amidst tall grass, leading them to...", "Long before the passing of a dragon coated the northern end of Clovengap with ice and rime frost, Frósthel's field were lush and green. Shepherds herded livestock amidst tall grass, leading them to..." }, { "Anatrâd", "Anatrâd", "The fortress of Anatrâd, the river-watch, once housed the guardians and protectors of Clovengap. From this location, dwarves from all over Gundabad converged in order to march through the tunnel...", "The fortress of Anatrâd, the river-watch, once housed the guardians and protectors of Clovengap. From this location, dwarves from all over Gundabad converged in order to march through the tunnel..." }, { "Maranazhâr", "Maranazhâr", "When Forstóri was tasked with guardianship of Clovengap, one of the first things he did was send a delegation of dwarves to the surrounding lands to collect seeds and saplings. Among the fruit trees,...", "When Forstóri was tasked with guardianship of Clovengap, one of the first things he did was send a delegation of dwarves to the surrounding lands to collect seeds and saplings. Among the fruit trees,..." }, { "Skarashulg", "Skarashulg", "Ancient records of Clovengap speak of tiers of heavy-laden fruit trees planted in neat rows upon the western tiers. Whatever may once have grown in gardens and orchards here is long gone, ripped out...", "Ancient records of Clovengap speak of tiers of heavy-laden fruit trees planted in neat rows upon the western tiers. Whatever may once have grown in gardens and orchards here is long gone, ripped out..." }, { "Min Návaid", "Min Návaid", "In days long ago, too numerous to count, a dragon fell from the sky, its body pierced with dwarf-made weapons. Into Clovengap he crashed, and slithered like a giant worm into a tunnel he found behind...", "In days long ago, too numerous to count, a dragon fell from the sky, its body pierced with dwarf-made weapons. Into Clovengap he crashed, and slithered like a giant worm into a tunnel he found behind..." } }
I.D[1879430143] = { "Discovering Clovengap", "Discovering Clovengap", 103, 130, 1000, 5, 500, "Recuperadores de la Fortaleza de la Montaña", "Explorador de Pasohendido", "Explore important points of interest and natural landmarks within Clovengap.", "Explore important points of interest and natural landmarks within Clovengap.", "Reclaimers of the Mountain-hold", "Explorer of Clovengap" }
I.O[1879430143] = { { "Stókkset", "Stókkset", "After the inky darkness of Gloomingtarn, the open sky above Stókkset is a blessing for some less used to being underground. Ages ago, part of the ceiling caved in, creating the first Forest beneath...", "After the inky darkness of Gloomingtarn, the open sky above Stókkset is a blessing for some less used to being underground. Ages ago, part of the ceiling caved in, creating the first Forest beneath..." }, { "Kurdushâlak", "Kurdushâlak", "Kurdushâlak carves a deep channel through the centre of Clovengap. The river is fed by multiple falls and runs the length of the cavern.", "Kurdushâlak carves a deep channel through the centre of Clovengap. The river is fed by multiple falls and runs the length of the cavern." }, { "Danakh-khêj", "Danakh-khêj", "Benches in various states of decay and rust line the main path through this green meadow. Danakh-khêj was once a park where dwarves came to enjoy the emerald grasses and sparkling sapphire waters of...", "Benches in various states of decay and rust line the main path through this green meadow. Danakh-khêj was once a park where dwarves came to enjoy the emerald grasses and sparkling sapphire waters of..." }, { "Tharrkirîn", "Tharrkirîn", "As the dwarves delved deeper into the depths of Gundabad, they came across stone in shapes and veins which they had not previously discovered. When the ceiling of Clovengap fell in, examples of these...", "As the dwarves delved deeper into the depths of Gundabad, they came across stone in shapes and veins which they had not previously discovered. When the ceiling of Clovengap fell in, examples of these..." }, { "Amgaruslun", "Amgaruslun", "The roaring of the Amgaruslun falls sit stilled now, by the icy passage of the dragon Hrímil. This waterfall was one of many that fed the river Kurdushâlak. Though the sun's rays sparkle on the ice,...", "The roaring of the Amgaruslun falls sit stilled now, by the icy passage of the dragon Hrímil. This waterfall was one of many that fed the river Kurdushâlak. Though the sun's rays sparkle on the ice,..." }, { "Bazanmanar", "Bazanmanar", "Bazanmanar was once a huge open-air market packed both with local and visiting dwarves. Heavily laden tables of food, wine, honey, jewels, and other fineries were scattered about the area. Visitors...", "Bazanmanar was once a huge open-air market packed both with local and visiting dwarves. Heavily laden tables of food, wine, honey, jewels, and other fineries were scattered about the area. Visitors..." } }
