I.O[1879438581] = { { "Fellgát", "Fellgát", "You have explored Fellgát. The dwarf encampment of Fellgát was recently established.", "You have explored Fellgát. The dwarf encampment of Fellgát was recently established." }, { "Flogalith", "Flogalith", "You have explored Flogalith. The old drake breeding grounds of Flogalith have become very active of late.", "You have explored Flogalith. The old drake breeding grounds of Flogalith have become very active of late." }, { "Draurákh", "Draurákh", "You have explored Draurákh. High up on the peaks of Mount Gundabad, beasts seek shelter within the caverns of Draurákh.", "You have explored Draurákh. High up on the peaks of Mount Gundabad, beasts seek shelter within the caverns of Draurákh." }, { "Mullach Cagar", "Mullach Cagar", "You have explored Mullach Cagar. The Angmarim encampment of Mullach Cagar guards one of the peaks of Gundabad.", "You have explored Mullach Cagar. The Angmarim encampment of Mullach Cagar guards one of the peaks of Gundabad." }, { "Thyrstáth", "Thyrstáth", "You have explored Thyrstáth. The ice-giants who dwell in their city of Thyrstáth have been dragged into war.", "You have explored Thyrstáth. The ice-giants who dwell in their city of Thyrstáth have been dragged into war." }, { "Bagud-dum", "Bagud-dum", "You have explored Bagud-dum. The fort of Bagud-dum rests high up on the slopes of Mountain Gundabad.", "You have explored Bagud-dum. The fort of Bagud-dum rests high up on the slopes of Mountain Gundabad." }, { "Bagud-bukhnu", "Bagud-bukhnu", "You have explored Bagud-bukhnu. Upon this great vantage point, one could see a vast distance away on a clear day.", "You have explored Bagud-bukhnu. Upon this great vantage point, one could see a vast distance away on a clear day." }, { "Uzdarulzahar", "Uzdarulzahar", "You have explored Uzdarulzahar. The old ruins of Uzdarulzahar rest upon the slopes of Mount Gundabad.", "You have explored Uzdarulzahar. The old ruins of Uzdarulzahar rest upon the slopes of Mount Gundabad." }, { "Ibdêkh-buzru, el Valle de las Cosas", "Ibdêkh-buzru, the Thing-fold", "You have explored Ibdêkh-buzru, the Thing-fold. A great meeting of the dwarf clans to settle differences, make alliances, and hold celebrations was held in ancient times in the Thing-fold.", "You have explored Ibdêkh-buzru, the Thing-fold. A great meeting of the dwarf clans to settle differences, make alliances, and hold celebrations was held in ancient times in the Thing-fold." }, { "Grymmclúd", "Grymmclúd", "You have explored Grymmclúd. The crags of Grymmclúd are filled with beasts.", "You have explored Grymmclúd. The crags of Grymmclúd are filled with beasts." }, { "Bazan-medan", "Bazan-medan", "You have explored Bazan-medan. The gate of Bazan-medan leads to the Clovengap in Gundabad.", "You have explored Bazan-medan. The gate of Bazan-medan leads to the Clovengap in Gundabad." } }
