I.O[1879464436] = { { "Ost Norhír", "Ost Norhír", "The ruin of Ost Norhír stands atop the hill overlooking the river south of the Harlond, but now it is inhabited only by wildlife. When the people departed to rebuild their lives in the aftermath of...", "The ruin of Ost Norhír stands atop the hill overlooking the river south of the Harlond, but now it is inhabited only by wildlife. When the people departed to rebuild their lives in the aftermath of..." }, { "Galdir's Dell", "Galdir's Dell", "The encampment that once stood in Galdir's Dell is now burned and unrecognizable. Wargs pad among the scorched wooden structures, and their howls linger on the breezes that sweep over the river.", "The encampment that once stood in Galdir's Dell is now burned and unrecognizable. Wargs pad among the scorched wooden structures, and their howls linger on the breezes that sweep over the river." }, { "Aegollant", "Aegollant", "The tents of the Haradrim remain at Aegollant, despite the defeat of the Black Serpent at the Battle of Pelennor Fields, but they are now home mostly to brigands and others who hold villainy in their...", "The tents of the Haradrim remain at Aegollant, despite the defeat of the Black Serpent at the Battle of Pelennor Fields, but they are now home mostly to brigands and others who hold villainy in their..." }, { "Erui Delta", "Erui Delta", "The River Erui empties into the Anduin here, and avanc prowl among the reedy banks, threatening unwary travellers.", "The River Erui empties into the Anduin here, and avanc prowl among the reedy banks, threatening unwary travellers." }, { "Taustrok", "Taustrok", "Remnants of the Morgul-host, scattered after the Battle of the Pelennor Fields, have begun to gather in alarming numbers in a camp they call 'Taustrok.' Within dank caves they burrow into the...", "Remnants of the Morgul-host, scattered after the Battle of the Pelennor Fields, have begun to gather in alarming numbers in a camp they call 'Taustrok.' Within dank caves they burrow into the..." } }
