I.O[1879466403] = { { "Ethring", "Ethring", "The village of Ethring stands on either side of the main fords of the Ringló. After dealing with the Ruthless Dead, spiders, and Orcs during the Dawnless Day, its denizens are eager for a return to...", "The village of Ethring stands on either side of the main fords of the Ringló. After dealing with the Ruthless Dead, spiders, and Orcs during the Dawnless Day, its denizens are eager for a return to..." }, { "Eilendoth", "Eilendoth", "You have discovered Eilendoth perched above the Ringló Vale. It is kept by Authest, ever steadfast in his duty.", "You have discovered Eilendoth perched above the Ringló Vale. It is kept by Authest, ever steadfast in his duty." }, { "Lumber Camp", "Lumber Camp", "The lumber camp lies upriver from Ethring. Its products will be vital to the restoration of Gondor.", "The lumber camp lies upriver from Ethring. Its products will be vital to the restoration of Gondor." }, { "Dâr Matum", "Dâr Matum", "During the Dawnless Day, Dâr Matum played host to the Ruthless Dead under Drugât's command. In their absence, a brood of spiders has taken roost.", "During the Dawnless Day, Dâr Matum played host to the Ruthless Dead under Drugât's command. In their absence, a brood of spiders has taken roost." }, { "Grishru", "Grishru", "You have discovered Gríshru, a White Mountain Orc camp.", "You have discovered Gríshru, a White Mountain Orc camp." }, { "The Bolt-holes", "The Bolt-holes", "The so-called 'Bolt-holes' is the last remaining refuge for brigands in the Vale.", "The so-called 'Bolt-holes' is the last remaining refuge for brigands in the Vale." } }
