I.O[1879466405] = { { "Calembel", "Calembel", "The city of Calembel finds itself a waystation for all manner of goods and people as Gondor seeks to build itself anew.", "The city of Calembel finds itself a waystation for all manner of goods and people as Gondor seeks to build itself anew." }, { "Tathrendalf", "Tathrendalf", "Left behind when the war ended, the Corsairs of Tathrendalf find themselves in a precarious position within Lamedon. Neither party knows quite how to handle the other. Perhaps peace can be brokered...", "Left behind when the war ended, the Corsairs of Tathrendalf find themselves in a precarious position within Lamedon. Neither party knows quite how to handle the other. Perhaps peace can be brokered..." }, { "Dínadab", "Dínadab", "The hamlet of Dínadab remains quiet as ever, quieter still for the loss of one of its sons, Fuirion, who fell during the Dawnless Day.", "The hamlet of Dínadab remains quiet as ever, quieter still for the loss of one of its sons, Fuirion, who fell during the Dawnless Day." }, { "Lothgobel", "Lothgobel", "Occupied by Corsairs during the war, the people of Lothgobel have returned to their homes, pleasantly surprised to find things mostly intact. They carry on the artifice of normalcy, forever aware of...", "Occupied by Corsairs during the war, the people of Lothgobel have returned to their homes, pleasantly surprised to find things mostly intact. They carry on the artifice of normalcy, forever aware of..." }, { "Bar Elir", "Bar Elir", "The farmstead of Bar Elir is known for its exceptionally fertile soil, being at the convergence of two waterways.", "The farmstead of Bar Elir is known for its exceptionally fertile soil, being at the convergence of two waterways." }, { "Roz Ladâr", "Roz Ladâr", "With Sauron's fall, the Orcs of Roz Ladâr retreated into their camp.", "With Sauron's fall, the Orcs of Roz Ladâr retreated into their camp." } }
I.D[1879466406] = { "Explorer of Dor-en-Ernil Renewed", "Explorer of Dor-en-Ernil Renewed", 103, 140, 1000, 0, 700, "La Renovación de Gondor", "Viajero de Dor-en-Ernil Renovada", "Explore Dor-en-Ernil in western King's Gondor.", "Explore Dor-en-Ernil in western King's Gondor.", "The Renewal of Gondor", "Traveller of Dor-en-Ernil Renewed" }
I.O[1879466406] = { { "Dol Brannor", "Dol Brannor", "The beacon of Dol Brannor stands in Dor-en-Ernil as a symbol of its strategic value to Central Gondor. Once home to an occupying force of Haradrim and Corsair, Dol Brannor has been freed once more...", "The beacon of Dol Brannor stands in Dor-en-Ernil as a symbol of its strategic value to Central Gondor. Once home to an occupying force of Haradrim and Corsair, Dol Brannor has been freed once more..." }, { "Tungobel", "Tungobel", "Once a humble village of Gondor, taken over and assaulted by the Corsairs of Umbar. Many of its inhabitants have been displaced. The freedom of Dor-en-Ernil and how much value it has wanes the longer...", "Once a humble village of Gondor, taken over and assaulted by the Corsairs of Umbar. Many of its inhabitants have been displaced. The freedom of Dor-en-Ernil and how much value it has wanes the longer..." }, { "Lang Boha", "Lang Boha", "Once the site of the Corsair and Haradrim landing, Lang Boha remains a desolate and barren reminder of the war's ravages on Dor-en-Ernil. It has been left to ruin, and the local fauna have taken...", "Once the site of the Corsair and Haradrim landing, Lang Boha remains a desolate and barren reminder of the war's ravages on Dor-en-Ernil. It has been left to ruin, and the local fauna have taken..." }, { "Gaerlond", "Gaerlond", "A once humble hamlet seated on the eastern coast of Dor-en-Ernil. It has long been abandoned since the Haradrim and Corsair raids. All that remains are whispers of the dead.", "A once humble hamlet seated on the eastern coast of Dor-en-Ernil. It has long been abandoned since the Haradrim and Corsair raids. All that remains are whispers of the dead." }, { "Parth Reposo", "Parth Rest", "Once the site of a deadly battleground during the war, Parth Rest was erected by the brother Herion to oversee rebuilding efforts and to organize supplies being transported through the region.", "Once the site of a deadly battleground during the war, Parth Rest was erected by the brother Herion to oversee rebuilding efforts and to organize supplies being transported through the region." }, { "Barad Rill", "Barad Rill", "The Shining Tower was once a beacon guiding the Gondorian fleet through Ethir Anduin and the Bay of Belfalas. It was conquered by Dolgimil and left to ruin. Garvir now seeks to rebuild the tower, so...", "The Shining Tower was once a beacon guiding the Gondorian fleet through Ethir Anduin and the Bay of Belfalas. It was conquered by Dolgimil and left to ruin. Garvir now seeks to rebuild the tower, so..." } }
I.D[1879466408] = { "Explorer of Belfalas Renewed", "Explorer of Belfalas Renewed", 103, 140, 1000, 0, 700, "La Renovación de Gondor", "Viajero de Belfalas Renovado", "Explore the Havens of Belfalas in western King's Gondor.", "Explore the Havens of Belfalas in western King's Gondor.", "The Renewal of Gondor", "Traveller of Belfalas Renewed" }
I.O[1879466408] = { { "Dol Amroth", "Dol Amroth", "Dol Amroth is the seat of Imrahil, the Prince of Belfalas, and is home to the noble and legendary swan-knights. With the siege of the Corsairs broken, the city's ports now lay open and ships are free...", "Dol Amroth is the seat of Imrahil, the Prince of Belfalas, and is home to the noble and legendary swan-knights. With the siege of the Corsairs broken, the city's ports now lay open and ships are free..." }, { "Abedec's Watch", "Abedec's Watch", "What was once a Corsair stronghold remains now as an echo of its former self. Corsairs who have found themselves stranded in Gondor have flocked here out of a desire for safety, vengeance, or both.", "What was once a Corsair stronghold remains now as an echo of its former self. Corsairs who have found themselves stranded in Gondor have flocked here out of a desire for safety, vengeance, or both." }, { "Amon Lontir", "Amon Lontir", "During the war, the vantage point of Amon Lontir gave beacon-wardens a clear view of the Corsair invasion in the bay. Nowadays, it offers the calming sight of Belfalas at peace.", "During the war, the vantage point of Amon Lontir gave beacon-wardens a clear view of the Corsair invasion in the bay. Nowadays, it offers the calming sight of Belfalas at peace." }, { "Edhellond", "Edhellond", "Corsairs occupied the crumbling ruins of Edhellond during the war. Now, the Elves of the Avorrim work tirelessly to turn the harbour into a garden.", "Corsairs occupied the crumbling ruins of Edhellond during the war. Now, the Elves of the Avorrim work tirelessly to turn the harbour into a garden." }, { "Hashadir", "Hashadir", "The Corsairs of Umbar have been driven away from Hashadir, but they left behind a significant rodent infestation among their destroyed tents. The shores too, have reverted back to nature, with a...", "The Corsairs of Umbar have been driven away from Hashadir, but they left behind a significant rodent infestation among their destroyed tents. The shores too, have reverted back to nature, with a..." }, { "Makham Mijann", "Makham Mijann", "Following the Corsairs' abandonment of Makham Mijann, the residents of Tadrent attempted to dismantle the camp for various crafting materials. These efforts paused during the king's coronation, and...", "Following the Corsairs' abandonment of Makham Mijann, the residents of Tadrent attempted to dismantle the camp for various crafting materials. These efforts paused during the king's coronation, and..." }, { "Nendath", "Nendath", "Once overrun by Corsairs, Nendath has since been reclaimed by the beacon-wardens.", "Once overrun by Corsairs, Nendath has since been reclaimed by the beacon-wardens." }, { "Ost Lontir", "Ost Lontir", "The undercurrent of anxiety that permeated Ost Lontir in the days of the war has dissipated since. But as the closest settlement to Amon Lontir, its townsfolk remain vigilant for other troubles...", "The undercurrent of anxiety that permeated Ost Lontir in the days of the war has dissipated since. But as the closest settlement to Amon Lontir, its townsfolk remain vigilant for other troubles..." }, { "Ost Amondal", "Ost Amondal", "Crumbling ruins are all that remain of the once-proud Gondorian fortress of Ost Amondal. Access to the site has been cut off for many years, but with the opening of the pass in Belfalas, it is...", "Crumbling ruins are all that remain of the once-proud Gondorian fortress of Ost Amondal. Access to the site has been cut off for many years, but with the opening of the pass in Belfalas, it is..." }, { "Tadrent", "Tadrent", "The shipping line in Tadrent did not end with the War of the Ring. It continues to this day, helping settlements throughout the region recover and rebuild.", "The shipping line in Tadrent did not end with the War of the Ring. It continues to this day, helping settlements throughout the region recover and rebuild." } }
