I.D[1879468393] = { "Perils of the Langstrand", "Perils of the Langstrand", 103, 133, 1000, 0, 0, "", "Explorador de Anfalas", "Explore enemy encampments and other dangerous places in Anfalas.", "Explore enemy encampments and other dangerous places in Anfalas.", "", "Scout of Anfalas" }
I.O[1879468393] = { { "Khatsûr", "Khatsûr", "What once served as a landing for many Corsair raids remains on the shores of Hathollant as a ready reminder that the Corsairs could return in force at any moment. Now, it serves as home to...", "What once served as a landing for many Corsair raids remains on the shores of Hathollant as a ready reminder that the Corsairs could return in force at any moment. Now, it serves as home to..." }, { "Snarlwood", "Snarlwood", "Filled with avanc, Snarlwood remains a bastion and home for the animals, and a readily available source of sustenance for the most daring of hunters in Langstrand.", "Filled with avanc, Snarlwood remains a bastion and home for the animals, and a readily available source of sustenance for the most daring of hunters in Langstrand." }, { "Delugel", "Delugel", "Throughout time this place has been avoided by many a resident of Lond Cirion, given to the cautionary tales of fantasy. Do those that dwell within claim its power by those very tales or have they...", "Throughout time this place has been avoided by many a resident of Lond Cirion, given to the cautionary tales of fantasy. Do those that dwell within claim its power by those very tales or have they..." }, { "Loxhall", "Loxhall", "Once a site for travellers to find reprieve and make camp, Loxhall has long been taken over by the growing lynx population.", "Once a site for travellers to find reprieve and make camp, Loxhall has long been taken over by the growing lynx population." }, { "Springer's Close", "Springer's Close", "Springer's Close is a place known to many residents of Barad Faen as the main concern for many travellers making their way to Iaphel and Pinnath Gelin.", "Springer's Close is a place known to many residents of Barad Faen as the main concern for many travellers making their way to Iaphel and Pinnath Gelin." }, { "Khâla Niket", "Khâla Niket", "Long ago, the cove of Khâla Niket proved deadly for the Corsair banner-ship that sought to gain access to the unprotected lands nearby. Today, only the wreck remains, a grim reminder of the Umbari...", "Long ago, the cove of Khâla Niket proved deadly for the Corsair banner-ship that sought to gain access to the unprotected lands nearby. Today, only the wreck remains, a grim reminder of the Umbari..." }, { "Fleetmire", "Fleetmire", "In their search for wood, the Corsairs have destroyed many trees and disturbed the local wild-life -- most notably the bog-lurkers.", "In their search for wood, the Corsairs have destroyed many trees and disturbed the local wild-life -- most notably the bog-lurkers." }, { "Bel Tâkhmar", "Bel Tâkhmar", "Having avoided the worst of the fighting during the war, the Corsairs in Anfalas remain a well-equipped threat.", "Having avoided the worst of the fighting during the war, the Corsairs in Anfalas remain a well-equipped threat." }, { "Wreck of the Kêl Tezhor", "Wreck of the Kêl Tezhor", "Not all of the Corsairs who raided Anfalas were lucky enough to emerge with ill-gotten goods. Some found themselves at the mercy of the sea -- a peril all Corsairs are familiar with, but one that...", "Not all of the Corsairs who raided Anfalas were lucky enough to emerge with ill-gotten goods. Some found themselves at the mercy of the sea -- a peril all Corsairs are familiar with, but one that..." }, { "Lithengris", "Lithengris", "For those who know what they're doing, or otherwise are willing to risk a few fingers, the crabs at Lithengris are a valuable source of food. Very few people venture into the cave itself, however....", "For those who know what they're doing, or otherwise are willing to risk a few fingers, the crabs at Lithengris are a valuable source of food. Very few people venture into the cave itself, however...." }, { "Dun Ox Herd", "Dun Ox Herd", "The dun oxen roam the hills of Anfalas peacefully, unbothered by the sparse vegetation and arid climate of their home. Get too close, however, and you may find that a bull's horns are just as sharp...", "The dun oxen roam the hills of Anfalas peacefully, unbothered by the sparse vegetation and arid climate of their home. Get too close, however, and you may find that a bull's horns are just as sharp..." } }
