I.O[1879524270] = { { "Kakidûr", "Kakidûr", "Old-timers in the village of Hanamíku will tell you that there have always been trouble-makers on the hills above the village, and they would be right: before the brigands, Kakidûr was home to...", "Old-timers in the village of Hanamíku will tell you that there have always been trouble-makers on the hills above the village, and they would be right: before the brigands, Kakidûr was home to..." }, { "Aptíku", "Aptíku", "Brigands dwell at Aptíku alongside the shore of the Hatokáli River. Any who speak Nêshakari would recognize the name as meaning 'reed-mist,' and would find it most appropriate. Few aside from their...", "Brigands dwell at Aptíku alongside the shore of the Hatokáli River. Any who speak Nêshakari would recognize the name as meaning 'reed-mist,' and would find it most appropriate. Few aside from their..." }, { "Mut-hûru", "Mut-hûru", "The caverns of Mut-hûru are actually two cave systems, joined through burrowing activity by underground dwellers beneath the Ridge of Plenty. Tombs of the dead, long abandoned by any save kergrim...", "The caverns of Mut-hûru are actually two cave systems, joined through burrowing activity by underground dwellers beneath the Ridge of Plenty. Tombs of the dead, long abandoned by any save kergrim..." }, { "Mûl Erebu", "Mûl Erebu", "Good folk abandoned Mûl Erebu; now it is given over only to scorpions and to those who thought to make use of them, to their sorrow.", "Good folk abandoned Mûl Erebu; now it is given over only to scorpions and to those who thought to make use of them, to their sorrow." }, { "Bolo Thúki", "Bolo Thúki", "Bolo Thúki is the northernmost of the three primary encampments seized by Bârshud's Ordâkhai as they fled south. Here his soldiers attempt to fortify the hillside and make use of the supplies they...", "Bolo Thúki is the northernmost of the three primary encampments seized by Bârshud's Ordâkhai as they fled south. Here his soldiers attempt to fortify the hillside and make use of the supplies they..." }, { "Nakársong", "Nakársong", "This is the second of the primary encampments seized by Bârshud's Ordâkhai as they fled into Pahar Hatokáli. Here they keep many of the lions they intend to unleash upon Mizâdi's forces, but the...", "This is the second of the primary encampments seized by Bârshud's Ordâkhai as they fled into Pahar Hatokáli. Here they keep many of the lions they intend to unleash upon Mizâdi's forces, but the..." }, { "Imizíla", "Imizíla", "The fortress of Imizíla, 'last torch' in the Shagâni language, has appropriately become the final bastion for Bârshud's Ordâkhai in Pahar Hatokáli. Trapped between the pursuing forces of Shâra Mizâdi...", "The fortress of Imizíla, 'last torch' in the Shagâni language, has appropriately become the final bastion for Bârshud's Ordâkhai in Pahar Hatokáli. Trapped between the pursuing forces of Shâra Mizâdi..." }, { "Ukh-bâra", "Ukh-bâra", "The zizani of Ukh-bâra fill the moist air with the sound of their call, and the underbrush rustles as they move hither and yon on skittering legs. Water splashes nearby but you cannot identify the...", "The zizani of Ukh-bâra fill the moist air with the sound of their call, and the underbrush rustles as they move hither and yon on skittering legs. Water splashes nearby but you cannot identify the..." }, { "Roz Káskrauz", "Roz Káskrauz", "The Orcs of Roz Káskrauz are war-like and aggressive, and while they prefer to remain within their stronghold, they will emerge from it to do battle if they believe they have the upper hand. Until...", "The Orcs of Roz Káskrauz are war-like and aggressive, and while they prefer to remain within their stronghold, they will emerge from it to do battle if they believe they have the upper hand. Until..." }, { "Bûlkharar", "Bûlkharar", "The alap-nâri oxen dwell at Bûlkharar, beside the Hatokáli River. The atmosphere here is warm and smells of damp hair; an unpleasant combination, though the alap-nâri do not seem to mind.", "The alap-nâri oxen dwell at Bûlkharar, beside the Hatokáli River. The atmosphere here is warm and smells of damp hair; an unpleasant combination, though the alap-nâri do not seem to mind." } }
I.D[1879524271] = { "Scouting Pahar Hatokáli", "Scouting Pahar Hatokáli", 103, 150, 1000, 0, 0, "", "Explorador / Exploradora de las Colinas de Hatokáli", "Explore friendly settlements, structures, tombs, and other important points of interest in Pahar Hatokáli in Mûr Ghala.", "Explore friendly settlements, structures, tombs, and other important points of interest in Pahar Hatokáli in Mûr Ghala.", "", "Scout of Hatokáli Fells" }
I.O[1879524271] = { { "MGS Norte", "Hanamíku", "The village of Hanamíku serves as a way-station nestled among the rocks of Nêr Abatu, the Gate of Stones that stands between Idagâl and Pahar Hatokáli. It has been a place of peace during the years...", "The village of Hanamíku serves as a way-station nestled among the rocks of Nêr Abatu, the Gate of Stones that stands between Idagâl and Pahar Hatokáli. It has been a place of peace during the years..." }, { "Ingarûma", "Ingarûma", "The forces of Renewed Hamât have established the war camp of Ingarûma on a naturally rocky rise midway through Pahar Hatokáli. Many throughout the years have sought to establish camps here for the...", "The forces of Renewed Hamât have established the war camp of Ingarûma on a naturally rocky rise midway through Pahar Hatokáli. Many throughout the years have sought to establish camps here for the..." }, { "Shûmadir", "Shûmadir", "The great bridge of Shûmadir has fallen into disrepair over the years. Unless it is repaired, no army can easily pass this way.", "The great bridge of Shûmadir has fallen into disrepair over the years. Unless it is repaired, no army can easily pass this way." }, { "Kirzâmur", "Kirzâmur", "The farm of Kirzâmur was burned by the retreating Ordâkhai as they passed south, hoping to prevent its use by Mizâdi's forces. Now Ebnûr and Namtâru seek to maintain a cheerful disposition while they...", "The farm of Kirzâmur was burned by the retreating Ordâkhai as they passed south, hoping to prevent its use by Mizâdi's forces. Now Ebnûr and Namtâru seek to maintain a cheerful disposition while they..." }, { "Nar Makâru", "Nar Makâru", "Though long-abandoned by their builders, the water-wheels of Nar Makâru turn still. For what purpose do they now run, and on behalf of what commander?", "Though long-abandoned by their builders, the water-wheels of Nar Makâru turn still. For what purpose do they now run, and on behalf of what commander?" }, { "Sakhar Kishâsya", "Sakhar Kishâsya", "Little is remembered today of the tower of Sakhar Kishâsya, save that it was built long ago and is more ancient than the other structures in Pahar Hatokáli. It has sunk into the earth as a result of...", "Little is remembered today of the tower of Sakhar Kishâsya, save that it was built long ago and is more ancient than the other structures in Pahar Hatokáli. It has sunk into the earth as a result of..." }, { "Pagru-kirít", "Pagru-kirít", "In the Nêshakari tongue, Pagru-kirít means 'Garden of Corpses.' Perhaps that is enough to know of this place to which only the desperate should come willingly.", "In the Nêshakari tongue, Pagru-kirít means 'Garden of Corpses.' Perhaps that is enough to know of this place to which only the desperate should come willingly." }, { "Gates of Eshkhâbul", "Gates of Eshkhâbul", "The Gates of Eshkhâbul prevent passage further north and west, keeping the brigands that encamp upon the southern slope of Mûr Ghala from leaving and troubling other lands. This is of little comfort...", "The Gates of Eshkhâbul prevent passage further north and west, keeping the brigands that encamp upon the southern slope of Mûr Ghala from leaving and troubling other lands. This is of little comfort..." }, { "The Roaring Hatokáli", "The Roaring Hatokáli", "The sound booms in your ears as the Hatokáli River descends in an overwhelming torrent, rushing downstream with tremendous voice.", "The sound booms in your ears as the Hatokáli River descends in an overwhelming torrent, rushing downstream with tremendous voice." }, { "Khabur Pâshu", "Khabur Pâshu", "The small graveyard of Khabur Pâshu stands beneath the village of Hanamíku and has served as the final resting place of its people since the village was founded.", "The small graveyard of Khabur Pâshu stands beneath the village of Hanamíku and has served as the final resting place of its people since the village was founded." } }
